      ["mount"] = {
        [1] = "J'ai sorti {mount=mon|ma|mes|mes} {mount} pour la première fois, et pendant une lieue ou deux je me suis $gsenti:sentie; comme un des chevaliers des vieilles ballades de [[Stormwind City]].",
        [2] = "Un cheval à moi, enfin. J'ai mené {mount=mon|ma|mes|mes} {mount} le long de la route sans pouvoir m'empêcher de sourire.",
        [3] = "{mount=Mon|Ma|Mes|Mes} {mount} et moi avons pris la route pour la première fois, et les fermes défilaient plus vite que je ne les avais jamais vues.",
