      ["opening"] = {
        [1] = "Je me suis $gmis:mise; en route {at}, en me demandant quels ennuis auraient des droits sur moi avant la fin du jour.",
        [2] = "Les vieux soldats conseillaient de manger quand on peut et de se reposer quand on peut, et j'ai repris la route {at} en gardant les deux en tête.",
        [3] = "J'ai repris la route {at}, encore sensible à la promesse d'une vie tranquille quelque part au-delà.",
        [4] = "Il y avait une journée de travail à faire {at}, et j'étais d'humeur à la faire.",
        [5] = "{where} avait assez de courses pour une douzaine de personnes, et je comptais être l'une d'elles.",
        [6] = "J'ai continué {at}, les noms de ceux qui avaient besoin d'aide plus difficiles à ignorer que la distance.",
