    ["Tauren"] = {
      ["beginning"] = {
        [1] = "J'ai fait mes premiers pas {at}. Les tribus ne vivaient en paix à [[Mulgore]] que depuis que les centaures en avaient été chassés, et je ne comptais pas considérer cette paix comme acquise.",
