      ["d-close"] = {
        [1] = "Je marche plus doucement depuis ma mort, comme si la terre m'avait rappelé à qui elle appartient.",
        [2] = "Être $gpassé:passée; si près de ma propre fin m'a fait penser plus doucement aux fins que j'apporte aux autres.",
        [3] = "Il y a en ce monde des lieux qui ressemblent à des blessures de la terre, et je suis $gentré:entrée; dans l'un d'eux. J'espère l'avoir laissé un peu plus près de guérir.",
        [4] = "La mort m'a montré que la Terre-Mère est patiente avec ses enfants, et je préfère ne pas découvrir où s'arrête cette patience.",
