      ["d-react"] = {
        [1] = "Je ne chasse pas par haine, mais celui-là avait fait du tort à la terre et à ses gens, et je n'ai pas pleuré cette fin.",
        [2] = "Certains maux ne s'arrêtent que lorsqu'on les arrête, et c'est moi qui l'ai arrêté.",
        [3] = "Les anciens auraient appelé cela un juste usage de la force, et j'étais $gheureux:heureuse; d'avoir dépensé la mienne ainsi.",
        [4] = "Une vie ramenée saine et sauve pèse plus que n'importe quelle proie, et j'en ai senti la différence.",
