      ["d-spec"] = {
        [1] = "J'avais choisi la voie des [[spec:Arms]], une arme tenue avec la patience d'un chasseur des plaines.",
        [2] = "J'avais choisi la [[spec:Fury]], une ruée de troupeau déchaînée, mais tenue loin de tout ce qui ne la méritait pas.",
        [3] = "J'avais choisi la [[spec:Protection]], me tenant aussi large que je le suis entre le troupeau et le mal.",
