        [14] = "J'ai repris la route {at} après la tombée de la nuit, à l'écoute des pas feutrés de tout ce qui chassait à cette heure.",
        [15] = "La route {at} avait l'air assez amicale, et c'est, d'expérience, le moment de regarder à deux fois.",
        [16] = "Mes yeux sont allés au sol {at} à la recherche de scorpides, par simple habitude de [[Durotar]].",
        [17] = "Me revoilà en route {at}, les longues jambes d'abord et le bon sens traînant un peu derrière.",
        [18] = "Le jour {at} m'a $gtrouvé:trouvée; $greposé:reposée; et $gprêt:prête; à aimer ce qui viendrait, ce que tout le monde chez moi demande à un matin.",
        [19] = "Je me suis $gélancé:élancée; {at} comme les pêcheurs poussent leur barque depuis le sable, d'un coup et sans regarder en arrière.",
        [20] = "Je suis $gparti:partie; {at} sans autre plan que le prochain tournant, ce qui m'a mieux $gservi:servie; que certains plans.",
        [21] = "J'étais d'humeur généreuse {at}, de celles qui font d'une longue route une sorte de visite.",
        [22] = "Chez moi, les nuits appartenaient aux tambours, alors l'obscurité {at} ressemblait plus à une invitation qu'à un avertissement.",
        [23] = "J'étais debout {at} avec mes deux défenses, tous mes membres et l'essentiel de mes esprits, ce que je tenais pour un bon début.",
        [24] = "Toute route pouvait mener quelque part de bon, à mon avis, et je suis $gparti:partie; {at} aussi $gplein:pleine; d'espoir que jamais.",
        [25] = "Les orcs {at} avaient été des étrangers autrefois et étaient désormais des voisins, ce qui me réchauffe encore le cœur.",
        [26] = "Personne ne m'avait encore demandé d'aller chercher quoi que ce soit quand je me suis $gmis:mise; en route {at}, et je comptais en profiter tant que ça durerait.",
      },
      ["rest"] = {
        [1] = "Je me suis $greposé:reposée; {at}, le dos contre quelque chose de solide, comme je l'aime.",
        [2] = "Rien ne me pressait {at}, et la vigilance du jour a quitté mes épaules.",
        [3] = "J'ai fait une pause {at}, le bruit de la mer presque présent dans le silence.",
        [4] = "Les ennuis du jour sont devenus plus drôles dès que je me suis $gassis:assise; {at}.",
        [5] = "Une heure dont la seule exigence était de rester $gassis:assise; tranquille : j'en étais $gheureux:heureuse; {at}.",
        [6] = "Je me suis $greposé:reposée; {at}, et les tambours de [[Sen'jin Village]] m'ont manqué plus que je ne l'aurais cru.",
        [7] = "Le calme {at} était bien loin du vacarme de chez moi, et je l'ai laissé tel quel.",
        [8] = "Ma curiosité a eu droit au repos {at}, en même temps que mes jambes.",
        [9] = "Ma patience n'ayant plus d'autre tâche que de ne rien faire, je lui ai confié cette tâche {at}.",
        [10] = "Mon corps avait beau guérir vite, la fatigue gardait son propre rythme, et je me suis $greposé:reposée; {at} jusqu'à ce qu'elle soit partie.",
        [11] = "Les endroits sûrs avaient été assez rares pour que je profite pleinement de celui-ci {at}, et je me suis $greposé:reposée; les deux yeux fermés.",
        [12] = "$gÉtendu:Étendue; {at}, j'étais aussi tranquille qu'un raptor au soleil.",
        [13] = "La fumée {at} a emporté la longue vigilance du jour, et je l'ai laissée partir.",
        [14] = "Je me suis $ginstallé:installée; {at}, et pour une fois rester immobile ressemblait à du repos et non à une planque.",
        [15] = "Je me suis $greposé:reposée; {at}, toujours en train de respirer, ce qui chez moi est une raison suffisante de faire la fête.",
        [16] = "$gContent:Contente; de n'être utile à rien un moment, je me suis $greposé:reposée; {at} en n'écoutant rien de particulier.",
        [17] = "Je me suis $gassis:assise; près du feu {at}, et j'ai décidé qu'il ne lui manquait qu'un tambour et quelques amis de chez moi pour être parfait.",
        [18] = "Je me suis $greposé:reposée; {at}, en m'offrant la pensée de crabes ouverts sur un rocher chaud au bord de la mer.",
        [19] = "La fatigue est venue lentement {at}, et je ne l'ai pas contredite.",
        [20] = "Je me suis $gassis:assise; {at}, secrètement $gamusé:amusée; de tout l'effort qu'il avait fallu pour trouver où m'asseoir.",
      },
      ["riding"] = {
        [1] = "J'ai appris à monter, et j'avais hâte de découvrir à quelle vitesse une monture à moi pouvait vraiment aller.",
        [2] = "Les leçons d'équitation ont été le plus grand plaisir que j'aie eu depuis des semaines, et je ne m'en suis pas $gcaché:cachée;.",
      },
      ["summit"] = {
        [1] = "J'ai atteint le niveau {level}, et les [[Echo Isles]] n'étaient plus les seuls rivages qui signifiaient « chez moi ».",
        [2] = "Au niveau {level}, j'avais plus à rapporter chez moi que le récit d'une survie.",
        [3] = "J'ai atteint le niveau {level}, en espérant que [[Sen'jin Village]] trouverait de quoi sourire dans la vie que je m'étais faite.",
      },
    },
  },
  scenery = {
    ["Aerie Peak"] = {
      [1] = "[[Aerie Peak]] était taillé dans la montagne, foyer des nains Wildhammer et de leurs griffons, et le vent le traversait de part en part.",
      [2] = "[[Aerie Peak]] était une place forte des Wildhammer perchée sur la montagne, et ses chevaucheurs de griffon voyaient tout ce qui bougeait, moi $gcompris:comprise;.",
    },
    ["Ahn'Qiraj Temple"] = {
      [1] = "[[Ahn'Qiraj Temple]] s'enfonçait dans le noir, les salles d'un empire d'insectes, et quelque chose de très ancien attendait tout au fond.",
    },
    ["Alterac Mountains"] = {
      [1] = "La neige et la pierre éboulée emplissaient [[Alterac Mountains]], où les ruines d'un royaume déchu gisaient à demi ensevelies. Les ogres tenaient désormais la vieille cité, et le Syndicat tenait les routes.",
      [2] = "La nuit, le vent descendait des sommets d'Alterac, tranchant comme une lame. Il y avait parmi les ruines des endroits dont je ne voulais rien savoir.",
    },
    ["Arathi Highlands"] = {
      [1] = "[[Arathi Highlands]] ondulaient sous un ciel immense, semées des ruines de Stromgarde et des pierres levées de temps plus anciens. Ogres, trolls et pillards s'étaient tous taillé leur part de la contrée.",
      [2] = "La nuit, [[Arathi Highlands]] étaient froides et vastes, les cercles de pierres levées noirs contre les étoiles. Quels que soient les royaumes qui s'étaient dressés là, le vent leur avait survécu à tous.",
    },
    ["Ashenvale"] = {
      [1] = "[[Ashenvale]] était la vieille forêt de mon peuple, haute et silencieuse, ses puits de lune cachés parmi les arbres. Les haches de la Horde en avaient atteint les lisières, et je ne pouvais regarder les souches sans colère.",
      [2] = "Sous la lune, [[Ashenvale]] semblait telle qu'elle avait toujours dû être, argentée et immobile. Puis j'ai pensé aux camps le long de ses frontières, et à la proximité des haches.",
      [3] = "Les arbres de [[Ashenvale]] étaient immenses et anciens, et la lumière qui les traversait tombait bleue et verte. C'était beau, et c'était disputé : des sentinelles gardaient les clairières.",
      [4] = "[[Ashenvale]] était dense, belle et hostile, et chaque arbre pouvait cacher une sentinelle. Nos camps de bûcherons étaient rares et dispersés, et la forêt semblait vouloir les chasser.",
    },
    ["Astranaar"] = {
      [1] = "[[Astranaar]] se dressait sur son île au milieu du lac, ses bâtiments elfiques pâles parmi les arbres, et ses sentinelles surveillaient sans cesse la rive.",
      [2] = "[[Astranaar]] se tenait sur son île au milieu du lac, cernée de sentinelles, et j'étais $gun ennemi:une ennemie;.",
    },
    ["Auberdine"] = {
      [1] = "Une brume marine grise flottait sur les jetées de [[Auberdine]], et les bateaux allaient et venaient à travers elle sans se presser. Je voyais bien comment une attente sur ce rivage pouvait s'étirer sur des jours.",
      [2] = "Les navires amarrés à [[Auberdine]] disaient clairement à qui appartenait ce rivage. J'ai admiré l'abri des jetées, sans m'attendre à y être $gbien accueilli:bien accueillie;.",
    },
    ["Azshara"] = {
      [1] = "L'automne régnait partout en [[Azshara]], des arbres rouges et dorés autour des ruines brisées des anciens elfes. C'était beau d'une beauté qui ressemblait à un deuil.",
      [2] = "La nuit, les ruines de [[Azshara]] se dressaient pâles parmi les arbres, et la mer au-delà était très sombre. L'endroit semblait se souvenir encore de la reine dont il portait le nom.",
    },
    ["Badlands"] = {
      [1] = "[[Badlands]] n'étaient que poussière et roche rouge sous un soleil sans pitié. Les os de grands dragons gisaient à demi enfouis dans les canyons, et rien n'y poussait qui n'eût des épines.",
      [2] = "[[Badlands]] se rafraîchissaient vite après la tombée de la nuit, les canyons noirs et les étoiles dures et proches. Quelque part, un coyote a appelé, et l'écho est revenu de trois côtés à la fois.",
    },
    ["Blackfathom Deeps"] = {
      [1] = "L'eau de mer avait gravi les marches du temple dans [[Blackfathom Deeps]] et y était restée. Chaque bruit portait dans les salles noyées, alors j'écoutais avant de bouger.",
    },
    ["Blackrock Depths"] = {
      [1] = "[[Blackrock Depths]] étaient une cité entière sous la montagne, le royaume de forges et de lave des nains Sombrefer. Sa chaleur montait à travers la pierre sous mes pieds.",
    },
    ["Blackrock Spire"] = {
      [1] = "[[Blackrock Spire]] s'élevait à l'intérieur de la montagne, forteresse d'orcs, d'ogres et de draconiens, sous les bannières des dragons noirs qui pendaient partout.",
    },
    ["Blackwing Lair"] = {
      [1] = "[[Blackwing Lair]] se trouvait au sommet de [[Blackrock Spire]], les salles de Nefarian, pleines de dragons, d'expériences et de cages.",
    },
    ["Blasted Lands"] = {
      [1] = "[[Blasted Lands]] n'étaient que terre rouge et morte sous un ciel maladif, et au sud la Porte des ténèbres se dressait en silence. Tout ici avait brûlé un jour et ne s'en était jamais remis.",
      [2] = "La nuit, [[Blasted Lands]] semblaient luire, comme si le sol se souvenait du gangrefeu. La Porte des ténèbres surgissait de l'obscurité, et il était difficile de ne pas se sentir $gobservé:observée;.",
    },
    ["Bloodhoof Village"] = {
      [1] = "[[Bloodhoof Village]] déployait ses grandes tentes le long de la rivière, des kodos se reposant tout près, et j'y suis $gentré:entrée; comme si j'en avais toujours connu le chemin.",
      [2] = "[[Bloodhoof Village]] était un rassemblement de grandes tentes au bord de la rivière, avec des kodos au repos tout près et une odeur de cuisine dans l'air.",
      [3] = "[[Bloodhoof Village]] était un village tauren dans l'herbe ouverte, sans murs et sans en avoir besoin, pas même contre moi.",
    },
    ["Booty Bay"] = {
      [1] = "[[Booty Bay]] était bâtie dans les falaises autour d'un port caché, tout en planches, en cordages et en marchandages gobelins, avec une immense mâchoire de requin pour porte. Ici, tout le monde était à vendre, et personne ne prétendait le contraire.",
    },
    ["Brackenwall Village"] = {
      [1] = "[[Brackenwall Village]] se tassait dans le marais, un camp de la Horde aux huttes sur pilotis au-dessus de la boue et des insectes.",
      [2] = "[[Brackenwall Village]] était un camp de la Horde dans le marais, ses huttes sur pilotis et ses gardes peu engageants.",
    },
    ["Brill"] = {
      [1] = "Après les tombeaux, les toits de guingois de [[Brill]] paraissaient presque amicaux. Autour de [[Gallows' End Tavern]], les miens vaquaient à leurs affaires, et la ville tenait debout par pur entêtement.",
      [2] = "À [[Brill]], les morts tenaient boutique et faisaient leurs courses sous des toits de guingois. Je m'attendais à des tombes, bien moins à cela.",
    },
    ["Burning Steppes"] = {
      [1] = "La cendre tombait comme neige sur [[Burning Steppes]], et le sol fumait encore. [[Blackrock Mountain]] dominait le tout, et les orcs qui le tenaient avaient fait de toute la contrée la leur.",
      [2] = "[[Burning Steppes]] ne s'obscurcissaient jamais tout à fait. Des feux brûlaient à travers la plaine, et la lueur rouge de [[Blackrock Mountain]] pendait dans le ciel comme une menace.",
    },
    ["Camp Mojache"] = {
      [1] = "[[Camp Mojache]] était un camp tauren à la lisière de [[Feralas]], ses grandes tentes déployées dans l'herbe.",
      [2] = "[[Camp Mojache]] était un camp tauren à l'orée de la forêt, et ses braves avaient l'air de gens qui n'accueilleraient pas aimablement des étrangers comme moi.",
    },
    ["Camp Taurajo"] = {
      [1] = "[[Camp Taurajo]] était un camp tauren dans le sud de [[The Barrens]], ses tentes et ses totems dressés au-dessus de l'herbe.",
      [2] = "[[Camp Taurajo]] était un camp tauren dans l'herbe ouverte, et je ne m'attendais pas à ce que quiconque y soit heureux de me voir.",
    },
    ["Cenarion Hold"] = {
      [1] = "[[Cenarion Hold]] était un camp fortifié dans le sable de [[Silithus]], où le Cercle cénarien montait la garde contre les ruches.",
    },
    ["Chillwind Camp"] = {
      [1] = "[[Chillwind Camp]] n'était qu'une poignée de tentes sous les arbres à l'orée des Maleterres, où l'Alliance gardait un pied face au Fléau.",
      [2] = "[[Chillwind Camp]] était un camp de l'Alliance à l'orée du pays pestiféré, et je ne pouvais pas attendre de ses soldats qu'ils m'aiment davantage que le Fléau.",
    },
    ["Darkshire"] = {
      [1] = "[[Darkshire]] se blottissait sous ses lanternes à l'orée du bois sombre, avec le Guet de nuit à chaque coin de rue. La forêt pressait le bourg de tous côtés.",
      [2] = "[[Darkshire]] était un bourg éclairé et gardé contre l'obscurité, et je ne doutais pas qu'il le soit aussi contre ceux de mon espèce. Ses lanternes laissaient bien peu d'ombres.",
    },
    ["Darkshore"] = {
      [1] = "La brume montait de la mer le long de [[Darkshore]], et de vieilles pierres gisaient à demi enfouies dans le sable gris. Même les arbres avaient l'air las, et je me suis $gsurpris:surprise; à chercher une lumière sur le rivage.",
      [2] = "La nuit, à [[Darkshore]], la brume ne faisait plus de la mer et du ciel qu'une seule chose grise. Je gardais mes repères au bruit du ressac et à la lune floue au-dessus.",
    },
    ["Darnassus"] = {
      [1] = "La pierre blanche et les bassins immobiles de [[Darnassus]] m'ont $gralenti:ralentie; sans que je le veuille. Près de [[Temple of the Moon]], le vieux silence s'est refermé sur moi, et j'étais chez moi.",
      [2] = "J'ai baissé la voix à [[Darnassus]] sans que personne me le demande. La pierre pâle et l'eau tranquille semblaient bien loin du rythme de la route en contrebas.",
      [3] = "À [[Darnassus]], la pierre pâle retenait une eau immobile. J'aurais pu admirer ce calme, s'il n'avait pas rendu chacun de mes pas trop bruyant.",
    },
    ["Deadwind Pass"] = {
      [1] = "[[Deadwind Pass]] était mort en tout point, des arbres gris sur de la roche grise, et la tour de [[Karazhan]] se dressait seule dans la pénombre. Personne parmi ceux que j'avais croisés ne pouvait dire ce qui vivait encore à l'intérieur.",
      [2] = "La nuit, [[Deadwind Pass]] était plus froid qu'il n'avait le droit de l'être. La tour de [[Karazhan]] se dressait, noire, au-dessus du ravin, et le vent dans les arbres morts ressemblait presque à des voix.",
    },
    ["Desolace"] = {
      [1] = "[[Desolace]] était grise d'un bout à l'autre : terre craquelée, vieux ossements et camps de centaures en guerre. Quelque chose avait vidé cette terre de sa vie, et elle n'était jamais revenue.",
      [2] = "La nuit en [[Desolace]] était froide, vide et très calme. Les tambours des centaures portaient loin, et les hurlements aussi.",
    },
    ["Dire Maul"] = {
      [1] = "[[Dire Maul]] était la ruine d'une cité elfe dans la forêt, ses grandes salles envahies par la végétation, hantées encore par leurs anciens maîtres, et des ogres vivaient dans les décombres.",
    },
    ["Dolanaar"] = {
      [1] = "Les feuilles et l'eau dormante parfumaient les maisons autour du puits de lune de [[Dolanaar]]. Les sentinelles montaient leur garde patiente sur la route, et j'ai un peu baissé la garde.",
      [2] = "Le puits de lune bleu de [[Dolanaar]] a attiré mon regard avant les maisons. Sous les lianes retombantes, je me suis $gsurpris:surprise; à parler bas, comme si quelqu'un me l'avait demandé.",
    },
    ["Dun Morogh"] = {
      [1] = "Le froid de [[Dun Morogh]] m'a $gsaisi:saisie; à la gorge, et les pins ployaient sous leur neige. Au-dessus des vallées se dressait la montagne qui abrite [[Ironforge]], et sa vue rendait le froid plus facile à supporter.",
      [2] = "La neige de Dun Morogh luisait de bleu sous les étoiles, et le froid en paraissait plus pur. Je reconnaissais la silhouette de ces montagnes, même dans le noir.",
      [3] = "Le froid de [[Dun Morogh]] a trouvé mes doigts avant tout le reste. Devant moi, la porte de [[Ironforge]] s'enfonçait dans la montagne, comme si les nains avaient convaincu la pierre de leur faire de la place.",
      [4] = "Une neige épaisse couvrait [[Dun Morogh]], et la montagne de [[Ironforge]] se dressait devant moi. Je me suis $gdemandé:demandée; combien de nains attendaient derrière toute cette pierre.",
    },
    ["Durotar"] = {
      [1] = "La chaleur montait de la poussière rouge de [[Durotar]], comme si le sol lui-même respirait. C'était la terre que nous avions revendiquée, et je comptais apprendre à lui appartenir.",
      [2] = "La terre rouge de [[Durotar]] virait au gris à mesure que la chaleur quittait les pierres. Par-delà les collines venaient les tambours de [[Orgrimmar]], un son que j'aurais pu suivre les yeux fermés.",
      [3] = "En [[Durotar]], les collines rouges se refermaient sur la route de [[Orgrimmar]]. Sous ce soleil, j'ai commencé à comprendre le peuple qui avait choisi de rester.",
      [4] = "Un vent brûlant me jetait au visage la poussière rouge de [[Durotar]]. C'était le pays même de la Horde, et j'ai cessé de croire les crêtes désertes.",
    },
    ["Duskwood"] = {
      [1] = "[[Duskwood]] était sombre même à midi, les arbres si serrés que le soleil atteignait à peine la route. Des choses bougeaient dans les cimetières, et les gens de [[Darkshire]] avaient cessé de faire semblant de ne pas les voir.",
      [2] = "La nuit dans [[Duskwood]] était une nuit plus noire que les autres. Des worgs hurlaient entre les arbres, et sur [[Raven Hill]] les morts ne restaient pas là où on les avait enterrés.",
    },
    ["Dustwallow Marsh"] = {
      [1] = "[[Dustwallow Marsh]] était chaud, humide et bourdonnant d'insectes, sa boue pleine de crocilisques et ses arbres lourds de mousse. Les tours de [[Theramore Isle]] sur la côte semblaient bien loin du marécage.",
      [2] = "La nuit, [[Dustwallow Marsh]] s'éveillait de coassements et de clapotis, et la brume montait de l'eau par nappes. Quelque part au sud se trouvait le repaire d'Onyxia, et je ne pouvais pas m'empêcher d'y penser.",
    },
    ["Eastern Plaguelands"] = {
      [1] = "[[Eastern Plaguelands]] étaient une terre sans couleur, aux arbres gris, aux rivières souillées et au sol amolli par la peste. Les murs de [[Stratholme]] se dressaient au nord, et rien de vivant n'y allait de son plein gré.",
      [2] = "[[Eastern Plaguelands]] étaient plus sombres qu'aucune nuit ne devrait l'être. Des choses marchaient parmi les arbres morts, et la seule lumière bienveillante venait de [[Light's Hope Chapel]], minuscule dans le noir.",
    },
    ["Elwynn Forest"] = {
      [1] = "[[Elwynn Forest]] était verte et bien ordonnée, des fermes nichées entre les chênes et les gardes de [[Stormwind City]] patrouillant sur les routes. Dans un tel pays, il était facile d'oublier à quel point les ennuis étaient proches.",
      [2] = "[[Elwynn Forest]] était calme la nuit, des lanternes le long de la route et les arbres sombres de chaque côté. Quelque part dans les bois, un loup a appelé, et le prochain réverbère a été le bienvenu.",
      [3] = "[[Elwynn Forest]] était une terre douce, toute en chênes, en prairies et en champs bien tenus, les murs de [[Stormwind City]] jamais bien loin. On aurait dit un endroit pour lequel des gens s'étaient battus afin qu'il reste ordinaire.",
      [4] = "La forêt montait jusqu'aux murs de [[Stormwind City]], et chaque route avait sa patrouille. C'était un joli pays et le cœur de l'Alliance, et j'ai senti peser sur moi chacune de ces patrouilles.",
    },
    ["Everlook"] = {
      [1] = "[[Everlook]] était une ville gobeline dans la neige, ses rues pleines de marchands venus de très loin.",
    },
    ["Feathermoon Stronghold"] = {
      [1] = "[[Feathermoon Stronghold]] se dressait sur son île au large de la côte de [[Feralas]], une forteresse elfe qu'on rejoignait en bateau ou à dos d'hippogriffe.",
      [2] = "[[Feathermoon Stronghold]] se dressait sur son île, et ses sentinelles ne verraient pas d'un bon œil des visiteurs de mon espèce.",
    },
    ["Felwood"] = {
      [1] = "[[Felwood]] avait été une forêt autrefois, et par endroits il l'était encore, mais les arbres étaient tordus et l'eau luisait de vert. La corruption des démons était partout, jusque dans l'air.",
      [2] = "[[Felwood]] était pire la nuit, quand la lueur verte des mares souillées était la seule lumière. Les arbres craquaient comme s'ils souffraient.",
    },
    ["Feralas"] = {
      [1] = "[[Feralas]] était verte et immense, avec des arbres aussi hauts que ceux de [[Ashenvale]] et les ruines des anciens elfes enfoncées parmi les fougères. L'air était épais, humide, et sentait la pousse.",
      [2] = "La nuit, [[Feralas]] était profonde et ruisselante, la canopée si épaisse que les étoiles s'y perdaient. Quelque part dans le noir se trouvaient les murs de [[Dire Maul]], et plus près, les cris de bêtes que je ne savais pas nommer.",
    },
    ["Freewind Post"] = {
      [1] = "[[Freewind Post]] se tenait au sommet d'une aiguille de pierre, accessible par un monte-charge grinçant, tout le canyon étalé en contrebas.",
      [2] = "[[Freewind Post]] se tenait au sommet d'une aiguille de pierre, accessible seulement par son monte-charge, et ses gardes avaient l'air d'avoir déjà vu des gens de mon espèce.",
    },
    ["Gadgetzan"] = {
      [1] = "[[Gadgetzan]] était une ville gobeline au milieu du désert, ceinte de murs et bruyante, avec à chaque coin un cogneur qui maintenait une paix d'un genre très particulier.",
    },
    ["Gnomeregan"] = {
      [1] = "Les salles de [[Gnomeregan]] étaient telles qu'on me les avait décrites. Parmi les troggs et la lueur empoisonnée, je ne pouvais m'empêcher de penser aux gnomes qui y avaient vécu.",
      [2] = "Les machines de [[Gnomeregan]] tournaient encore dans des salles que leurs créateurs avaient perdues. Sous la lumière d'un vert maladif, je me demandais qui arrêterait jamais les rouages.",
    },
    ["Goldshire"] = {
      [1] = "[[Goldshire]] se rassemblait autour de [[Lion's Pride Inn]], et la route qui le traversait semblait la plus sûre du monde.",
      [2] = "[[Goldshire]] était une petite ville douillette de l'Alliance autour de son auberge, avec des gardes à chaque coin, et pas un ne m'aurait $gvu:vue; d'un bon œil.",
    },
    ["Grom'gol Base Camp"] = {
      [1] = "[[Grom'gol Base Camp]] était un camp de la Horde taillé dans la jungle, une tour à zeppelins dominant les arbres et la jungle qui le pressait de tous côtés.",
      [2] = "[[Grom'gol Base Camp]] était un camp de la Horde dans la jungle, sa tour à zeppelins visible de loin, et chaque grunt qui s'y trouvait était mon ennemi.",
    },
    ["Hammerfall"] = {
      [1] = "[[Hammerfall]] se dressait, austère et pavoisé de rouge, parmi les collines d'Arathi, une place forte orque dans un pays que les humains disaient encore le leur.",
      [2] = "[[Hammerfall]] était une place forte orque dans les collines d'Arathi, tout en murs hérissés de pointes et en regards aux aguets, et ici, c'était moi $gl'ennemi:l'ennemie;.",
    },
    ["Hillsbrad Foothills"] = {
      [1] = "[[Hillsbrad Foothills]] étaient verts et leurs vergers lourds de fruits, mais [[Southshore]] et [[Tarren Mill]] se faisaient face, et chacun le savait. Les vieilles fermes étaient devenues une ligne de front.",
      [2] = "[[Hillsbrad Foothills]] étaient inquiets la nuit, chaque camp tenant une ville de part et d'autre de la vallée, et aucune des deux en paix.",
    },
    ["Ironclad Cove"] = {
      [1] = "Le tunnel débouchait sur une crique cachée, et sur l'eau reposait un vrai navire, cuirassé et hérissé de canons, construit en secret sous [[Westfall]]. J'ai compris alors tout ce que VanCleef avait préparé.",
      [2] = "L'air marin m'est parvenu avant que je voie la crique. Un grand cuirassé mouillait dans le port caché, ses ponts grouillant de pirates, et j'avais peine à croire qu'on l'ait construit sous terre.",
    },
    ["Ironforge"] = {
      [1] = "La chaleur de [[The Great Forge]] m'a $gaccueilli:accueillie; dès la porte de [[Ironforge]], et le martèlement m'a $gsuivi:suivie; à l'intérieur. Je me suis $gtenu:tenue; au-dessus du fer en fusion et j'ai laissé le vacarme de mon peuple remplir le vide que la route avait laissé.",
      [2] = "Après le froid de la montagne, la chaleur de [[Ironforge]] était presque trop forte. Les marteaux résonnaient dans chaque salle, et j'ai trouvé ce bruit étrangement réconfortant après la rase campagne.",
      [3] = "La montagne s'est refermée sur moi à [[Ironforge]], le martèlement venant de chaque salle. Il y avait des gardes partout, et la chaleur ne suffisait pas à me mettre à l'aise.",
    },
    ["Kargath"] = {
      [1] = "[[Kargath]] était creusé dans les parois du canyon de [[Badlands]], un avant-poste austère de la Horde qui portait le nom d'un rude guerrier.",
      [2] = "[[Kargath]] était un avant-poste de la Horde creusé dans les parois du canyon, tout en tours de guet, et chacune regardait dans ma direction.",
    },
    ["Kharanos"] = {
      [1] = "J'ai senti l'odeur de [[Thunderbrew Distillery]] avant même d'atteindre vraiment [[Kharanos]]. La fumée montait au-dessus des maisons, où nains et gnomes se serraient contre le froid, et mes épaules se sont détendues à ce spectacle.",
      [2] = "L'odeur de la brasserie m'a $gatteint:atteinte; sur la route de [[Kharanos]]. Parmi les maisons trapues, j'ai vu des gnomes autant que des nains, et j'ai pensé à la façon dont un foyer perdu peut suivre son peuple.",
      [3] = "La fumée flottait sur [[Kharanos]], et l'odeur de bière portait bien au-delà des maisons. Pour quelqu'un d'autre, c'était peut-être la promesse d'un accueil. Moi, je me suis $gsurpris:surprise; à compter les nains.",
    },
    ["Lakeshire"] = {
      [1] = "[[Lakeshire]] s'étendait au bord de [[Lake Everstill]], son grand pont toujours inachevé et ses habitants fatigués. La ville avait l'air d'un endroit qui tenait bon.",
      [2] = "Le pont de [[Lakeshire]] était gardé, et toute la ville surveillait les collines. Je sentais qu'elle me surveillait aussi.",
    },
    ["Light's Hope Chapel"] = {
      [1] = "[[Light's Hope Chapel]] se dressait seule au milieu de [[Eastern Plaguelands]], ses pierres encore propres et l'[[faction:Argent Dawn]] montant la garde alentour. Des vivants de toute sorte se rassemblaient au pied de ses murs, faute d'autre endroit où aller.",
    },
    ["Loch Modan"] = {
      [1] = "L'eau bleue de [[Loch Modan]] dormait derrière [[Stonewrought Dam]]. Je savais que les nains bâtissaient en grand, mais le poids de toute cette eau m'a $gforcé:forcée; à m'arrêter pour regarder.",
      [2] = "La nuit, l'eau de [[Loch Modan]] s'étendait, noire, sous les collines, et le barrage traçait une ligne plus sombre contre le ciel. [[Thelsamar]] dormait le long de la rive, et je l'enviais.",
      [3] = "De l'autre côté de [[Loch Modan]] se dressait le grand barrage des nains. Je surveillais les gardes le long de l'eau d'aussi près que le paysage.",
    },
    ["Maraudon"] = {
      [1] = "[[Maraudon]] était une caverne de cristal et d'eau empoisonnée, demeure des morts sacrés des centaures et de quelque chose de bien plus ancien en dessous. Plus on s'y enfonçait, plus tout devenait vert.",
    },
    ["Marshal's Refuge"] = {
      [1] = "[[Marshal's Refuge]] était un camp niché dans l'entrée d'une grotte au bord du cratère, où quelques âmes robustes vivaient parmi les dinosaures.",
    },
    ["Menethil Harbor"] = {
      [1] = "[[Menethil Harbor]] était une forteresse au bord du marais, son donjon à demi enfoncé dans la boue et ses quais animés de navires en partance pour Kalimdor.",
      [2] = "Le donjon et les quais de [[Menethil Harbor]] grouillaient de soldats de l'Alliance qui allaient et venaient par la mer, et chacun d'eux était mon ennemi.",
    },
    ["Molten Core"] = {
      [1] = "[[Molten Core]] s'étendait tout au fond de [[Blackrock Mountain]], une caverne de feu où Ragnaros en personne attendait. La chaleur donnait l'impression d'entrer dans une forge.",
    },
    ["Moonbrook"] = {
      [1] = "[[Moonbrook]] avait été une ville autrefois. Désormais, ses maisons se dressaient, brûlées et brisées, et des hommes coiffés de bandanas rouges surveillaient la route depuis les ruines.",
      [2] = "Après la tombée de la nuit, [[Moonbrook]] n'était plus qu'une ruine, ses murs brisés noirs contre le ciel. Les Défias étaient quelque part parmi les maisons brûlées, et je restais dans l'ombre.",
    },
    ["Moonglade"] = {
      [1] = "[[Moonglade]] était paisible comme nulle part ailleurs au monde, un lac tranquille dans un crépuscule sans fin, où des druides marchaient lentement au bord de l'eau. Même mes pensées s'y faisaient plus douces.",
      [2] = "La nuit à [[Moonglade]] différait à peine du jour, la même lumière douce sur le lac et le même calme. Là-bas, je ne guettais pas de pas derrière moi.",
    },
    ["Morgan's Vigil"] = {
      [1] = "[[Morgan's Vigil]] était un petit camp de l'Alliance à l'orée de [[Burning Steppes]], qui tenait bon face aux orcs de [[Blackrock Mountain]].",
      [2] = "[[Morgan's Vigil]] était un camp de l'Alliance à l'orée des Steppes, et ma venue n'avait pas pu rendre leur veille plus facile.",
    },
    ["Mulgore"] = {
      [1] = "L'herbe de [[Mulgore]] ondulait jusqu'aux mesas, parcourue de trotteurs des plaines, et le vent la traversait comme de l'eau. La terre de la Terre-Mère ne me demandait rien d'autre que de la fouler avec douceur.",
      [2] = "La nuit sur [[Mulgore]] était vaste et claire, les étoiles descendant jusqu'au bord de l'herbe. Les tentes de la tribu luisaient ici et là, et la terre semblait monter la garde.",
      [3] = "Les plaines de [[Mulgore]] ondulaient, vertes et dorées, au pied des mesas, avec des kodos qui paissaient et des moulins à vent qui tournaient près des tentes. C'était le pays le plus paisible que j'aie vu depuis longtemps.",
      [4] = "Les plaines de [[Mulgore]] s'ouvraient dans toutes les directions, sans nulle part où se cacher. C'était la terre des taurens, et je me sentais comme $gun étranger:une étrangère; qui traverse la maison de quelqu'un.",
    },
    ["Naxxramas"] = {
      [1] = "[[Naxxramas]] flottait au-dessus des Maleterres, la nécropole de Kel'Thuzad, et de ses salles glacées sortaient les morts en marche.",
    },
    ["Nethergarde Keep"] = {
      [1] = "[[Nethergarde Keep]] montait la garde sur [[Blasted Lands]], ses mages surveillant la Porte des ténèbres comme si elle pouvait se rouvrir à tout instant.",
      [2] = "[[Nethergarde Keep]] était une forteresse de l'Alliance pleine de mages qui surveillaient la Porte. Je me sentais $gsurveillé:surveillée; d'aussi près.",
    },
    ["Nighthaven"] = {
      [1] = "[[Nighthaven]] était un village de druides au bord du lac, paisible et ouvert, où quiconque venait en paix était le bienvenu.",
    },
    ["Nijel's Point"] = {
      [1] = "[[Nijel's Point]] était un petit camp de l'Alliance dans les collines au-dessus de [[Desolace]], où un peu de verdure s'accrochait encore aux pentes.",
      [2] = "[[Nijel's Point]] était un camp de l'Alliance dans les collines, un endroit dangereux pour quelqu'un de mon espèce.",
    },
    ["Onyxia's Lair"] = {
      [1] = "[[Onyxia's Lair]] était une grotte dans le marais, jonchée d'os et pleine de dragonnets. Je me suis $gtu:tue; à son entrée.",
    },
    ["Orgrimmar"] = {
      [1] = "Les tambours de [[Orgrimmar]] résonnaient contre les murs hérissés de pointes quand je suis $gentré:entrée;. À [[Grommash Hold]], j'en ai senti tout le poids : une cité que notre peuple avait bâtie pour lui-même, sans les chaînes de personne.",
      [2] = "La fumée flottait sur la pierre rouge et les pointes de fer de [[Orgrimmar]]. Les tambours faisaient de la fierté du lieu une chose que je sentais presque sous mes pieds.",
      [3] = "Au pied des murs de [[Orgrimmar]], les tambours roulaient sur la pierre rouge. Je ne m'étais jamais $gsenti:sentie; aussi loin de quiconque aurait pu m'appeler son ami.",
    },
    ["Ragefire Chasm"] = {
      [1] = "Le feu courait dans la roche de [[Ragefire Chasm]], juste sous notre cité. Que la [[faction:Burning Blade]] puisse se cacher si près de chez nous me troublait plus que l'obscurité.",
      [2] = "Le magma éclairait [[Ragefire Chasm]] par en dessous. Je devais sans cesse me rappeler de regarder le sol plutôt que le feu.",
    },
    ["Ratchet"] = {
      [1] = "[[Ratchet]] était un port gobelin sur la côte de [[The Barrens]], tout en quais, en grues et en marchandages, avec le bateau pour [[Booty Bay]] qui allait et venait.",
    },
    ["Razor Hill"] = {
      [1] = "À [[Razor Hill]], la caserne et la tour de guet dominaient la route, et des navires de Kul Tiras mouillaient au large. J'ai compris pourquoi la ville ne semblait jamais tranquille.",
      [2] = "La caserne et les tours de guet de [[Razor Hill]] dominaient la côte. Avec tant d'armes en vue, ce n'était manifestement pas une ville en paix.",
    },
    ["Razorfen Downs"] = {
      [1] = "[[Razorfen Downs]] formaient un tertre d'épines et d'ossements, où les huran avaient fait cause commune avec le Fléau. Les morts y marchaient aux côtés des vivants.",
    },
    ["Razorfen Kraul"] = {
      [1] = "[[Razorfen Kraul]] était un dédale d'épines géantes, les terriers des huran creusés profondément en dessous. Les ronces lacéraient tout ce qui passait.",
    },
    ["Redridge Mountains"] = {
      [1] = "La roche rouge se dressait autour de [[Lake Everstill]] dans [[Redridge Mountains]], et le pont de [[Lakeshire]] portait plus de soldats que de voyageurs. Les gnolls et les orcs de [[Blackrock Mountain]] s'étaient installés dans les collines, et la vallée avait l'air d'un pays assiégé.",
      [2] = "Le lac de [[Redridge Mountains]] s'étendait, noir, sous les collines rouges, et les crêtes au-dessus ressemblaient à un pays qu'aucun ami ne tenait.",
    },
    ["Refuge Pointe"] = {
      [1] = "[[Refuge Pointe]] était un camp sur une hauteur rocheuse, où les derniers habitants de Stromgarde faisaient encore flotter leurs bannières au-dessus des hautes-terres.",
      [2] = "[[Refuge Pointe]] se dressait sur son rocher au-dessus des hautes-terres, un camp de l'Alliance qui avait l'œil sur chaque approche, la mienne comprise.",
    },
    ["Revantusk Village"] = {
      [1] = "[[Revantusk Village]] se dressait sur la côte de [[The Hinterlands]], un village troll de huttes et de totems où les trolls Revantusk avaient pris le parti de la Horde.",
      [2] = "[[Revantusk Village]] était un village troll sur la côte, fidèle à la Horde, et il n'était pas de mes amis.",
    },
    ["Ruins of Ahn'Qiraj"] = {
      [1] = "[[Ruins of Ahn'Qiraj]] s'étendaient dans le sable au-delà du mur du Scarabée, des tours brisées et des silithides partout.",
    },
    ["Scarlet Monastery"] = {
      [1] = "[[Scarlet Monastery]] était beau et terrible, tout en bannières rouges et en sols polis, et les croisés qui s'y trouvaient étaient sûrs de leur cause. J'ai été mal à l'aise dès que je suis $gentré:entrée;.",
    },
    ["Scholomance"] = {
      [1] = "[[Scholomance]] avait été le donjon de la famille Barov avant de devenir une école de nécromanciens. Ses salles sentaient la poussière, la mort et les vieux livres.",
    },
    ["Searing Gorge"] = {
      [1] = "[[Searing Gorge]] était une plaie dans la terre, roche noire, scories rougeoyantes et puanteur de soufre. Les nains Sombrefer l'avaient exploitée jusqu'à n'y laisser que la chaleur.",
      [2] = "Dans [[Searing Gorge]], la nuit importait à peine. La lave éclairait les falaises par en dessous, et [[The Cauldron]] en son cœur luisait comme un second soleil.",
    },
    ["Sentinel Hill"] = {
      [1] = "Une tour de pierre se dressait sur [[Sentinel Hill]], et autour d'elle la Milice populaire, des fermiers qui avaient tout perdu, avait planté ses tentes. Je les ai longtemps regardés.",
      [2] = "[[Sentinel Hill]], c'était une tour et un camp de fermiers devenus soldats. Personne là-bas n'avait grand-chose, mais ils avaient décidé de tenir la ligne ensemble.",
    },
    ["Shadowfang Keep"] = {
      [1] = "La pierre froide et les hurlements se sont refermés sur moi dans [[Shadowfang Keep]], tout en haut de [[Pyrewood Village]]. Je connaissais Arugal de réputation, mais j'écoutais surtout les bruits derrière les murs.",
    },
    ["Shadowprey Village"] = {
      [1] = "[[Shadowprey Village]] se trouvait sur la côte de [[Desolace]], un village tranquille de la Horde parmi les roseaux, loin de tout.",
      [2] = "[[Shadowprey Village]] était un village de la Horde sur la côte, et même en [[Desolace]], je n'y étais pas $gle bienvenu:la bienvenue;.",
    },
    ["Silithus"] = {
      [1] = "[[Silithus]] était un désert de sable rouge et de grandes ruches, et le sol bourdonnait des silithides qui s'y déplaçaient. Les ruines d'Ahn'Qiraj se dressaient au sud, et l'air semblait lourd de ce qui y dormait.",
      [2] = "La nuit à [[Silithus]] était pleine de cliquetis et de grattements, les ruches pâles sous la lune. J'essayais de ne pas penser à ce qui se trouvait là-dessous.",
    },
    ["Silverpine Forest"] = {
      [1] = "Les pins de [[Silverpine Forest]] se dressaient, sombres, au-dessus de l'eau grise de [[Lordamere Lake]], et au-delà s'élevait le dôme violet de Dalaran. Des hurlements dans les collines ramenaient sans cesse mon attention vers les arbres autour de moi.",
      [2] = "Des hurlements m'ont $gsuivi:suivie; dans [[Silverpine Forest]] après la tombée de la nuit, venus de collines que je ne voyais pas. Derrière le mur noir des pins, je n'avais aucune envie de découvrir ce qui s'y trouvait d'autre.",
    },
    ["Southshore"] = {
      [1] = "Les maisons de [[Southshore]] se dressaient au bord de l'eau, avec une bonne auberge et une longue mémoire de la guerre. [[Tarren Mill]] était juste derrière la colline, et personne ici ne l'oubliait.",
      [2] = "[[Southshore]] était une ville humaine au bord de l'eau, à une courte marche des Réprouvés. Je m'attendais à ce que ses gardes sachent d'un coup d'œil de quel camp je venais.",
    },
    ["Splintertree Post"] = {
      [1] = "[[Splintertree Post]] était un rude camp de la Horde à l'orée de [[Ashenvale]], tout en palissades et en fumée de bois, où les haches ne s'arrêtaient jamais.",
      [2] = "[[Splintertree Post]] était un camp de la Horde à l'orée de [[Ashenvale]], d'où le bruit des haches portait toute la journée, et je n'attendais aucun accueil de ses gardes.",
    },
    ["Stonard"] = {
      [1] = "[[Stonard]] émergeait de la fange en lourde pierre orque, le seul endroit sec et sûr de [[Swamp of Sorrows]].",
      [2] = "[[Stonard]] était une forteresse orque émergeant du marais, et je ne doutais pas que ses murs soient gardés par des gens qui me voulaient $gmort:morte;.",
    },
    ["Stonetalon Mountains"] = {
      [1] = "[[Stonetalon Mountains]] grimpaient en grandes crêtes grises, et par endroits la forêt avait été réduite à des souches par les scies de la KapitalRisk. Le pic lui-même semblait tout regarder de haut.",
      [2] = "Les crêtes de [[Stonetalon Mountains]] se découpaient en noir sur les étoiles, et le vent chantait dans les cols. Tout en bas, les machines des gobelins tournaient encore.",
    },
    ["Stonetalon Peak"] = {
      [1] = "[[Stonetalon Peak]] était un camp paisible haut parmi les arbres, où les druides veillaient sur ce qui restait de la forêt.",
      [2] = "[[Stonetalon Peak]] était un camp elfe haut dans les montagnes, paisible et vigilant, et sa vigilance se portait sur moi.",
    },
    ["Stormwind City"] = {
      [1] = "Les murs blancs de [[Stormwind City]] s'élevaient au-dessus des canaux, et les cloches de la cathédrale portaient à travers toute la ville. C'était chez moi, et les cloches me le rappelaient.",
      [2] = "[[Stormwind City]] n'était que pierre blanche, toits bleus et canaux, avec des gardes sur chaque pont. On aurait dit une cité qui n'avait jamais connu la guerre, mais j'en savais plus long.",
      [3] = "Les murs blancs de [[Stormwind City]] se sont refermés autour de moi, et chaque garde semblait regarder dans ma direction. Je n'avais jamais eu autant conscience de mon propre visage.",
    },
    ["Stranglethorn Vale"] = {
      [1] = "[[Stranglethorn Vale]] n'était que jungle d'un bout à l'autre, chaude, bruyante d'oiseaux et pleine de choses qui voulaient me manger. De vieilles ruines trolls émergeaient de la verdure, et des chasseurs venaient du monde entier pour faire leurs preuves.",
      [2] = "Dans [[Stranglethorn Vale]], la nuit n'était jamais silencieuse. Des panthères rôdaient dans le noir, des tambours venaient des ruines trolls, et la chaleur ne faiblissait pas un instant.",
    },
    ["Stratholme"] = {
      [1] = "[[Stratholme]] était une cité qui avait brûlé et n'avait jamais cessé de brûler, le Fléau dans ses rues et la [[faction:Scarlet Crusade]] retranchée parmi les ruines.",
    },
    ["Sun Rock Retreat"] = {
      [1] = "[[Sun Rock Retreat]] s'abritait sous les falaises de [[Stonetalon Mountains]], un camp de la Horde où la montagne pressait de tous côtés.",
      [2] = "[[Sun Rock Retreat]] était un camp de la Horde niché sous les falaises, sans autre issue que le chemin par lequel j'étais $gvenu:venue;.",
    },
    ["Sunken Temple"] = {
      [1] = "[[Sunken Temple]] gisait à demi noyé dans le marais, ses salles sombres et ruisselantes, où les Atal'ai invoquaient encore leur dieu du sang. L'air avait le goût d'une magie ancienne.",
    },
    ["Swamp of Sorrows"] = {
      [1] = "[[Swamp of Sorrows]] méritait son nom : eau grise, mousse pendante et un silence qui ressemblait à du chagrin. Quelque part dans ses profondeurs gisait le temple englouti des Atal'ai.",
      [2] = "La nuit dans [[Swamp of Sorrows]] était étouffante et lourde, l'air assez épais pour qu'on le goûte. Des lueurs pâles se déplaçaient sur l'eau, et je n'avais aucune intention de les suivre.",
    },
    ["Tanaris"] = {
      [1] = "[[Tanaris]] n'était que sable, chaleur et encore du sable, des dunes jusqu'à l'horizon sous un ciel blanc. Les murs de [[Gadgetzan]] offraient la seule ombre à des lieues à la ronde.",
      [2] = "Le désert de [[Tanaris]] devenait froid la nuit, et les dunes viraient à l'argent. J'entendais le vent déplacer le sable, et de temps à autre les pinces d'un scorpide sur la pierre.",
    },
    ["Tarren Mill"] = {
      [1] = "[[Tarren Mill]] appartenait désormais aux Réprouvés, ses vieilles maisons réparées à leur manière et ses apothicaires affairés. [[Southshore]] était juste derrière la colline, et la ville ne l'oubliait jamais.",
      [2] = "[[Tarren Mill]] avait été un village humain autrefois. Désormais, les Réprouvés le tenaient, et les gardes noirs surveillaient chaque route. Je sentais que chacun d'eux savait ce que j'étais.",
    },
    ["Teldrassil"] = {
      [1] = "Les branches de [[Teldrassil]] portaient toute la forêt sous mes pieds. Des feux follets flottaient sur la mousse de notre nouveau foyer, et je leur enviais leur aisance.",
      [2] = "Le clair de lune argentait les feuilles de [[Teldrassil]] tandis que des chouettes appelaient au-dessus de moi. J'écoutais entre mes pas, peu $gdésireux:désireuse; de traverser à la hâte tant de silence.",
      [3] = "Dans la lumière violette de [[Teldrassil]], il était difficile d'oublier que toute la forêt reposait sur un seul arbre. Cette pensée détournait sans cesse mon regard des sentinelles vers le sol.",
      [4] = "Les feuilles de [[Teldrassil]] étouffaient chaque bruit. J'admirais l'endroit, tout en étant bien $gsûr:sûre; que quelqu'un m'avait déjà $gremarqué:remarquée;.",
    },
    ["The Barrens"] = {
      [1] = "L'herbe jaune s'étendait au-delà des arbres épineux de [[The Barrens]], où des zhévras se déplaçaient dans la chaleur. Les distances étaient plus difficiles à juger qu'elles ne l'avaient paru sur une carte.",
      [2] = "L'herbe de [[The Barrens]] virait à l'argent sous un immense ciel nocturne. Quelque part au loin, des tambours de centaures portaient sur l'herbe, et je gardais les yeux sur l'horizon.",
    },
    ["The Crossroads"] = {
      [1] = "La palissade de [[The Crossroads]] se dressait là où les routes rejoignaient la prairie. Après tant de distance vide, des gens rassemblés en un même lieu étaient un soulagement.",
      [2] = "À [[The Crossroads]], la palissade de la Horde abritait les siens. Pour moi, c'était une raison de bien regarder avant d'aller plus loin.",
    },
    ["The Deadmines"] = {
      [1] = "Des étais de bois soutenaient les galeries de [[The Deadmines]], et l'air avait le goût de la poussière et de l'huile de lampe. Quelque part devant, des machines martelaient, comme si toute la colline était travaillée de l'intérieur.",
      [2] = "Des wagonnets abandonnés attendaient sur leurs rails, et les murs suintaient à la lueur des lampes. Plus je m'enfonçais dans [[The Deadmines]], plus le martèlement s'amplifiait.",
    },
    ["The Hinterlands"] = {
      [1] = "[[The Hinterlands]] étaient hauts et sauvages, des collines boisées où volaient les griffons et d'où les trolls Witherbark guettaient depuis leurs ruines. Cela ressemblait à un pays qui n'avait jamais été tout à fait dompté.",
      [2] = "[[The Hinterlands]] étaient pleins de bruits la nuit : chouettes, loups, et les tambours des trolls là-haut dans les collines. Ce n'était pas un pays où dormir à la belle étoile.",
    },
    ["The Sepulcher"] = {
      [1] = "Des chauves-souris tournoyaient au-dessus des tombes de [[The Sepulcher]], et nos gardes se tenaient à la porte. Faire d'un cimetière un avant-poste me semblait un bon usage de ce qui restait.",
      [2] = "Je suis $garrivé:arrivée; à [[The Sepulcher]] par un flanc de colline couvert de tombes. Un instant, j'ai observé les gardes avec méfiance, avant de me rappeler qui vivait ici.",
    },
    ["The Stockade"] = {
      [1] = "[[The Stockade]] était la geôle de [[Stormwind City]], construite sous la cité, et les prisonniers en avaient pris le contrôle. Toutes les portes des cellules pendaient, ouvertes.",
    },
    ["Thelsamar"] = {
      [1] = "J'ai trouvé [[Stoutlager Inn]] de [[Thelsamar]] au bord du loch. Après les collines ouvertes, sa bière et ses boudins m'intéressaient plus que la distance parcourue.",
      [2] = "L'auberge de [[Thelsamar]] avait l'air confortable au bord du loch. Mais sur une rive de l'Alliance, ses fenêtres m'offraient plus de risques d'être $gvu:vue; que de chances de repos.",
    },
    ["Theramore Isle"] = {
      [1] = "[[Theramore Isle]] se dressait sur son île au large de la côte du marais, tours de pierre et quais animés, la cité de dame Jaina et l'ancrage de l'Alliance en Kalimdor.",
      [2] = "Les tours de [[Theramore Isle]] s'élevaient sur leur île au large de la côte, la cité de dame Jaina et l'ancrage de l'Alliance en Kalimdor. C'était le dernier endroit où j'aurais dû me trouver.",
    },
    ["Thorium Point"] = {
      [1] = "[[Thorium Point]] était le camp de la [[faction:Thorium Brotherhood]] au bord de la gorge, quelques tentes et une forge au-dessus de toute cette chaleur.",
    },
    ["Thousand Needles"] = {
      [1] = "[[Thousand Needles]] portaient bien leur nom : des piliers de pierre s'élevaient par centaines du fond du canyon, reliés à leur sommet par des ponts de corde. À l'est, le Désert de sel brillait de blanc.",
      [2] = "La nuit, les flèches rocheuses de [[Thousand Needles]] se dressaient comme une forêt de pierre noire. Les camps sur les mesas étaient petits et éloignés les uns des autres, et la chute en contrebas était longue.",
    },
    ["Thunder Bluff"] = {
      [1] = "[[Thunder Bluff]], la cité de Cairne, se dressait sur ses mesas au-dessus de [[Mulgore]], faite de tentes, de totems et de ponts de corde. Le vent ne s'arrêtait jamais là-haut, et je n'aurais pas voulu qu'il en soit autrement.",
      [2] = "[[Thunder Bluff]] se dressait sur ses mesas bien au-dessus de [[Mulgore]], avec des tentes et des totems sur chaque sommet et des ponts de corde qui se balançaient entre eux. Le vent ne s'arrêtait jamais, et personne ne semblait s'en soucier.",
      [3] = "[[Thunder Bluff]] s'élevait sur ses mesas au-dessus des plaines, accessible seulement par ses grands monte-charges. D'en bas, aucun espoir d'entrer sans être $gvu:vue;.",
    },
    ["Tirisfal Glades"] = {
      [1] = "Sous le ciel gris de [[Tirisfal Glades]], des arbres morts se dressaient là où la peste les avait laissés. Je reconnaissais quelque chose de moi-même dans un pays qui avait été obligé de continuer.",
      [2] = "Des corbeaux croassaient au-dessus des cryptes de [[Tirisfal Glades]], vers les murs brisés de Lordaeron. La nuit n'y changeait pas grand-chose, même si elle me rendait moins $gvoyant:voyante;.",
      [3] = "Les champs gris de [[Tirisfal Glades]] menaient, au-delà des arbres morts, jusqu'aux murs brisés de Lordaeron. Je me demandais ce que les gens d'ici se rappelaient encore de leur pays.",
      [4] = "Des arbres morts s'étendaient à travers [[Tirisfal Glades]] jusqu'aux ruines de Lordaeron. Savoir que les Réprouvés marchaient ici rendait le calme plus difficile à croire.",
    },
    ["Uldaman"] = {
      [1] = "[[Uldaman]] était une chambre forte des titans, creusée profondément dans la montagne, où troggs et nains Sombrefer se disputaient des choses qu'aucun d'eux ne comprenait. La pierre elle-même semblait observer.",
    },
    ["Undercity"] = {
      [1] = "Des canaux verts parcouraient [[Undercity]], devant le bouillonnant Apothicarium, tout au fond sous les ruines de Lordaeron. De tant de choses qui avaient mal survécu, nous avions fait une cité, et elle était à nous.",
      [2] = "Une boue verte emplissait les canaux de pierre de [[Undercity]], tout au fond sous Lordaeron. L'odeur ne m'a pas $gquitté:quittée; tout le temps que j'ai cherché mon chemin.",
      [3] = "Sous les ruines de Lordaeron, les Réprouvés avaient fait de [[Undercity]] leur foyer. Chaque tournant que je prenais rendait le chemin vers la lumière du jour moins certain.",
    },
    ["Un'Goro Crater"] = {
      [1] = "[[Un'Goro Crater]] était un autre monde, chaud et fumant, plein de fougères géantes et de créatures qui auraient dû disparaître depuis longtemps. Des diablosaures marchaient à travers la jungle, et le sol tremblait sous leurs pas.",
      [2] = "La nuit dans [[Un'Goro Crater]] était épaisse de chaleur et de bruit : des insectes grands comme ma main, et le rugissement lointain de quelque chose d'énorme. Le cratère semblait plus ancien que tout ce que je connaissais.",
    },
    ["Wailing Caverns"] = {
      [1] = "Dans [[Wailing Caverns]], le vent gémissait sur l'eau verte parmi les racines. Sachant ce qu'étaient devenus les druides, je guettais une voix avec qui l'on pourrait encore raisonner.",
    },
    ["Western Plaguelands"] = {
      [1] = "[[Western Plaguelands]] avaient été des terres agricoles autrefois, et les fermes étaient toujours debout, vides ou pire. Le grain était rongé, les morts marchaient dans les champs, et Andorhal n'était plus qu'une ruine.",
      [2] = "La nuit dans [[Western Plaguelands]] était pleine de bruits qui n'allaient pas : des pieds qui traînaient, le grincement de maisons vides, le vent dans le blé mort. Chaque ombre avait l'air de pouvoir se lever.",
    },
    ["Westfall"] = {
      [1] = "Les champs de [[Westfall]] s'étendaient, dorés, jusqu'à l'horizon, et la moitié étaient montés en graine. Des fermes vides se dressaient, portes ouvertes, et je pensais aux familles qui les avaient travaillées avant l'arrivée des Défias.",
      [2] = "[[Westfall]] s'étendait, sombre et silencieuse, ses moulins tournant au-dessus de fermes que plus personne n'entretenait. Je me demandais qui vivait encore derrière ses fenêtres obscures.",
      [3] = "Des champs dorés traversaient [[Westfall]] jusqu'à la mer, sous des moulins qui tournaient. C'était un beau pays, et un pays affamé : trop de fermes étaient vides, et trop de gens sur la route n'avaient nulle part où aller.",
      [4] = "Les champs de [[Westfall]] couraient vers la mer, avec des fermes vides et des épouvantails qui n'en étaient pas toujours. Au cœur des terres agricoles de l'Alliance, je me tenais bien à l'écart de la route.",
    },
    ["Wetlands"] = {
      [1] = "[[Wetlands]] n'étaient que boue, roseaux et eaux dormantes, et la moitié de la route disparaissait dessous. Des raptors rôdaient dans le marais, et à l'est, les hauteurs de Grim Batol n'étaient pas un sujet qu'on évoquait à la légère.",
      [2] = "La nuit, [[Wetlands]] s'éveillaient de coassements et de clapotis, et la brume restait basse sur l'eau. La route était la seule chose en laquelle j'avais confiance, et dans un marais, ce n'était pas beaucoup dire.",
    },
    ["Winterspring"] = {
      [1] = "[[Winterspring]] dormait sous une neige épaisse, calme et propre, avec des sabres-de-givre dans les collines et des sources fumantes parmi les congères. Après tant d'endroits brûlés et rongés, le froid avait quelque chose d'honnête.",
      [2] = "Sous les étoiles, la neige de [[Winterspring]] était bleue et silencieuse. Le froid mordait fort, [[Everlook]] se dressait, minuscule, au loin, et je pensais à sa chaleur.",
    },
    ["Zul'Farrak"] = {
      [1] = "[[Zul'Farrak]] était une cité troll dans le désert, ses escaliers et ses temples cuisant au soleil, et les Sandfury guettaient du haut de chaque mur.",
    },
    ["Zul'Gurub"] = {
      [1] = "[[Zul'Gurub]] était l'ancienne capitale des Gurubashi, émergeant de la jungle, ses temples imprégnés du culte du dieu du sang.",
    },
  },
  why = {
    [2] = "ai rapporté la griffe de [[name:Sharptalon]] à [[name:Senani Thunderheart]], la preuve que l'hippogriffe qui terrorisait les péons des camps de bûcherons était mort",
    [6] = "ai traqué Garrick Padfoot, un coupe-jarret qui tourmentait les fermiers et les marchands de [[Elwynn Forest]], pour la prime de l'adjoint Willem",
    [9] = "ai chassé les gardiens des moissons des champs du fermier Saldean et de ceux de ses voisins, dans l'espoir que [[Westfall]] prospère à nouveau",
    [10] = "ai fouillé [[Gaping Chasm]] à la recherche de l'assistant disparu de Fizzledowser, le géomètre subalterne Scrimshank, et n'ai trouvé que son matériel",
    [12] = "ai traqué les trappeurs et les contrebandiers défias dans les fermes de [[Westfall]] pour gagner une place dans la milice populaire de Gryan Stoutmantle",
    [13] = "ai chassé les pilleurs et les pillards défias de [[Gold Coast Quarry]] et de [[Moonbrook]], l'étape suivante de l'entraînement de la milice",
    [14] = "ai délogé les Défias qui avaient fui dans [[Dagger Hills]], ce qui m'a valu une place dans la milice populaire",
    [15] = "ai chassé les ouvriers kobolds de leur camp près de [[Echo Ridge Mine]], pour savoir, pour le maréchal McBride, jusqu'où allait l'infestation",
    [17] = "ai ramassé des chapeaux de champignon magenta à [[Uldaman]] pour que Ghak Healtouch les étudie pour l'alchimie, en prenant garde à leurs spores empoisonnées",
    [18] = "ai arraché des masques rouges aux membres de la Confrérie défias, une nouvelle bande de voleurs qui rôdait de l'autre côté de la rivière, face à [[Northshire Valley]]",
    [19] = "ai traqué [[name:Tharil'zun]], le chef cruel des coureurs Blackrock qui tendaient des embuscades sur la route de [[Stonewatch Keep]]",
    [20] = "ai combattu les orcs Blackrock de [[Stonewatch Keep]], dont les raids gardaient les gens de [[Lakeshire]] parqués en ville comme du bétail",
    [21] = "ai purgé [[Echo Ridge Mine]] de ses travailleurs kobolds avant qu'ils ne prennent pied plus solidement [[at:Northshire Valley]]",
    [22] = "suis $gallé:allée; chercher des foies de Broche-tripes pour la célèbre tourte à la viande de Salma Saldean, un festin pour elle et le fermier Saldean",
    [23] = "ai présenté la patte d'[[name:Ursangous]], un grand ours aux nombreuses victimes, à [[name:Senani Thunderheart]] pour la chasse de [[Ashenvale]]",
    [24] = "ai rapporté la tête de [[name:Shadumbra]], la sabre-de-nuit qui rendait dangereux chaque voyage à l'ouest de [[Splintertree Post]], pour la chasse de [[Ashenvale]]",
    [25] = "ai dispersé les élémentaires d'eau souillés qui bloquaient les convois au-delà de [[Mystral Lake]], et repéré l'avant-poste de l'Alliance qui s'y trouvait",
    [28] = "ai plongé dans [[Lake Elune'ara]] pour une babiole du sanctuaire et l'ai rapportée en courant au sanctuaire de Remulos, une première épreuve pour la forme aquatique",
    [29] = "ai fouillé [[Lake Elune'ara]] à la recherche d'une babiole du sanctuaire et l'ai rapportée en courant au sanctuaire de Remulos avant qu'elle ne se défasse, l'épreuve du lac",
    [30] = "ai réuni les deux moitiés du pendentif du lion de mer, agilité et endurance, pour réussir l'épreuve de la forme aquatique",
    [32] = "ai porté le rapport de Fizzledowser sur les insectes du désert à Zilzibin Drumlore à [[Orgrimmar]], un érudit troll qui saurait peut-être comment les arrêter",
    [33] = "ai chassé les loups des bois pour la viande coriace qu'Eagan Peltskinner voulait pour ses steaks de loup",
    [34] = "ai mis fin aux jours de [[name:Bellygrub]], le sanglier qui ne cessait de piétiner le jardin et les jonquilles de Martie Jainrose",
    [36] = "ai porté la recette du ragoût de la marche de l'Ouest de Verna Furlbrow à Salma Saldean avant que les Furlbrow ne quittent leur ferme envahie",
    [38] = "ai rassemblé de la viande de vautour, des groins de Broche-tripes, des yeux de murloc et du gombo pour que Salma Saldean cuisine le ragoût de Verna",
    [48] = "suis $gallé:allée; chercher l'eau de la source sacrée à un puits caché dans le sud pour la recette en vers de l'ambrée douce de Grimbooze Thunderbrew",
    [49] = "ai rassemblé des sacs d'orge, de seigle et de maïs pour le moût de l'ambrée douce de Grimbooze Thunderbrew",
    [50] = "ai fourni du vrai-argent pour que Grimbooze Thunderbrew se fabrique un alambic pour sa réserve personnelle",
    [51] = "suis $gallé:allée; chercher une branche de sycomore pour le charbon qui filtrerait l'alcool de Grimbooze Thunderbrew",
    [53] = "ai rapporté du chêne carbonisé pour le tonneau où vieillirait l'ambrée douce de Grimbooze Thunderbrew, le tout conclu par un toast en vers",
    [54] = "ai porté les papiers du maréchal McBride au maréchal Dughan à [[Goldshire]], une commission d'adjoint par intérim pour aider à garder [[Elwynn Forest]] en sécurité",
    [55] = "ai retourné le Fléau de Morbent contre Morbent Fel dans sa maison au-dessus de la [[Raven Hill]] et l'ai tué, la vengeance que Sven espérait depuis longtemps",
    [56] = "ai chassé les squelettes de [[Tranquil Gardens Cemetery]] pour le Guet de nuit, qui gardait seul [[Darkshire]] depuis que [[Stormwind City]] avait retiré ses soldats",
    [57] = "ai chassé les démons squelettes et les squelettes infernaux du cimetière de la [[Raven Hill]], d'où les morts-vivants se répandaient dans la forêt autour de [[Darkshire]]",
    [58] = "ai débarrassé le mausolée est de la [[Raven Hill]] de ses répandeurs de peste, avec trop peu de veilleurs restants pour garder [[Darkshire]] en sécurité",
    [64] = "ai repris la montre du fermier Furlbrow, un cadeau de mariage du père de Verna, dans la ferme envahie par les voleurs",
    [66] = "ai demandé le nom de Stalvan à l'hôtel de ville, un indice tiré de la transe de Madame Eva, qui craignait pour sa petite-fille Alyssa",
    [67] = "ai cherché des nouvelles de Stalvan Mistmantle à l'école de [[Moonbrook]], sa dernière adresse connue dans le registre du clerc Daltry",
    [68] = "ai apporté au clerc Daltry une lettre poussiéreuse jamais envoyée, tirée d'une malle de [[Moonbrook]], la preuve que Stalvan y avait bien vécu",
    [69] = "ai suivi une adresse à moitié raturée du registre de la ville jusqu'à l'auberge de la Fierté du lion à [[Goldshire]], à la recherche de Stalvan",
    [70] = "ai livré une lettre de Stalvan, laissée par un messager qui avait fui en hurlant l'auberge de la Fierté du lion une nuit d'orage",
    [72] = "ai fouillé les dernières affaires de la famille Flintridge, promises aux enchères longtemps après le massacre, à la recherche d'un indice sur Stalvan",
    [74] = "ai montré la page de journal déchirée de la caisse des Flintridge au maréchal Haggard, dont les yeux fatigués reconnaissaient encore l'écriture",
    [75] = "suis $gallé:allée; chercher la vieille page de journal dans le coffre à l'étage pour le maréchal Haggard, trop aveugle pour la lire lui-même",
    [77] = "ai récupéré des bouteilles de Délice au miel des Hinterlands dans les caisses des ruines de [[Skulk Rock]], infestées de limons, la gourmandise que voulait Dran Droffers",
    [78] = "ai porté la vieille page de journal au tavernier Smitts, expert en histoire locale, qui a reconnu l'écriture aussitôt",
    [79] = "ai apporté au commandant Ebonlocke les pages boueuses trouvées là où des nobles en visite avaient été massacrés, qui reliaient les preuves à Stalvan",
    [80] = "ai fait comparer par le clerc Daltry la page de journal tachée de sang aux signatures de son registre, la preuve de la culpabilité de Stalvan",
    [82] = "ai arraché des morceaux aux Centipaar de [[Noxious Lair]] pour que l'alchimiste Pestlezugg sache ce qui asséchait les points d'eau du désert",
    [89] = "ai repris aux gnolls qui avaient détourné les provisions de [[Lakeshire]] les clous et les vis en fer, pour que le pont sur le lac puisse être reconstruit",
    [90] = "ai rassemblé des steaks de loup et des herbes aromatiques de [[Stormwind City]] pour les brochettes de loup assaisonnées que le chef Grual appelait la spécialité de la maison",
    [91] = "ai tué les gnolls Sombrepoil qui servaient le démoniste Morganth et terrorisaient [[Lakeshire]], comme l'exigeait la loi de [[Lakeshire]]",
    [92] = "ai rassemblé de la viande de condor, des groins de broche-tripes et de la chair d'araignée pour regarnir le garde-manger vide de la cheffe Breanna, pour un goulash des Carmines",
    [93] = "ai rassemblé des pattes d'araignée fondantes pour les gâteaux au crabe brun du chef Grual, pour nourrir Jitters après des semaines de vers et de mauvaises herbes",
    [94] = "ai posé le glyphe d'Azora près de [[Tower of Ilgalar]] pour que Theocritus puisse espionner son rival, le mage Morganth",
    [95] = "ai déterré ce qu'une silhouette sombre avait enterré derrière la vieille souche de la ferme de Sven, où des cavaliers noirs avaient massacré sa famille",
    [98] = "ai exécuté Stalvan Mistmantle dans sa chaumière au nord de [[Darkshire]], l'assassin que la prémonition de Madame Eva avait démasqué",
    [99] = "ai pris des chaînes enchantées aux habitants maudits de [[Pyrewood Village]], la dernière pièce dont Dalar Dawnweaver avait besoin pour défaire la magie d'Arugal",
    [101] = "ai rassemblé crocs, doigts et venin pour que Madame Eva enchante un totem d'infliction contre un danger qu'elle pressentait",
    [102] = "ai patrouillé les prairies à la recherche des gnolls qui travaillaient avec les voleurs de [[Deadmines]], et rapporté leurs pattes au capitaine Danuvin",
    [103] = "ai pris des flasques d'huile aux monstres des moissons pour que le capitaine Grayson garde le phare allumé pour les marins près des rochers",
    [104] = "ai tué le Vieux Troubloeil, le murloc dont les raids avaient tué la famille du gardien du phare, pour le fantôme du capitaine Grayson",
    [105] = "ai détruit Araj l'Invocateur, la liche qui tenait Andorhal, et porté un éclat de son phylactère au grand exécuteur Derrington",
    [113] = "ai rapporté à Fizzledowser la sombre découverte de Pestlezugg : une force venue d'ailleurs poussait les insectes, une menace pour tout le sud de Kalimdor",
    [115] = "ai pris des orbes de minuit aux lanceurs d'ombre Blackrock pour qu'ils soient détruits, des instruments obscurs qui avaient durement frappé les défenseurs des Carmines",
    [116] = "ai rapporté bière, merlot, tord-boyaux et rhum de quatre villes pour le tavernier Daniels, ses bouteilles presque vides depuis l'invasion orque",
    [117] = "ai trouvé du houblon pour Grimbooze Thunderbrew, pour que sa blonde ait plus le goût de la bière et moins celui du ragoût",
    [118] = "ai porté la note de Verner Osgood au forgeron Argus, à [[Goldshire]], pour demander des fers pour les chevaux de l'écurie",
    [119] = "ai rapporté la caisse de fers à cheval à Verner Osgood, avec la note d'Argus réclamant d'être payé",
    [120] = "ai porté au général Marcus Jonathan l'appel aux renforts du magistrat Solomon, [[Lakeshire]] étant constamment assiégé",
    [121] = "ai rapporté au magistrat Solomon la réponse du général Marcus Jonathan, où il a lu que quelque chose n'allait pas dans le royaume",
    [122] = "ai chassé des dragonnets noirs pour leurs écailles ventrales, afin que Verner Osgood puisse payer à Argus ses fers à cheval",
    [124] = "ai chassé les brutes et les mystiques gnolls de la crête au-dessus de l'écurie de Verner Osgood, qui lui prenaient ses chevaux quand ils s'égaraient",
    [125] = "ai plongé au fond de [[Lake Everstill]] pour la boîte à outils du contremaître Oslow, coulée quand les catapultes orques avaient frappé le bateau qui la portait",
    [126] = "ai tué [[name:Yowler]], chef des gnolls dont les hurlements emplissaient les collines au-dessus de [[Lakeshire]], pour disperser sa meute",
    [127] = "ai vendu au maître des docks Baren les poissons-lunes tachetés qui font la réputation de [[Lake Everstill]], son stock s'épuisant",
    [128] = "ai tué [[des:Blackrock Champion]], les chefs des unités du clan campées au nord de [[Lakeshire]], comme le voulait le magistrat Solomon",
    [129] = "ai apporté son déjeuner au garde Parker pendant sa patrouille sur la route de [[Duskwood]], un trajet trop dangereux pour l'habitante qui l'avait préparé",
    [131] = "ai porté les jonquilles du garde Parker à Darcy, qui craignait que Martie, jalouse, ne les ait empoisonnées",
    [132] = "ai porté la note de Wiley à Gryan Stoutmantle, un avertissement : les Défias travaillaient avec des gnolls, des kobolds et même des gobelins",
    [133] = "ai rassemblé des côtes de goule pour l'effigie d'Abercrombie, un épouvantail à goules, après que des mâcheurs d'os avaient tambouriné à ses murs",
    [134] = "ai récupéré la caisse d'outils et d'herbes d'Abercrombie près du tertre des ogres, abandonnée quand les ogres l'avaient chassé",
    [135] = "ai montré la note de Wiley à Mathias Shaw du SI:7, pour savoir si les Défias avaient des liens avec les tailleurs de pierre",
    [136] = "ai suivi le premier indice du capitaine Sanders jusqu'à une malle à moitié enterrée près de la seule ancre rouillée de la côte",
    [138] = "ai suivi l'indice suivant vers le trésor du capitaine Sanders, à l'est sur les falaises, jusqu'à un vieux tonneau près d'une cheminée en ruine",
    [139] = "ai suivi la piste d'indices du capitaine Sanders vers le nord jusqu'à une cruche vide près d'un moulin solitaire sur les falaises",
    [140] = "ai nagé vers l'ouest jusqu'à une île pour le coffre au trésor du capitaine Sanders, la fin de sa piste d'indices",
    [141] = "ai porté le rapport de Shaw à Stoutmantle : le chef des Défias était sans doute Edwin VanCleef, le tailleur de pierre brouillé avec le roi",
    [142] = "ai traqué le messager défias sur les routes de [[Westfall]] pour le message qui prouvait que VanCleef menait la Confrérie",
    [143] = "ai porté l'appel du magistrat Solomon à Gryan Stoutmantle, de la milice de [[Westfall]], puisque l'armée de [[Stormwind City]] n'était pas venue",
    [144] = "ai rapporté le refus attristé de Gryan Stoutmantle, [[Westfall]] abandonnée par [[Stormwind City]] tout comme [[Lakeshire]]",
    [145] = "suis $gpassé:passée; à [[Duskwood]] avec la lettre du magistrat Solomon demandant au seigneur Ebonlocke d'envoyer son Guet de nuit à [[Lakeshire]]",
    [146] = "ai rapporté à [[Lakeshire]] le refus du seigneur Ebonlocke, une nouvelle qui a convaincu le magistrat Solomon d'une trahison à [[Stormwind City]]",
    [149] = "ai porté un peigne spectral à l'esprit triste de Marie l'Aveugle, pour que Madame Eva en tire des cheveux fantômes pour en faire du fil",
    [150] = "ai chassé pour le maître des docks Baren les murlocs qui vidaient [[Lake Everstill]] de ses poissons, étrangement loin de la mer",
    [152] = "ai chassé les murlocs de la côte de [[Westfall]] pour le capitaine Grayson, pour que les marins naufragés soient en sécurité sur ses plages",
    [153] = "ai pris des masques en cuir rouge aux membres des bandes défias pour l'éclaireur Galiaan, qui suivait grâce à eux le front mouvant des Défias",
    [154] = "ai rapporté le peigne à Madame Eva après que Marie l'Aveugle avait pleuré qu'elle était un monstre que plus personne ne trouverait jamais beau",
    [155] = "ai escorté le traître défias jusqu'à la cachette secrète de la Confrérie, pour que Stoutmantle sache où se cachait VanCleef",
    [156] = "ai cueilli des fleurs pourries sur les crânes des squelettes de la [[Raven Hill]] pour le suc de zombie du tavernier Smitts, en éclaircissant leurs rangs",
    [157] = "ai apporté à Abercrombie le fil de cheveux fantômes, bon pour lier les esprits mauvais ou coudre la vie dans les choses sans vie",
    [159] = "ai porté à Abercrombie le suc de zombie qu'il voulait contre les nuits froides, un breuvage assez fort pour relever les morts",
    [160] = "ai porté la lettre d'Abercrombie à son vieil ami le maire de [[Darkshire]], qui l'a trouvée écrite dans une langue qu'il ne savait pas lire",
    [161] = "ai porté l'étrange poudre du barrage à Ashlan Stonesmirk à [[Dun Modr]], un expert en explosifs capable de dire ce que c'était",
    [162] = "ai porté le rapport de Fizzledowser sur les insectes du désert à Gracina Spiritmight à [[Darnassus]], une érudite qui saurait peut-être comment les arrêter",
    [163] = "ai cherché ce qui hantait la [[Raven Hill]], où Calor avait vu bouger des ombres, et n'y ai trouvé que Jitters, caché",
    [164] = "ai livré des fournitures au camp de Sven en lisière de [[Duskwood]], ses fidèles trop peu nombreux pour envoyer quelqu'un les chercher en ville",
    [165] = "suis $gallé:allée; voir le vieil homme de la cabane au-dessus du cimetière de la [[Raven Hill]], qui avait cessé depuis longtemps de venir en ville",
    [166] = "ai assassiné Edwin VanCleef dans [[Deadmines]], le début de la fin pour la Confrérie défias qui tourmentait [[Westfall]]",
    [167] = "ai fouillé la mine effondrée de Ruisselune à la recherche du frère de [[name:Wilder Thistlenettle]], et n'ai rapporté que son insigne de la Ligue des explorateurs",
    [168] = "ai rassemblé les cartes du syndicat des mineurs de ceux qui avaient péri dans l'éboulement, pour que [[name:Wilder Thistlenettle]] prévienne leurs familles",
    [169] = "ai tué [[name:Gath'Ilzogg]], chef des attaques Blackrock contre [[Lakeshire]], premier pas pour reprendre [[Stonewatch Keep]] au nom de [[Stormwind City]]",
    [170] = "ai repoussé les troggs Mâcheroc pour Balir Frosthammer, dont ils avaient envahi le camp à l'ouest quelques nuits plus tôt",
    [173] = "me suis $gattaqué:attaquée; aux tisseurs d'ombre Plaie-de-nuit du bosquet de Clairbois, pour me montrer digne de la bande de maître Carevin",
    [174] = "ai trouvé un tube en bronze pour Viktori Prism'Antras, la première pièce d'un appareil pour lire dans les étoiles la vérité sur le changement de la forêt",
    [175] = "ai retrouvé Marie, connue autrefois pour toujours porter un miroir, pour lui demander un miroir pour l'appareil à étoiles de Viktori",
    [177] = "ai arraché le miroir de Marie l'Aveugle à la goule démente de [[Tranquil Gardens Cemetery]], le miroir qui manquait à l'appareil de Viktori",
    [178] = "ai porté un pendentif sombrepoil fané au mage Theocritus, dont le sort lancé à travers lui sur les gnolls de Morganth semblait avoir échoué",
    [179] = "ai chassé des loups pour la viande de loup coriace de Sten Stoutarm, en échange de gants chauds contre les engelures",
    [180] = "ai tué [[name:Lieutenant Fangore]], chef des gnolls Sombrepoil au service de Morganth, dont le magistrat Solomon voulait la mort",
    [181] = "ai pris le monocle de l'ogre Zzarc'Vul pour la lentille de l'appareil à observer les étoiles de Viktori, la dernière pièce qu'il réclamait",
    [182] = "ai éclairci les rangs des jeunes trolls Frostmane dans la caverne du sud pour [[name:Grelin Whitebeard]], envoyé [[at:Coldridge Valley]] jauger la menace troll",
    [183] = "ai décimé les petits sangliers des rochers près du lac gelé, devenus si nombreux que la chasse quotidienne de Talin Keeneye était devenue dangereuse",
    [184] = "ai rapporté le titre de propriété volé des Furlbrow, que les voleurs comptaient falsifier, pour que la famille puisse un jour reprendre ses terres",
    [185] = "ai prouvé mon adresse de $gchasseur:chasseuse; à [[name:Ajeck Rouack]] sur [[les:Young Stranglethorn Tiger]] près du camp de Nesingwary, la première de ses épreuves",
    [186] = "ai traqué [[les:Stranglethorn Tiger]] adultes, l'étape suivante de l'apprentissage de [[name:Ajeck Rouack]] dans la chasse au tigre",
    [187] = "ai pisté [[les:Elder Stranglethorn Tiger]], les plus féroces et les plus difficiles à trouver, pour montrer à [[name:Ajeck Rouack]] que la leçon avait porté",
    [188] = "ai abattu [[name:Sin'Dall]], le tigre insaisissable que l'expédition de Nesingwary pistait depuis des semaines, et gagné le titre de $gmaître:maîtresse; chasseur de tigres",
    [189] = "ai rapporté [[des:Bloodscalp Ear]] à [[name:Kebok]] de [[Booty Bay]], dont les agents et les gardes se faisaient tuer par les trolls dans la jungle",
    [190] = "ai commencé par [[les:Young Panther]], la première preuve que [[name:Sir S. J. Erlgadin]] demandait à quiconque rejoignait la chasse de Hemet",
    [191] = "suis $gpassé:passée; aux [[pl:Panther]] adultes, un gibier plus coriace, pour être $gjugé:jugée; digne des chasseurs de gros gibier de Nesingwary",
    [192] = "ai abattu [[les:Shadowmaw Panther]], les fauves les plus mortels de [[Stranglethorn Vale]], la plus dure épreuve de [[name:Sir S. J. Erlgadin]] pour un chasseur de panthères",
    [193] = "ai tué la grande panthère [[name:Bhag'thera]], qui avait échappé à l'expédition de Nesingwary, et rapporté son croc à [[name:Sir S. J. Erlgadin]]",
    [194] = "ai chassé [[les:Stranglethorn Raptor]] pour [[name:Hemet Nesingwary]], qui laissait au chasseur le soin de les trouver, la moitié du défi",
    [195] = "me suis $gattaqué:attaquée; aux [[pl:Lashtail Raptor]], l'épreuve suivante et plus rude de [[name:Hemet Nesingwary]] pour un chasseur de raptors",
    [196] = "ai pisté [[les:Jungle Stalker]], les raptors les plus méfiants et les plus durs à abattre, pour gagner le meilleur tuyau de chasse de [[name:Hemet Nesingwary]]",
    [197] = "ai tué [[name:Tethis]], un raptor rusé que même [[name:Hemet Nesingwary]] n'avait pas su abattre, et rapporté sa serre",
    [198] = "ai porté des fournitures gobelines au soldat Thorsen, des mines terrestres dont les rebelles du lieutenant Doren avaient besoin contre Kurzen et ses hommes",
    [200] = "ai fouillé le camp de Kurzen à la recherche des registres de [[name:Bookie Herod]], pour savoir comment le secret du soldat Thorsen était parvenu jusqu'à Kurzen",
    [201] = "ai repéré le camp des chasseurs en amont pour [[name:Krazek]] à [[Booty Bay]], qui voulait savoir ce que mijotait [[name:Hemet Nesingwary]]",
    [202] = "ai pris d'assaut la Réserve pour tuer le colonel Kurzen et ses chefs, sauvant la bande de rebelles du lieutenant Doren",
    [203] = "ai attaqué le camp de Kurzen pour abattre [[des:Kurzen Jungle Fighter]] et soulager les rebelles, qui étaient en sous-nombre",
    [204] = "ai pris aux médecins de Kurzen leurs [[pl:Jungle Remedy]] et leurs extraits de fougère vénéneuse, pour que les rebelles puissent soigner les leurs",
    [205] = "ai pris [[des:Skullsplitter Fetish]] à leurs sorciers-docteurs pour le frère Nimetz, qui cherchait le secret de la chute de Kurzen dans le mal",
    [206] = "ai tué le mage ogre [[name:Mai'Zoth]], dont la magie de l'esprit avait corrompu Kurzen selon le frère Nimetz, et pris sa Vue de l'esprit",
    [207] = "ai recopié quatre tablettes trolls dans les ruines de [[Stranglethorn Vale]] pour le frère Nimetz, qui soupçonnait une magie troll derrière la chute de Kurzen",
    [208] = "ai chassé le roi Bangalash, le grand tigre blanc pour lequel [[name:Hemet Nesingwary]] était venu [[at:Stranglethorn Vale]], un trophée qu'aucun autre chasseur n'avait pris",
    [209] = "ai arraché des défenses aux trolls Skullsplitter pour [[name:Kebok]], qui les vendait comme crocs de tigre aux acheteurs des mers du Sud",
    [210] = "ai rapporté la cocotte cassée du cuisinier des rebelles à [[name:Krazek]] à [[Booty Bay]], le gobelin qui l'avait fabriquée, pour qu'il la répare",
    [211] = "ai abattu Araj l'Invocateur, la liche qui régnait sur Andorhal, et porté l'éclat de son phylactère au commandant Ashlam Valorfist",
    [212] = "ai porté en hâte un cuissot de basilic glacé de [[Stranglethorn Vale]] à Angus Stern, qui voulait la viande fraîche pour le banquet d'anniversaire d'un noble",
    [213] = "ai volé [[des:Tumbled Crystal]] aux géologues de la KapitalRisk pour [[name:Kebok]], tandis que le baron Revilgaz ripostait aux manigances de Gelriz",
    [214] = "ai abattu les Défias les plus haut gradés de la planque de VanCleef et rapporté leurs masques de soie rouge à l'éclaireur Riell pour preuve",
    [215] = "ai appris du lieutenant Doren que le soldat Thorsen était retourné parmi les hommes de Kurzen pour espionner pour les rebelles",
    [216] = "ai fait des coupes sombres chez les furbolgs Crin-de-Chardon, dont le village barrait la route de la Horde entre [[Zoram'gar Outpost]] et [[Splintertree Post]]",
    [217] = "ai tué le chef trogg Grawmug et ses gardes Grinceur et Bagarreur, pour repousser les troggs de [[Loch Modan]] sous terre",
    [218] = "ai tué [[name:Grik'nir the Cold]] dans la caverne des trolls pour reprendre le journal volé de [[name:Grelin Whitebeard]]",
    [219] = "ai escorté le caporal Keeshan, blessé, dont le régiment avait été écrasé par les orcs Blackrock, de sa grotte-prison jusqu'aux Carmines",
    [221] = "ai décimé les messagers Plaie-de-nuit qui avaient envahi le Verger pourri, le gros des worgens des bois, pour Calor",
    [222] = "ai affronté les crocs noirs et les contaminés Plaie-de-nuit près de leurs feux de camp au sud, les worgens les plus dangereux de [[Duskwood]]",
    [223] = "ai porté la lettre de recommandation de Calor à maître Jonathan Carevin, pour rejoindre son combat contre les démons et les morts-vivants",
    [224] = "ai combattu les troggs Brisepierre qui creusaient leurs tunnels à travers [[Loch Modan]], la plus grave menace pour [[Ironforge]] tant que ses soldats étaient au front",
    [225] = "ai interrogé Sirra Von'Indi au sujet de Morgan Ladimore, dont la tombe usée venait d'être creusée",
    [226] = "ai décimé les loups redoutables affamés et enragés qui harcelaient Lars quand il rentrait au camp de Sven avec de la viande",
    [228] = "ai tué Mor'Ladim, le corps relevé de Morgan Ladimore, qui errait dans [[Duskwood]] en attaquant les gardes en patrouille",
    [229] = "ai apporté à la guetteuse Sarah Ladimore des nouvelles de son père, dont la mort l'avait toujours troublée",
    [230] = "ai apporté à Sven le livre déterré à sa ferme, qui lui apprenait que la silhouette sombre avait assisté à la mort de sa famille",
    [231] = "ai posé l'anneau de Sarah Ladimore sur la tombe de son père, pour que Morgan Ladimore sache qu'elle vivait et que son âme puisse reposer",
    [232] = "ai porté la commande de l'apothicaire Zinge à Alessandro Luca pour une trousse d'analyse, le début de son plan pour tirer profit des recherches de Keever",
    [237] = "ai tenu tête aux brise-crânes et aux prophètes troggs dans les collines du sud, pour gagner du temps jusqu'au retour des nains du front de l'Alliance",
    [240] = "ai rapporté les gâteaux au crabe brun à Jitters, affamé dans sa cachette de la ville fantôme",
    [244] = "ai averti l'adjoint Feldon que des camps de gnolls se rassemblaient près de la route, une force qui pourrait avancer jusque dans [[Elwynn Forest]]",
    [245] = "ai éliminé les araignées Tisse-venin pygmées qui envahissaient la frontière ouest de [[Duskwood]], trop nombreuses pour le Guet de nuit",
    [246] = "ai harcelé les camps de gnolls le long de la route du sud des Carmines pour en estimer le nombre pour l'adjoint Feldon, qui n'avait pas d'hommes à disposition",
    [247] = "ai achevé la chasse de [[Ashenvale]] pour [[name:Senani Thunderheart]], ses trois bêtes légendaires tuées et leurs trophées rapportés",
    [248] = "ai caché un glyphe d'Azora au sommet de la tour de guet près de [[Stonewatch Keep]], pour que Theocritus puisse sonder les esprits qui s'y trouvaient",
    [249] = "suis $gentré:entrée; dans [[Tower of Ilgalar]] pour vaincre Morganth avant qu'il ne trouve la Faux d'Elune et ne la retourne contre [[Stormwind City]]",
    [250] = "ai fouillé la rampe est de [[Stonewrought Dam]], où l'on avait vu des sapeurs Sombrefer, à la recherche d'un indice sur leur prochaine attaque",
    [251] = "ai fait traduire par Sirra Von'Indi, savante en langues et en arts anciens, l'étrange lettre d'Abercrombie au maire",
    [252] = "ai porté la lettre traduite au seigneur Ello Ebonlocke, révélant que l'aide apportée à Abercrombie avait condamné [[Darkshire]]",
    [253] = "ai pris le cœur encore battant de l'Embaumeur sur la tombe de sa femme Eliza, pour briser son pouvoir et protéger la ville de [[Darkshire]]",
    [255] = "ai combattu les ogres Mo'grosh installés au bord du lac pour le magistrat Bluntnose, tandis que [[Thelsamar]] attendait des soldats depuis des mois",
    [256] = "ai traqué Chok'sul, l'ogre derrière les attaques contre [[Thelsamar]], le barrage et le site de fouilles",
    [257] = "ai relevé le défi fanfaron de Daryl le Jeunot, abattre une volée de busards des montagnes contre la montre",
    [258] = "ai couru contre la montre face aux vieux sangliers des montagnes pour donner tort à Daryl le Jeunot une seconde fois",
    [261] = "ai détruit les ravageurs morts-vivants de [[Valley of Bones]] pour prouver ma loyauté envers le frère Anton et la Croisade écarlate",
    [262] = "ai montré le livre de la ferme de Sven dans tout [[Darkshire]], pour trouver le rôdeur que Sven avait vu la nuit où sa famille avait été tuée",
    [263] = "ai tué des chamans et des briseurs d'os troggs pour le montagnard Wallbang, les réservistes appelés au front et les gardes laissés seuls",
    [265] = "me suis $grenseigné:renseignée; dans [[Darkshire]] sur le propriétaire du livre, un étranger nerveux et agité qui l'avait acheté en ville un mois plus tôt",
    [266] = "ai cherché à l'auberge des nouvelles du propriétaire du livre, parti en hâte vers l'ouest en marmonnant qu'on le traquait",
    [267] = "ai porté le combat aux troggs dans les collines pour le capitaine Rugelfuss, dont le régiment ne pouvait quitter sa porte",
    [268] = "ai porté à Sven le journal complet de Jitters, pour ce qu'il racontait des cavaliers noirs et de Morbent Fel",
    [269] = "ai apporté le journal de Jitters à l'évêque Farthing, à la cathédrale de la Lumière, pour prendre conseil avant d'affronter Morbent Fel",
    [270] = "ai interrogé Glorin Steelbrow à [[Menethil Harbor]] au sujet du fer de sancteforge perdu en mer, le métal d'une arme contre Morbent Fel",
    [271] = "ai tué le vieux Noiraud, l'ours qui avait laissé sa cicatrice à Daryl le Jeunot, à l'instigation de Vyrin Swiftwind",
    [272] = "ai trouvé et réuni les deux moitiés du pendentif du lion de mer, la preuve de l'agilité et de l'endurance qu'exige une forme aquatique",
    [273] = "ai rattrapé le chargement de poudre de Huldar vers le site de fouilles juste au moment où le porteur Saean se révélait un partisan des Sombrefer",
    [274] = "suis $grevenu:revenue; en hâte auprès de Hinderweir annoncer que la poudre était de l'hydroglycérine, de quoi, une fois mouillée, faire sauter [[Ironforge]] hors de la montagne",
    [275] = "ai abattu les rampants des tourbières malades pour Rethiel le Gardevert, pour que la fièvre qui couvait [[at:Wetlands]] retombe",
    [276] = "ai décimé les gnolls Poil-moussu près de la porte d'Algaz pour Rethiel le Gardevert, leur nombre croissant piétinant le marais",
    [277] = "ai pris aux Poil-moussu leurs silex bruts pour que Rethiel le Gardevert les jette à la mer, mettant fin à leurs incendies de bois vivant",
    [278] = "ai rassemblé du venin de rôdeuse, un cristal Mo'grosh et une larme de crocilisque pour le mélange capable de désamorcer l'hydroglycérine des Sombrefer",
    [279] = "ai tué Enfourneur et les siens, des murlocs Branchie-bleue, pour la marine marchande, les murlocs qui harcelaient les marchands sur la route côtière",
    [280] = "ai plongé jusqu'au tonneau des Sombrefer au pied de [[Stonewrought Dam]] pour y verser le mélange désamorçant avant qu'il n'explose",
    [281] = "ai fouillé les camps murlocs de la côte à la recherche de la cargaison arrachée à la Princesse aveugle, dont une précieuse statuette de Terenas Menethil",
    [284] = "ai fouillé d'autres huttes murlocs le long de la côte à la recherche de la statuette de Menethil disparue",
    [285] = "ai fouillé les dernières huttes murlocs au nord, $gcertain:certaine; d'approcher de la statuette de Menethil",
    [286] = "ai rendu la statuette de Menethil à Karl Boran, une cargaison précieuse perdue quand les murlocs avaient pillé la Princesse aveugle",
    [287] = "ai repéré [[Frostmane Hold]] et tué ses chasseurs de têtes pour Senir Whitebeard, qui avait vu trop de trolls pour oser y entrer",
    [288] = "ai payé une cruche d'hydromiel au second Fitzsimmons, seul survivant de la funeste troisième flotte, pour qu'il puisse finir son histoire",
    [289] = "ai abattu l'équipage maudit de la troisième flotte, le second Snellig parmi eux, pour libérer les âmes des compagnons de bord de Fitzsimmons",
    [290] = "ai pris la clé du coffre au capitaine Halyndor, qui hantait encore l'Intrépide condamné, pour atteindre la chose maudite qui liait son équipage",
    [291] = "ai porté le rapport de Senir Whitebeard sur les trolls au sénateur Barin Redstone, d'humeur maussade, à [[Ironforge]]",
    [292] = "ai apporté l'œil maudit de Paleth, tiré de l'Intrépide, au prêtre Glorin Steelbrow, dans l'espoir d'apprendre à lever sa malédiction",
    [293] = "ai porté l'œil maudit de Paleth à l'archevêque Benedictus à [[Stormwind City]] pour qu'il soit purifié, le moyen de libérer les morts maudits de la troisième flotte",
    [294] = "ai tué des raptors et des hurleurs tachetés pour Ormer Ironbraid, dont les frères avaient péri sous les griffes des raptors au site de fouilles de Whelgar",
    [295] = "ai tué des faucheurs et des tranchegueules tachetés sous la falaise, pour faire payer aux raptors la mort des nains du chantier de fouilles",
    [296] = "ai traqué Grondecroc, le grand raptor qu'Ormer Ironbraid accusait d'avoir mené l'attaque contre le chantier, et rapporté une serre pour preuve",
    [297] = "ai arraché aux troggs de [[Ironband's Excavation Site]] des idoles sculptées, des reliques qui les rendaient fous furieux, pour que Magmar Fellhew les étudie",
    [298] = "ai apporté le rapport d'état d'Ironband et sa supplique pour plus de poudre explosive à Jern Hornhelm à [[Thelsamar]]",
    [299] = "ai déterré les quatre fragments perdus de la pierre de Goaz pour le prospecteur Whelgar, une tablette des Titans qui parlait d'une funeste prophétie",
    [301] = "ai porté le rapport d'Ironband au prospecteur Stormpike à [[Ironforge]], qui avait envoyé des semaines plus tôt de la poudre jamais arrivée",
    [303] = "ai repoussé les nains Sombrefer à [[Dun Modr]] pour Motley Garmason, pour que la réserve arrive à temps pour achever l'offensive",
    [304] = "ai tué Balgaras l'Immonde, le lâche démoniste Sombrefer qui menait les brutes qui avaient pris [[Dun Modr]], pour Longbraid le Sinistre",
    [305] = "ai cherché Merrin Rockweaver au chantier de fouilles pour son mari Tarrel, inquiet, sans lettre d'elle depuis deux semaines",
    [306] = "ai porté la note de Merrin à Tarrel, qui lui apprenait que les raptors avaient envahi le chantier et que seuls trois membres de l'équipe avaient survécu",
    [307] = "ai sauvé le matériel de la Ligue des mineurs dans [[Silver Stream Mine]] infestée de kobolds, avant que les guerriers ne la prennent d'assaut",
    [309] = "ai escorté Miran et la poudre explosive jusqu'à [[Ironband's Excavation Site]], avec des partisans des Sombrefer qui rôdaient sur la route",
    [310] = "ai glissé un tonneau de Barleybrew Scalder dans la cave des Thunderbrew, pour leur apprendre que leur bière n'était pas la seule bonne",
    [311] = "ai rapporté un tonneau de Thunder Ale chapardé à Marleth Barleybrew pour preuve de l'échange",
    [312] = "me suis $gglissé:glissée; dans la grotte du vieux Barbe-de-glace pour la viande séchée de Tundra MacGrann, un mois de vivres sans lesquels il mourrait de faim",
    [313] = "ai pris des crinières de wendigo dans [[Grizzled Den]] pour le pilote Stonegear, un tapis pour le pont de son engin de siège Charrue-à-trolls",
    [314] = "ai tué Vagash, la bête qui s'attaquait aux béliers d'Amberstill pendant que l'essentiel de l'armée de Magni était à la guerre",
    [315] = "ai chapardé de la chatoyante aux trolls Frostmane pour Rejold Barleybrew, qui voulait brasser la stout parfaite",
    [317] = "ai chassé de la viande de sanglier et des fourrures d'ours pour approvisionner le char Jetvapeur du pilote Bellowfiz pour une mission d'un mois de la brigade de siège",
    [318] = "suis $gallé:allée; chercher un tonneau d'Evershine pour le pilote Bellowfiz, une boisson pour le réchauffer sur la route froide et brûler dans la chaudière de Jetvapeur",
    [319] = "ai chassé les ours, les sangliers et les léopards des neiges des abords de [[Brewnall Village]] pour que ses nains puissent reprendre leur brassage",
    [320] = "ai apporté au pilote Bellowfiz son tonneau d'Evershine, du feu pour la chaudière de Jetvapeur pendant la longue mission à venir",
    [321] = "ai fouillé l'épave du Balbuzard volant à la recherche de son fer de sancteforge, pour n'y trouver que le coffre éventré par les griffes des murlocs",
    [322] = "ai porté les lingots de sancteforge à Grimand Elmore à [[Stormwind City]], pour forger une arme qui inquiéterait même Morbent Fel",
    [323] = "ai combattu les sbires squelettes de Morbent Fel, pour que Sven sache quelle force il fallait pour affronter le nécromancien",
    [324] = "ai chassé les écumeurs murlocs près de l'épave du Balbuzard volant pour les lingots de sancteforge qu'ils avaient volés",
    [325] = "ai apporté à Sven le Fléau de Morbent, forgé dans le fer de sancteforge, une protection contre le démon Morbent Fel",
    [328] = "ai ouvert le coffre de [[name:Bookie Herod]] dans la Réserve avec une clé cachée dans son registre, dans l'espoir de savoir comment Thorsen avait été démasqué",
    [329] = "ai porté une note boueuse tirée du coffre de Herod au lieutenant Doren, l'indice d'un traître dans le camp rebelle",
    [330] = "ai vérifié les plans de patrouille du caporal Sethman pour savoir qui avait livré les itinéraires de Thorsen, et donc qui l'avait trahi",
    [331] = "ai démasqué le soldat Merle, l'espion caché parmi les rebelles du lieutenant Doren, un traître qu'ils n'auraient pas pu garder longtemps sans y laisser la vie",
    [333] = "ai porté au tailleur du canal la demande de Harlan Bagley, qui voulait plus de vêtements tricotés, son stock épuisé maintenant que tout le monde achetait des armures",
    [334] = "ai apporté au jeune Thurman Schneider la trousse de couture qu'il avait oubliée, sans laquelle il ne pouvait faire son travail d'apprenti",
    [335] = "ai rassemblé une larme de Tilloa et une racine de Musquash pour Zardeth de la Griffe noire, qui voulait empêcher le seigneur Wishock de dénoncer les démonistes",
    [336] = "ai servi au seigneur Wishock une bouteille de bière brune de la Griffe noire de Zardeth, pour que les démonistes de [[Stormwind City]] pratiquent leur art en paix",
    [338] = "ai rassemblé les pages éparses du roman de [[name:Hemet Nesingwary]] pour [[name:Barnil Stonepot]], qui avait laissé le vent les disperser dans la jungle",
    [339] = "ai reconstitué le premier chapitre des Vertes collines de Strangleronce, où Nesingwary nomme ses compagnons de chasse",
    [340] = "ai retrouvé les pages perdues du deuxième chapitre du roman de Nesingwary, ses récits de chasse à la panthère et au tigre, pour [[name:Barnil Stonepot]]",
    [341] = "ai restauré le troisième chapitre du manuscrit de Nesingwary, avec la première prise d'Erlgadin et de Rouack au fusil nain",
    [342] = "ai retrouvé les dernières pages du quatrième chapitre, le final des Vertes collines de Strangleronce, pour [[name:Barnil Stonepot]]",
    [346] = "ai enfin rendu Les tensions du fer au frère Kristoff, pour son discours sur la Force d'âme",
    [347] = "ai extrait du minerai de rethban des cavernes de Rethban, aux mains des gnolls, pour que le frère Paxton prépare l'encre qui lui permettrait d'achever la copie de son livre",
    [348] = "suis $gallé:allée; chercher le cœur de Mokk le Sauvage, invoqué par le sorcier-docteur Unbagwa, seul remède à la fièvre mortelle de [[name:Fin Fizracket]]",
    [351] = "ai suivi une balise de détresse jusqu'au robot de repérage d'Oglethorpe, écrasé près de [[Gaping Chasm]]",
    [353] = "ai porté la nouvelle hache de Grimand Elmore jusqu'au montagnard Stormpike à [[Loch Modan]], impatient de l'essayer sur les troggs et les kobolds",
    [354] = "ai détruit les Agamand relevés pour leurs restes, la vengeance de Coleman Farthing, que leur orgueil avait condamné à la non-vie",
    [356] = "ai patrouillé derrière [[The Bulwark]] pour tuer le Fléau qui passait au travers, pour que ses défenseurs n'aient pas d'attaque à craindre par l'arrière",
    [357] = "ai volé le grimoire de la liche de l'île de [[Brightwater Lake]], qui a appris à Bethor Iceshard qu'il s'agissait de Gunther Arcanus",
    [358] = "ai tué les gnolls Poil-Putride qui pillaient les charniers pour les armées du Fléau, et pris leur ichor pour les apothicaires",
    [361] = "ai livré la dernière lettre de Thurman Agamand à Yvette Farthing, qui l'avait supplié de quitter avec elle [[Agamand Mills]]",
    [362] = "ai détruit Devlin Agamand, dont le bavardage dément s'entendait encore depuis les moulins, pour que Coleman Farthing ait ses os",
    [365] = "ai volé des potirons dans une ferme au nez de la Croisade écarlate pour l'apothicaire Johaan, une première leçon dans les manières des Réprouvés",
    [366] = "ai rendu le grimoire de Gunther avec l'enchantement de Bethor, dans l'espoir que la liche libérée rejoigne les Réprouvés",
    [367] = "ai rassemblé du sang de sombredogue pour l'apothicaire Johaan, une première étape vers une nouvelle peste qui mènerait le Fléau à sa ruine",
    [368] = "ai rassemblé des écailles d'Aileron noir pour la peste de Johaan, car empester un monde entier demandait plus qu'empoisonner une seule victime",
    [369] = "ai tiré le venin des araignées Tisse-nuit vicieuses, l'agent d'une peste ancienne, pour achever la nouvelle mixture mortelle de Johaan",
    [370] = "ai tué le capitaine Perrine et sa brigade à la tour au sud-ouest de [[Brill]], trouvés grâce aux documents pris à la Croisade",
    [371] = "ai abattu le capitaine Vachon et ses frères, des pillards de la tour en ruine près de la ferme des Balnir, pour ralentir la Croisade",
    [372] = "ai assassiné le capitaine Melrache, commandant impitoyable des croisés qui pillaient au-delà de [[Faol's Rest]], et ses deux gardes du corps",
    [373] = "ai apporté la lettre jamais envoyée d'Edwin VanCleef à Baros Alexston, l'architecte de la ville, qui avait été autrefois tailleur de pierre avec lui",
    [374] = "ai pris des anneaux de la Croisade écarlate sur des croisés tués, la preuve de ma loyauté envers Varimathras et la Dame noire",
    [375] = "ai apporté des peaux de chauve-souris et du fil à Gretchen Dedmar, pour que des mains tremblant du froid de la peste puissent coudre une couverture",
    [377] = "ai assassiné Dextren Ward dans [[Stormwind Stockade]] pour le conseiller Millstipe, le vendeur de cadavres que [[Stormwind City]] avait sauvé du billot",
    [378] = "ai tué Kam Deepfury dans [[Stormwind Stockade]], le Sombrefer dont le plan pour abattre [[Thandol Span]] avait coûté sa famille à Longbraid",
    [379] = "ai arraché des outres d'eau aux nomades Bat-le-désert pour que l'ingénieur en chef Bilgewhizzle me cède une source d'énergie",
    [384] = "ai rassemblé des côtes de sanglier des rochers et une bière au malt Rhapsody pour Ragnar Thunderbrew, dont le trappeur était parti à la guerre, pour sa recette de famille",
    [385] = "me suis $gcolleté:colletée; aux crocilisques des îles du lac pour leur viande et leurs peaux, le commerce du pavillon des Pérégrins",
    [386] = "ai décapité Targorr le Terrible, l'impitoyable bourreau de Gath'Ilzogg, dont la sentence avait été mystérieusement suspendue par quelque noble",
    [387] = "ai maté les détenus défias qui se mutinaient dans [[Stormwind Stockade]] pour le directeur Thelwater, pour la sécurité de [[Stormwind City]]",
    [388] = "ai pris les foulards en laine rouge des Défias pour Nikova Raskol, dont le petit-fils Mac avait été poignardé pour avoir grondé les prisonniers qui les fabriquaient",
    [391] = "ai tué Bazil Thredd, le chef défias derrière les émeutes de la prison, pour prouver ma loyauté au méfiant directeur Thelwater",
    [392] = "ai porté une description du mystérieux visiteur de Bazil Thredd, Maelik, à Baros Alexston, dans l'espoir qu'il connaisse l'homme",
    [393] = "ai porté la description à Mathias Shaw du SI:7, qui connaissait le visiteur, un assassin à la solde du seigneur Gregor Lescovar",
    [396] = "ai livré le rapport de Baros Alexston sur les Défias au donjon de [[Stormwind City]], et reçu des éloges pour avoir déjoué les machinations de VanCleef",
    [398] = "ai exécuté Œil-de-ver, le gnoll qui volait des cadavres près de [[Garren's Haunt]] pour l'armée du roi-liche, pour la récompense de [[Brill]]",
    [399] = "ai fouillé la ferme incendiée des Alexston [[at:Westfall]] à la recherche de la première boussole de Baros Alexston, un souvenir de son enfance",
    [400] = "ai livré une nouvelle commande d'outils à Beldin Steelgrill, qui avait cassé son dernier croc-cliquet en pleine réparation d'un engin de siège",
    [404] = "ai repoussé le Fléau qui s'était glissé près du vieux pont à l'ouest de [[Brill]], pour les gardes de la Mort",
    [407] = "ai fait manger un potiron arrosé de la dernière formule de Johaan au zélote écarlate captif dans la cave de la taverne du Gibet",
    [408] = "ai abattu les ancêtres Agamand dans la crypte de la famille et pris le crâne du capitaine Dargol, le chef du Fléau en ces lieux",
    [409] = "ai invoqué et détruit Lillith Nefara à son autel sanglant, la preuve pour Gunther que j'étais $gun ennemi:une ennemie; du roi-liche",
    [411] = "ai apporté la gemme du Néant de Gunther à Bethor Iceshard pour que les anciens camarades puissent parler, la liche égarée enfin gagnée à notre cause",
    [412] = "ai pris des rouages et des engrenages aux gnomes lépreux aux portes de [[Gnomeregan]] pour le recombobulateur de Razzle Sprysprocket, censé inverser leur sort",
    [413] = "ai porté un tonneau de la nouvelle Shimmer Stout de Rejold à son frère Wellart, à la tour de garde à la frontière de [[Loch Modan]]",
    [414] = "ai porté un bidon de Shimmer Stout au montagnard Kadrell à [[Thelsamar]], pour qu'un collègue montagnard goûte la dernière bière des Barleybrew",
    [416] = "ai délogé les kobolds rats des tunnels des contreforts à l'ouest de [[Thelsamar]] pour la prime sur leurs oreilles",
    [417] = "ai tué Griffe-galeuse, l'ours Griffeglace qui avait déchiqueté le pilote Hildelve, comme le demandait le journal du pilote mort",
    [418] = "ai rassemblé de la viande d'ours, des tripes de sanglier et de l'ichor d'araignée pour les célèbres boudins de Vidra Hearthstove",
    [419] = "ai trouvé le pilote Mori Hildelve dans les collines, gelé et mort, parti à la recherche d'un minerai rare pour la poudre explosive",
    [420] = "ai porté le rapport de Grelin Whitebeard par le tunnel infesté de troggs jusqu'à son frère Senir à [[Kharanos]]",
    [421] = "ai tué des Poil-blanc Ragelune pour me montrer digne de Dalar Dawnweaver, qui comptait débarrasser [[Silverpine Forest]] de la malédiction d'Arugal",
    [422] = "ai pris le remède d'Arugal dans les grimoires de la ferme à blé, pour que Dalar Dawnweaver apprenne la magie qui s'y cachait",
    [423] = "ai pris des bracelets enchantés aux worgens Ragelune pour Dalar Dawnweaver, les objets dont Arugal se servait pour étayer sa faible magie",
    [424] = "ai décapité Grimson le Blafard, le contremaître corrompu de [[Deep Elem Mine]], pour gagner la mine à l'avancée de Varimathras",
    [425] = "ai tué Ivar l'Immonde, la goule qui avait déchiqueté Quinn Yorick, pour que le traqueur noir blessé ait le temps de guérir",
    [426] = "ai brisé le Fléau à [[Agamand Mills]] avant qu'il n'en fasse une base pour attaquer tout [[Tirisfal Glades]]",
    [427] = "ai tué des guerriers écarlates à la tour au-delà de la ferme des Solliden, pour me montrer digne de servir la Dame noire",
    [428] = "ai retrouvé les traqueurs noirs Rane et Quinn Yorick, disparus depuis des semaines lors d'une mission de reconnaissance au nord de [[Silverpine Forest]]",
    [429] = "ai rassemblé des cœurs de worg décolorés pour que l'apothicaire Renferrel prépare une potion de soins pour Quinn Yorick, gravement blessé",
    [430] = "ai livré la potion de l'apothicaire Renferrel à Quinn Yorick à [[Ivar Patch]], pour qu'il puisse reprendre la route",
    [432] = "ai tué des brise-crânes Mâcheroc dans la carrière de Gol'Bolar pour le contremaître Stonebrow, furieux qu'ils aient saccagé son chantier",
    [433] = "ai chassé les briseurs d'os Mâcheroc de la carrière de Gol'Bolar pour le sénateur Mehr Stonehallow, pour que les mineurs reprennent le travail",
    [434] = "ai tué le seigneur Gregor Lescovar et l'assassin Marzon dans le jardin du château, alors qu'ils se retrouvaient pour comploter avec les Défias",
    [435] = "ai escorté Erland en évitant les loups affamés jusqu'au traqueur noir Rane Yorick, qui l'avait cru perdu",
    [437] = "ai attaqué les gnolls Poil-Putride de [[Dead Field]] jusqu'à l'apparition de la banshee Cinglenuit, et l'ai détruite pour les Réprouvés",
    [438] = "ai enquêté sur le Bac décrépit, où se rassemblait le Fléau, et trouvé un tas de cadavres emballés en partance pour [[Fenris Isle]]",
    [439] = "ai apporté au grand exécuteur Hadrec un anneau pris sur un cadavre frais du bac, la preuve que les gnolls Poil-Putride pillaient les tombes de [[Tirisfal Glades]]",
    [440] = "ai montré l'anneau de Deliah au magistrat Sevren à [[Brill]], qui a confirmé que les gnolls Poil-Putride avaient volé son corps",
    [441] = "ai rendu l'anneau de Deliah à son mari Raleigh à [[Undercity]], qui voulait se venger",
    [442] = "ai pris d'assaut [[Fenris Isle]] pour détruire Thule Ravenclaw, le mage traître qui menait les gnolls Poil-Putride pour le Fléau",
    [443] = "ai prélevé de l'ichor sur les gnolls Poil-Putride de [[Fenris Isle]] pour que l'apothicaire Renferrel sache qui était derrière eux",
    [444] = "ai porté l'ichor de Poil-Putride à Bethor Iceshard à [[Undercity]], dont la science de la magie pourrait percer l'origine des gnolls",
    [445] = "ai porté les découvertes de l'apothicaire Johaan à l'apothicaire Renferrel [[at:The Sepulcher]], vers la nouvelle peste que désirait la Dame noire",
    [446] = "ai livré le parchemin de Bethor Iceshard à l'apothicaire Renferrel, de quoi faire une potion contre les sorts de Thule Ravenclaw",
    [447] = "ai rassemblé des cœurs d'ours et du sang d'araignée pour le maître apothicaire Faranell, les ingrédients d'une nouvelle peste pour le Fléau comme pour les humains",
    [449] = "ai porté le rapport des traqueurs noirs au grand exécuteur Hadrec, la nouvelle d'une présence du Fléau que personne n'avait prévue",
    [450] = "me suis $gglissé:glissée; dans l'auberge de [[Pyrewood Village]] pour le journal de l'apothicaire Berard, un homme maudit par Arugal qui avait étudié une peste ancienne",
    [451] = "ai rassemblé de la mousse de lac et une rare tumeur de murloc pour la nouvelle peste du maître apothicaire Faranell, comme le conseillait le journal de Berard",
    [452] = "ai aidé la traqueuse noire Faerleia à tendre une embuscade au conseil de Bois-du-Bûcher, les marionnettes par lesquelles Arugal régnait sur le village maudit",
    [453] = "ai pisté l'étranger nerveux qui avait quitté [[Darkshire]] vers l'ouest, et l'ai trouvé caché, fuyant ce qui le traquait",
    [455] = "me suis frayé un passage à travers [[Dun Algaz]] contre les orcs Dragonmaw, dont la tête de pont menaçait de couper [[Loch Modan]] de [[Menethil Harbor]]",
    [460] = "ai réuni la tête d'Alaric, le garde du corps de Thule Ravenclaw, et son corps, que les gnolls avaient enterré dans une tombe anonyme à [[Fenris Keep]]",
    [461] = "ai porté le corps d'Alaric jusqu'à une alcôve cachée de [[Fenris Keep]], où il voulait reposer entre les murs qu'il avait aimés",
    [464] = "ai attaqué le campement Dragonmaw au nord-est de Menethil et pris leurs étendards de guerre pour preuve, pour le capitaine Stoutfist",
    [465] = "ai brûlé les catapultes que Nek'rosh avait construites pour assiéger [[Menethil Harbor]], coupé de tout renfort",
    [466] = "ai extrait du minerai d'incendicite instable [[at:Wetlands]] pour le pilote Stonegear, qui espérait en tirer des obus de canon d'une puissance redoutable",
    [469] = "ai porté le lot de peaux de crocilisques d'Einar à James Halloran, pour qu'Einar puisse retarder le moment d'affronter sa femme",
    [470] = "ai récupéré le sac de Sidonie parmi les limons de [[Ironbeard's Tomb]], où elle l'avait jeté pour leur échapper",
    [471] = "ai dépecé des crocilisques géants pour James Halloran, dont les brutes avaient laissé l'apprenti à moitié mort",
    [472] = "ai cherché Longbraid près de [[Dun Modr]] tombé, pour un soldat blessé de Menethil qui espérait que son chef vivait encore",
    [474] = "ai tué le chef Nek'rosh des Dragonmaw, un coup sévère pour le clan qui comptait assiéger [[Menethil Harbor]]",
    [476] = "ai apporté à Athridas Bearmantle les graves nouvelles du gardien blessé Gaerolas : la gangremousse avait rendu fous les furbolgs Pin-tordu",
    [477] = "ai forcé une caisse des sorciers de Dalaran près de [[Pyrewood Village]], pour savoir pourquoi ils envoyaient des fournitures à ce trou perdu de [[Ambermill]]",
    [478] = "ai remis l'étrange pendentif de la caisse des sorciers au prêtre des ombres Allister, un indice sur les desseins de Dalaran à [[Ambermill]]",
    [479] = "ai arraché des pendentifs de Dalaran aux sorciers de [[Ambermill]] pour ralentir leurs travaux sur le nœud de ligne tellurique endormi",
    [480] = "ai tué l'archimage de Dalaran qui réveillait le nœud tellurique de [[Ambermill]], et rapporté son bâton au prêtre des ombres Allister",
    [481] = "ai montré le pendentif marqué de runes à Dalar Dawnweaver, qui y a reconnu un outil du Kirin Tor pour canaliser la magie",
    [483] = "ai récupéré les reliques de l'Éveil dans [[Ban'ethil Barrow Den]] ravagée, de peur que les druides de la Griffe endormis ne se perdent dans le Rêve",
    [484] = "ai dépecé de jeunes crocilisques pour James Halloran, le tanneur dont les peaux traitées partaient vers des ports du monde entier",
    [485] = "ai apporté une balise de détresse au robot de repérage d'[[name:Oglethorpe Obnoticus]], écrasé à la source de la rivière près de [[Skulk Rock]]",
    [486] = "ai tué Ursal le Mutileur, le chef Pin-tordu qui avait rendu sa tribu folle, pour que les druides de la Griffe puissent être réveillés",
    [487] = "ai chassé les embusqués Pin-tordu de la route de [[Darnassus]], où les voyageurs qui apportaient nouvelles et marchandises se faisaient attaquer",
    [488] = "suis $gallé:allée; chercher crocs, plumes et soie d'araignée pour Zenn Foulhoof, un satyre qui se moquait des naïfs qui le servaient",
    [489] = "ai glissé à Zenn Foulhoof des gangrenoix en guise d'en-cas d'apparence inoffensive, la leçon qu'exigeait le Conseil de la forêt pour l'avoir servi",
    [491] = "ai remis la baguette tressée, gage d'une amitié que Thule avait trahie, à son ancien collègue Bethor Iceshard",
    [492] = "ai servi la boisson spéciale de Johaan à un montagnard nain captif, un avant-goût de ce que la Dame noire prévoyait pour le reste d'Azeroth",
    [493] = "ai porté les découvertes de l'apothicaire Renferrel sur la nouvelle peste à l'apothicaire Lydon à [[Tarren Mill]], pour accélérer les travaux",
    [500] = "ai chassé les ogres Cognecrête pour leurs osselets, pour qu'ils ne s'installent pas dans les ruines d'Alterac et ne descendent pas sur [[Southshore]]",
    [504] = "ai abattu les va-t-en-guerre Cognecrête dans les ruines d'Alterac, pour apprendre aux ogres à se tenir loin de [[Southshore]]",
    [505] = "ai tué des voleurs et des tire-laines du Syndicat près de [[Tarren Mill]], la bande qu'on soupçonnait du meurtre du dernier magistrat de [[Southshore]]",
    [510] = "ai remis les plans inquiétants du Syndicat au magistrat Maleb, une liste de fournitures urgente pour une mission contre [[Southshore]]",
    [511] = "ai porté une lettre chiffrée trouvée sur le Syndicat au maître des traditions Dibbs à [[Southshore]], dans l'espoir qu'il saurait la lire",
    [512] = "ai tué les nobles d'Alterac cachés dans le Syndicat à [[Strahnbrad]] pour leurs chevalières, pour priver la bande de ses chefs",
    [514] = "ai porté la lettre habilement chiffrée au prospecteur Stormpike à [[Ironforge]], le seul érudit susceptible de la lire",
    [516] = "ai trouvé le Péril de Beren, où les morts-vivants se massaient pour attaquer, et les ai frappés les premiers pour le prêtre des ombres Allister",
    [522] = "ai apporté au magistrat Maleb le contrat de son propre assassinat, scellé de cire rouge avec une chevalière bien reconnaissable",
    [523] = "ai traqué le baron Vardus, le noble d'Alterac au cœur froid qui avait signé le contrat sur la vie du magistrat Maleb",
    [525] = "ai apporté au magistrat Maleb la lettre déchiffrée, qui montrait que le Syndicat avait des liens avec une autre puissance, plus sombre",
    [526] = "ai repris aux murlocs les lingots de sancteforge qu'ils avaient emportés, puisqu'un seul ne permettait de rien forger de convenable",
    [530] = "ai tué Valdred Moray à [[Greymane Wall]] et rapporté ses mains à Raleigh Andrean, dont Moray avait étranglé la femme",
    [531] = "ai présenté la tête du vieux Noiraud à Vyrin Swiftwind, qui brûlait depuis des mois de rabattre le caquet à ce prétentieux de Daryl",
    [535] = "suis $gallé:allée; chercher une chope de stout de Southshore pour Valik, un homme du Syndicat mourant, en échange de ce qu'il savait",
    [537] = "ai tué Nagaz et les mages de l'ombre d'Argus dans les hautes terres d'Alterac, envoyés du Sillage d'Argus alliés au Syndicat",
    [540] = "ai sauvé des livres des mains des ogres dans les ruines d'Alterac pour le maître des traditions Dibbs, dont le savoir troll du Bras de Gri'lek",
    [542] = "ai rapporté les tomes d'Alterac retrouvés à Milton Sheaf, sauvant leur savoir pour la bibliothèque royale de [[Stormwind City]]",
    [543] = "ai repris la tiare de Perenolde, héritage des souverains déchus d'Alterac, au mage ogre Grel'borg l'Avare",
    [551] = "ai porté le parchemin ensorcelé portant le nom de Nagaz au maître des traditions Dibbs, dans l'espoir qu'il briserait son sort",
    [554] = "ai apporté le parchemin ensorcelé au prospecteur Stormpike à [[Ironforge]], un maître du déchiffrement, pour qu'il y comprenne quelque chose",
    [568] = "ai éliminé [[les:Lashtail Raptor]] aux abords de Grom'gol, qui menaçaient la ligne de ravitaillement de la Horde vers [[Stonard]]",
    [569] = "ai frappé les ogres des ruines de Mizjah, qui tendaient sans cesse des embuscades aux caravanes destinées à ravitailler [[Stonard]]",
    [570] = "ai rassemblé des griffes d'Ombregueule et un croc de tigresse intact, les premiers composants d'un enchantement que le Grand prophète Mok'thardin voulait faire",
    [571] = "ai chassé [[les:Elder Mistvale Gorilla]] pour un tendon vieilli sans défaut, le lien magique qui tiendrait le charme de Mok'thardin",
    [572] = "ai arraché des plumes aux traqueurs de la jungle au sud de Grom'gol pour l'enchantement du Grand prophète Mok'thardin",
    [573] = "suis $gallé:allée; chercher l'eau de la source sacrée en évitant les explorateurs nagas qui s'en étaient approchés, le dernier composant du collier de Mok'thardin",
    [574] = "ai brisé les commandos et les réducteurs de têtes de Kurzen dans la Réserve, ses meilleures troupes, et rendu aux rebelles l'espoir de survivre",
    [575] = "ai dépecé des crocilisques de rivière pour [[name:Drizzlik]], le travailleur du cuir de [[Booty Bay]], qui avait une douzaine de bottes Excelsior à fabriquer",
    [576] = "ai repris aux boucaniers de la Voile sanglante qui l'avaient agressé l'œil de verre enchanté de [[name:Dizzy One-Eye]], pour que le vieux loup de mer y voie à nouveau",
    [577] = "ai pris des peaux de crocilisques Gueule d'acier, moins chères, au lac Nazferiti, pour les doublures des bottes de [[name:Drizzlik]]",
    [578] = "ai trouvé l'île hantée au large pour le baron Revilgaz, qui espérait que la Pierre des marées serait bientôt à lui",
    [580] = "ai repêché dans la mer les bouteilles de porto Pupellyverbos de [[name:Whiskey Slim]], avant que son capitaine ne lui fasse goûter du chat à neuf queues",
    [581] = "ai chassé les Bloodscalp pour leurs défenses, afin de prouver que j'étais capable d'aider Nimboya à chercher Yenniku, le fils perdu de son chef",
    [582] = "ai pris des têtes réduites aux chasseurs de têtes Bloodscalp, pour que Nimboya s'assure que celle de Yenniku n'en faisait pas partie",
    [584] = "ai tué Gan'zulah, chef des Bloodscalp, et Nezzliok le Terrible, leurs têtes destinées au chaudron de Nimboya pour arracher la vérité sur Yenniku",
    [585] = "ai volé des crânes trophées Skullsplitter dans trois ruines pour apaiser l'esprit de Nezzliok, qui savait où Yenniku avait été emmené",
    [586] = "me suis frayé un chemin jusqu'au cœur des Skullsplitter pour vaincre leur chef, Ana'thek le Cruel, comme l'exigeait l'esprit furieux de Gan'zulah",
    [587] = "ai repris le tabac à priser que les écumeurs de la Voile sanglante avaient détourné, pour Deeg, un pirate qui n'en trouvait pas à [[Booty Bay]]",
    [588] = "ai annoncé à Kin'weelay que Zanzil le Paria tenait Yenniku corps et âme, et qu'il ne restait qu'un mince espoir",
    [589] = "ai rassemblé [[des:Pulsing Blue Shard]] sur les basilics Mâchefer de la mine de Veine-de-cristal, la magie dont Kin'weelay avait besoin pour plier la Vue de l'esprit",
    [591] = "ai arraché la Vue de l'esprit au mage ogre [[name:Mai'Zoth]] dans le tertre Mosh'Ogg, le seul espoir de sauver Yenniku",
    [592] = "ai capturé l'âme de Yenniku dans une gemme aux ruines d'Aboraz et l'ai portée à Nimboya, le libérant de Zanzil le Paria",
    [594] = "ai cherché l'auteur d'un message dans une bouteille, une captive retenue par un grand Crins-du-ciel sur une île des mers du Sud",
    [595] = "ai repéré la crique au nord de [[Booty Bay]] pour le second Crazz, après des rumeurs de boucaniers de la Voile sanglante partout dans le sud de [[Stranglethorn Vale]]",
    [596] = "ai pris des colliers d'os ensanglantés aux trolls Bloodscalp pour Kin'weelay, dont les rites affaibliraient les ennemis des Darkspear",
    [597] = "ai apporté au second Crazz une carte de la Voile sanglante, la preuve que leurs hommes campaient près de [[Booty Bay]] en attendant un signal pour attaquer",
    [598] = "ai chassé les Skullsplitter pour leurs colliers d'os brisés, poursuivant pour Kin'weelay la vieille guerre des Darkspear contre la tribu",
    [599] = "ai averti l'amiral Seahorn de l'attaque que les boucaniers de la Voile sanglante préparaient contre [[Booty Bay]]",
    [600] = "ai saisi [[des:Singing Blue Crystal]] aux mineurs de la KapitalRisk près de la mine de Veine-de-cristal pour [[name:Crank Fizzlebub]]",
    [601] = "ai pris des bracelets aux élémentaires d'eau de l'île hantée, pour qu'un mage de Dalaran étudie la malédiction de la Pierre des marées",
    [602] = "ai porté les bracelets d'élémentaire d'eau à l'archimage Ansirem Runeweaver à Dalaran, qui connaissait les légendes de la Pierre des marées",
    [604] = "ai attaqué le poste de commandement de la Voile sanglante sur le Rivage sauvage pour leurs cartes et leurs ordres, afin de connaître leur plan contre [[Booty Bay]]",
    [605] = "ai récolté des éclats de cristal chantant sur les peaux des basilics pour [[name:Crank Fizzlebub]], que la KapitalRisk tenait éloigné des cristaux",
    [606] = "ai effrayé Philippe le Chancelant avec des abats de gorille pour qu'il paie la dette de jeu qu'il devait au Loup de mer MacKinley",
    [607] = "ai récupéré le paiement en retard de Philippe le Chancelant pour le Loup de mer MacKinley, avec sa promesse qu'il avait bien eu l'intention de payer",
    [608] = "ai tué le capitaine Stillwater, le capitaine Keelhaul et l'amiral Firallon pour briser l'attaque de la Voile sanglante contre [[Booty Bay]]",
    [609] = "ai récupéré auprès de trois joueurs maudits dans les ruines de la jungle un pied, une longue-vue et un anneau qu'ils devaient au Loup de mer MacKinley",
    [610] = "ai repris la dague de Catelyn à Duncan le Beau garçon, de la Voile sanglante, la lame qu'il fallait pour briser l'autel de la Pierre",
    [611] = "ai brisé l'autel des Marées avec la lame de Catelyn et tué Gazban, pour rapporter la Pierre des marées au baron Revilgaz",
    [613] = "ai fouillé les ogres Mosh'Ogg à la recherche de la clé de Maury, pour ouvrir le pied verrouillé qui renfermait ce qu'il devait au Loup de mer MacKinley",
    [614] = "ai repris le coffre du capitaine Smotts à Gorlash, l'un des géants des mers qui avaient fracassé son navire et tué son équipage",
    [617] = "ai cueilli des roseaux akiris aux nagas le long de la plage pour le corsaire Bloads, dont l'ami Groy les payait bien",
    [618] = "ai attiré le géant Negolash avec des ailes de busard et du vin, puis l'ai tué pour reprendre le coutelas du capitaine Smotts",
    [621] = "ai pris des échantillons de la mixture de Zanzil à ses fidèles pour [[name:Crank Fizzlebub]], qui comptait bien lui trouver un usage",
    [622] = "ai rapporté la cocotte réparée au caporal Kaleb, pour que le camp rebelle puisse enfin préparer son dîner",
    [623] = "ai expédié un fagot de roseaux akiris au corsaire Groy à [[Theramore Isle]], pour un client qui en voulait d'autres sur-le-champ",
    [624] = "ai suivi la devinette de Cortello jusqu'à un indice caché sous un pont de [[Swamp of Sorrows]]",
    [625] = "ai suivi l'indice suivant de la devinette jusqu'à une grotte au sud-ouest de [[Dustwallow Marsh]]",
    [626] = "ai résolu la dernière devinette de Cortello sous les grandes chutes de [[Hinterlands]], où attendait un coffre au trésor",
    [627] = "ai extrait du minerai de pierre de sang dans la gorge des Moustaches-Sèches pour [[name:Krazek]], le service qu'il demandait pendant qu'il réparait la cocotte",
    [628] = "ai attiré un vieux crocilisque d'eau salée pour sa peau précieuse, la couche extérieure des bottes Excelsior de [[name:Drizzlik]]",
    [629] = "ai bravé les murlocs du Récif infâme pour un éclat de la tablette de Gri'lek, que les Darkspear voulaient garder en sanctuaire à [[Orgrimmar]]",
    [630] = "ai tué le roi Mukla, le grand Crins-du-ciel, pour libérer la princesse Poobah de la chaîne qui la retenait sur son île",
    [631] = "ai cherché le vieux Rustlocke, l'éclaireur que Longbraid avait envoyé quelques jours plus tôt voir si le pont est de [[Thandol Span]] pouvait tenir",
    [632] = "ai apporté à Rhag Garmason la triste nouvelle de la mort du vieux Rustlocke et le parchemin trouvé dans son poing serré",
    [633] = "ai détruit la réserve d'explosifs de Kam Deepfury de l'autre côté de [[Thandol Span]] avant qu'elle ne coupe le dernier pont vers le nord",
    [634] = "ai porté la supplique des survivants de [[Dun Modr]] au capitaine Nials à [[Refuge Pointe]], pour des soldats qui aideraient à reprendre [[Thandol Span]]",
    [635] = "ai suivi la vision d'un éclat palpitant jusqu'à un cristal dans les montagnes du nord de [[Arathi Highlands]], où quelqu'un semblait appeler à l'aide",
    [636] = "ai cherché les éclats de Myzrael, qu'un vieux livre décrivait comme une fenêtre sur la prison d'une princesse élémentaire sous [[Arathi Highlands]]",
    [639] = "ai pris le glyphe de Strom au Syndicat pour Zengu, le premier des sceaux du tombeau de Trollbane et de son épée tueuse de trolls",
    [640] = "ai arraché les cinq fragments du glyphe de Thoradin aux défenseurs de [[Stromgarde Keep]] pour que Tor'gan les réunisse",
    [641] = "ai rapporté le glyphe de Thoradin restauré à Zengu, à mi-chemin de l'ouverture du tombeau de Trollbane",
    [642] = "ai rassemblé des poussières de Myzrael sur les kobolds Moustaches-Sèches pour charger un éclat pour Myzrael, une princesse de la terre emprisonnée par des géants",
    [643] = "ai pris le glyphe d'Arathor au lieutenant Valorcall, chef de la cavalerie de [[Stromgarde Keep]], pour Zengu",
    [644] = "ai tué le prince Galen Trollbane dans sa chapelle de [[Stromgarde Keep]] pour le dernier glyphe qui scellait le tombeau de son père",
    [645] = "ai brisé les protections du tombeau de Trollbane à [[Stromgarde Keep]] pour prendre Trol'kalar, l'épée tueuse de trolls que voulaient les Darkspear",
    [646] = "ai livré Trol'kalar à Zengu à [[Hammerfall]], la plus grande arme de Strom et d'Arathor mise au service du combat des Darkspear à [[Zul'Gurub]]",
    [647] = "ai porté en hâte une cuvée de tord-boyaux de MacKreel au maître brasseur Bilger à [[Southshore]] pour rembourser la dette de Foggy MacKreel avant l'échéance",
    [648] = "ai escorté OOX-17/TN, bien cabossé, jusqu'à [[Steamwheedle Port]] pour qu'[[name:Oglethorpe Obnoticus]] remette son robot de repérage en l'air",
    [651] = "ai gagné les clés des pierres de lien gardées [[at:Arathi Highlands]] pour desserrer les liens qui retenaient Myzrael sous terre",
    [652] = "ai tué le guetteur de pierre Fozruk pour le bâtonnet de l'Ordre et ouvert la clé de voûte qui tenait Myzrael enchaînée",
    [654] = "ai couru contre la montre, les deux heures que durait une source d'énergie, pour analyser avec une trousse de terrain les tissus des basilics, des hyènes et des scorpides de [[Tanaris]]",
    [656] = "ai invoqué Myzrael et l'ai vaincue avant qu'elle ne devienne assez forte pour défier les géants, puis l'ai liée de nouveau dans ses propres chaînes",
    [662] = "ai plongé jusqu'aux épaves de la Folie de la Vierge et de l'Esprit des Pins argentés pour leurs cartes et leurs journaux de bord, pour qu'aucun regard indiscret ne les trouve",
    [664] = "ai massacré les nagas Daguéchine qui avaient tué les survivants de la Folie de la Vierge, une maigre consolation pour le capitaine Steelgut",
    [665] = "ai protégé le professeur Phizzlethorpe dans la grotte maudite pendant qu'il chargeait les lunettes censées trouver le trésor elfique perdu",
    [666] = "ai fouillé le fond de la mer avec les lunettes de chasse aux gemmes à la recherche des gemmes elfiques du trésor perdu, changées en pierre",
    [667] = "ai tenu le canon pour défendre Shakes O'Breen contre l'attaque des Daguéchine, son équipage ne pouvant rejoindre [[Booty Bay]] sans lui",
    [668] = "ai remis les gemmes elfiques retrouvées au capitaine O'Breen, le trésor pour lequel ses navires étaient venus à [[Faldir's Cove]]",
    [669] = "ai porté un échantillon de gemme elfique à l'amiral Seahorn à [[Booty Bay]], la preuve que l'équipage échoué d'O'Breen avait trouvé le trésor",
    [670] = "ai rapporté la lettre secrète de l'amiral Seahorn à Shakes O'Breen, au mouillage au large de la côte de [[Arathi Highlands]]",
    [671] = "ai rassemblé des amulettes de pierre de sang pour Tor'gan, qui avait trouvé des traces d'invocation démoniaque à [[Northfold Manor]]",
    [672] = "ai rassemblé des yeux de raptor pour que Tor'gan fabrique une amulette capable de dissiper le désespoir de Gor'mul, brisé depuis la mort de Doomhammer",
    [673] = "ai tué le démoniste Marez Cowl à [[Stromgarde Keep]] pour l'orbe de pierre de sang qui y invoquait des démons, pour que Tor'gan le détruise",
    [674] = "ai donné à Gor'mul l'amulette de griffe de raptor de Tor'gan, dans l'espoir que la force des raptors réveille le guerrier en lui",
    [677] = "ai tué des trolls Witherbark dans leurs camps pour Drum Fel, pour montrer aux trolls comme aux ogres que la Horde aussi avait un foyer [[at:Arathi Highlands]]",
    [678] = "ai combattu les brutes et les magus Rochepoing dans leur repaire près du pont nain, l'épreuve plus rude que fixait Drum Fel",
    [679] = "ai abattu les seigneurs Rochepoing et leurs chamans dans les ruines de [[Stromgarde Keep]], les chefs des attaques contre [[Hammerfall]]",
    [680] = "ai tué Or'Kalar pour Korin Fel, qui cachait le piège de l'ogre à son mari pour qu'il ne s'y précipite pas bêtement",
    [682] = "ai repris au Syndicat les insignes des miliciens de [[Stromgarde Keep]] tombés, dont il payait des primes, pour que leurs familles apprennent leur sort",
    [684] = "ai traqué Marez Cowl, un démoniste du Syndicat qui trafiquait des démons à [[Stromgarde Keep]], pour la prime de [[Refuge Pointe]]",
    [685] = "ai abattu le seigneur Falconcrest, chef du Syndicat [[at:Arathi Highlands]], et Otto, le garde du corps qui avait tué des dizaines de défenseurs",
    [687] = "ai fouillé [[Badlands]] à la recherche de Theldurin l'Égaré, un déserteur fou du Marteau du crépuscule qui avait volé le parchemin de Myzrael",
    [691] = "ai rassemblé des défenses, des bourses-médecine et un couteau de chasseur d'ombre des Witherbark, des composants pour Kryten, l'apprenti de l'archimage Malin",
    [693] = "ai arraché la baguette d'invocation de Trelane à Kor'gresh, dans la salle de Rochepoing, avant que l'ogre ne maîtrise son pouvoir glacé",
    [694] = "ai pris une agate azur aux chamans Rochepoing pour que Kryten l'enchante en une clé des défenses de la tour d'Arathor",
    [696] = "ai pillé la tour d'Arathor, aux mains des ogres, pour le phylactère, l'orbe et l'agate de braise de Trelane",
    [698] = "ai chassé [[des:Sawtooth Crocolisk]] adultes pour leurs flancs, afin de nourrir les soldats de Tok'Kar à l'avant-poste de la plage, qui n'avaient pas le temps de chasser",
    [699] = "ai fourni à Tok'Kar des griffes de mordeur dents-de-scie pour fabriquer des armes à l'avant-poste qui surveillait la côte contre les murlocs",
    [701] = "ai arraché des cœurs de raptor aux traqueurs des hautes-terres pour que Tor'gan insuffle à Gor'mul la ruse du raptor",
    [702] = "ai apporté à Gor'mul l'orbe que Tor'gan avait empli de l'esprit du raptor, un nouvel essai pour réveiller le guerrier endormi en lui",
    [704] = "ai repris les urnes de pierre trouvées par les fouilleurs du défunt Agmond à [[Uldaman]], qui avaient réveillé les troggs selon les craintes du prospecteur Ironband",
    [709] = "ai trouvé la tablette de Ryun'eh dans un coffre ancien au fond de [[Uldaman]] pour Theldurin l'Égaré, qui craignait une catastrophe qu'il n'osait nommer",
    [721] = "ai cherché Hammertoe Grez à [[Uldaman]], retenu par les Ombreforge pour ce qu'il savait des fouilles des Titans",
    [722] = "ai repris l'amulette de Hammertoe Grez à Magregan Ombre-profonde, avant qu'elle ne mène les Sombrefer à des parchemins pour des golems plus puissants",
    [729] = "suis $gparti:partie; vers le sud voir si le prospecteur Remtravel allait bien, son chantier envahi par des golems qu'il semblait ne jamais remarquer",
    [730] = "ai cherché [[at:Darkshore]] des traces de l'équipe de fouilles naine, dont on était sans nouvelles depuis des semaines",
    [731] = "ai protégé le distrait prospecteur Remtravel parmi les créatures de son chantier pendant qu'il cherchait son fossile",
    [736] = "ai rassemblé trois reliques de pouvoir pour le gardien Bel'dugur, le prix du condensé de Yagyin et de l'ouverture d'un chapitre de l'ordre",
    [741] = "ai porté le mystérieux fossile de Remtravel à l'archéologue en chef Greywhisker, à [[Darnassus]], comme promis à la Ligue",
    [747] = "ai chassé les trotteurs des plaines pour la viande et les plumes qui manquaient à [[Camp Narache]], pour me montrer digne aux yeux du chef Hawkwind",
    [750] = "ai dépecé les pumas des montagnes dans les collines pour le [[Camp Narache]], dont les enfants avaient besoin de vêtements et les tentes de réparations",
    [752] = "suis $gallé:allée; voir la mère du chef Hawkwind, partie depuis longtemps chercher de l'eau au puits",
    [753] = "ai rapporté une cruche d'eau du puits pour la Grand-mère, dont les vieilles jambes manquaient de vigueur",
    [757] = "ai réussi le rite de Force, le premier des rites de la Terre-Mère, contre les Dos-hirsute qui pillaient le [[Camp Narache]]",
    [780] = "ai tué les sangliers de guerre que les Dos-hirsute avaient dressés à la méchanceté, pour des groins et des flancs à mijoter pour les jeunes du camp",
    [781] = "ai apporté au chef Hawkwind les plans du chef de guerre Dos-hirsute pour assiéger le [[Camp Narache]], à temps pour appeler [[Bloodhoof Village]] à l'aide",
    [784] = "ai chassé de [[Tiragarde Keep]] le lieutenant Benedict et ses hommes de Kul Tiras, qui l'avaient repris au mépris du pacte du chef de guerre",
    [786] = "ai détruit les plans d'attaque des centaures Kolkar, détenus par trois chefs dans [[Kolkar Crag]], avant qu'ils ne frappent [[Durotar]]",
    [791] = "ai apporté du canevas à Furl Scornbrow, trop vieux pour la bataille, qui faisait désormais des sacs pour les jeunes guerriers depuis sa tour de guet",
    [806] = "ai vaincu [[name:Fizzle Darkstorm]], démoniste gobelin de la [[faction:Burning Blade]] à [[Thunder Ridge]], pour refuser au culte une prise [[at:Durotar]]",
    [808] = "ai pris le crâne de Minshina dans le cercle de pouvoir de Zalazane, libérant l'esprit prisonnier du frère de maître Gadrin",
    [812] = "ai couru jusqu'à Kor'ghan, à [[Orgrimmar]], chercher l'antidote qui a sauvé Rhinag, piqué par un queue-venin et à une heure de la mort",
    [813] = "ai rassemblé des glandes à venin de queue-venin pour que Kor'ghan prépare un antidote pour Rhinag, piqué",
    [815] = "ai volé des œufs de fouette-queue sur [[Echo Isles]] pour le prochain petit déjeuner du cuisinier Torka",
    [816] = "ai fouillé les crocilisques de la Furie-du-Sud en quête d'un signe du sort de Kron, pour que sa mère Misha Tor'kren puisse enfin faire son deuil",
    [817] = "ai chassé [[des:Durotar Tiger]] sur les îles du sud pour leur fourrure, afin que Vel'rin Fang puisse garder les gens au chaud",
    [818] = "ai rassemblé des yeux de makrura et du mucus de clampant pour maître Vornal, un alchimiste à demi aveugle qui n'avait jamais trouvé d'élève digne de lui",
    [819] = "ai porté un tonneau vide à quelqu'un qui connaissait celui qui l'avait fait, Chen Stormstout, autrefois compagnon de route de Rexxar",
    [821] = "ai rassemblé des canines, des rognons et une corne de lézard-tonnerre pour que le maître brasseur Drohn brasse une fois de plus la stormstout de Chen",
    [822] = "ai rassemblé des glandes d'éclair, une glande salivaire et un foie de kodo pour la bière trogg du maître brasseur Drohn, une autre recette de Chen",
    [824] = "ai porté un globe d'eau souillée à [[name:Je'neu Sancrea]] du Cercle terrestre, qui craignait qu'il nourrisse une corruption des éléments",
    [825] = "ai nagé parmi les épaves de la flotte de Proudmoore à la recherche d'outils gnomes, pour que la Horde apprenne la mécanique de l'Alliance",
    [826] = "ai vaincu Zalazane et ses trolls maléficiés sur [[Echo Isles]], pour que la tribu Darkspear puisse de nouveau dormir en paix",
    [827] = "ai pris des colliers brûlants à la [[faction:Burning Blade]] à [[Skull Rock]], pour que Margoz apprenne comment les sectateurs puisaient dans le pouvoir démoniaque",
    [829] = "ai montré un collier brûlant à Neeru Fireblade, un démoniste qui prétend chasser les démons, son origine dépassant le savoir de Margoz",
    [830] = "ai apporté un exemplaire trouvé des ordres de l'amiral Proudmoore à Gar'Thok, commandant de [[Razor Hill]]",
    [831] = "ai porté en hâte les ordres de l'amiral Proudmoore à Nazgrel, dans la salle de Thrall, preuve que les plans des humains avaient survécu à l'amiral",
    [832] = "ai remis à Neeru Fireblade l'Œil de l'ombre ardente, un pendentif de sectateur dont la voix avait prononcé son nom",
    [834] = "ai repris les provisions que les harpies Terrevent avaient arrachées à la caravane de Rezlak et emportées dans [[Razorwind Canyon]]",
    [835] = "ai débarrassé [[Drygulch Ravine]] de ses harpies pour que les caravanes de ravitaillement de Rezlak puissent passer sans danger",
    [836] = "ai escorté le robot OOX-09/HL jusqu'au rivage au-delà de [[Overlook Cliffs]], d'où il pourrait commencer son long décollage vers chez lui",
    [837] = "ai chassé les hurans Tranchecrin de leurs camps à l'ouest de [[Razor Hill]], pour protéger les frontières de la nouvelle patrie des orcs",
    [843] = "ai chassé les nains de [[Bael Modan]], dont les explosions ravageaient les terres tribales de Gann Stonespire, et pris le journal de Khazgorm",
    [844] = "ai abattu les trotteurs des plaines qui pillaient les vivres de [[Crossroads]], les premières proies, et les plus faciles, de Sergra Darkthorn",
    [845] = "ai chassé les zhévras pour leurs sabots, un gibier un peu plus coriace que les trotteurs, la leçon suivante de Sergra Darkthorn",
    [846] = "ai récupéré de la nitroglycérine, de la pulpe de bois et du nitrate de sodium pour que Gann Stonespire fasse goûter aux nains leur propre médecine",
    [848] = "ai cueilli des spores fongiques près des oasis pour l'apothicaire Helbrim, dont les camarades réprouvés prisaient les étranges propriétés",
    [849] = "ai fait sauter la machine volante de [[Bael Modan]], une arme de guerre naine et une insulte pour la tribu perdue de Gann Stonespire",
    [850] = "ai traqué Barak Plaie-des-kodos, l'un des nouveaux chefs qui ralliaient les centaures kolkars, pour Regthar Deathgate",
    [851] = "ai agité les centaures de [[Stagnant Oasis]] jusqu'à ce que vienne Verog le Derviche, le chef kolkar suivant après Barak Plaie-des-kodos",
    [852] = "ai tué Hezrul Bloodmark, chef des Kolkars, pour diviser les centaures et émousser leur menace contre la Horde",
    [853] = "ai porté en hâte les spores fondues de l'apothicaire Helbrim à l'apothicaire Zamah à [[Thunder Bluff]] avant que l'émulsion ne perde sa force",
    [855] = "ai pris des bracelets aux guerriers kolkars pour la prime de Regthar Deathgate, pour éclaircir les troupes centaures",
    [857] = "ai volé la Larme des lunes dans le fort du général Twinbraid pour Feegly l'Exilé, qui délirait en croyant que son pouvoir lui revenait",
    [858] = "suis $gallé:allée; chercher la clé de contact pour Wizzlecrank, un gobelin coincé dans un déchiqueteur de la KapitalRisk qu'il comptait voler",
    [862] = "ai attrapé des rats des fouilles à [[Bael Modan]] pour le ragoût de Grub, car pour lui aucun aventurier n'était aguerri sans avoir tué quelques rats",
    [863] = "ai protégé Wizzlecrank pendant qu'il menait un déchiqueteur volé à la KapitalRisk hors de [[Sludge Fen]], vers Sputtervalve à [[Ratchet]]",
    [864] = "ai rapporté la trousse d'analyse de terrain scellée à l'apothicaire Zinge, ses données intactes pour son étude des recherches de Keever",
    [865] = "ai arraché des cornes aux faucheurs Écaille-solaire pour Mebok Mizzyrix, qui comptait les moudre en boissons pour l'esprit et faire fortune",
    [866] = "ai prélevé des échantillons de racines sur les herbes de [[Barrens]] pour Mebok Mizzyrix, qui espérait que l'eau des oasis leur avait donné des vertus précieuses",
    [867] = "ai coupé des serres aux harpies Ensorçaile qui avaient ravagé les caravanes de la Horde, un premier coup pour Darsok Swiftdagger",
    [868] = "ai déterré des œufs de silithide de leurs monticules dans [[Field of Giants]] pour que Korran étudie ces étranges insectes pour [[Orgrimmar]]",
    [869] = "ai chassé les raptors qui avaient, on ne sait comment, volé l'argent des gardes de [[Crossroads]], pour qu'ils ne volent plus jamais rien",
    [870] = "ai fouillé [[Forgotten Pools]] à la recherche du pouvoir qui suintait sous [[Barrens]], et trouvé une fissure pour Tonga Runetotem",
    [871] = "ai décimé les hurans Tranchecrin qui attaquaient les lignes de ravitaillement venues de [[Durotar]], pour Thork à [[Crossroads]]",
    [872] = "ai tué Kreenig Grondegroin, le Tranchecrin qui menait les raids contre les caravanes de [[Durotar]], et rapporté sa défense à Thork",
    [873] = "ai nagé au large pour tuer Isha Awak, le Fléau des profondeurs de la côte, la proie de valeur que Mahren Skyseer m'avait désignée",
    [875] = "ai abattu une à une les tueuses Ensorçaile, les lieutenants harpies de [[Dry Hills]], un coup décisif contre leur matriarcat",
    [876] = "ai tué Serena Bloodfeather, dont les harpies pillaient les caravanes de la Horde pour venger la sœur que Rexxar avait tuée",
    [877] = "ai planté des graines mortes dans une fissure de [[Stagnant Oasis]] pour Tonga Runetotem, et les ai regardées reprendre vie",
    [878] = "ai abattu les chefs spirituels des hurans Dos-hirsute pour que les Tranchecrin puissent les vaincre, pour Mangletooth, en cage",
    [879] = "ai tué Nak, Kuz et Lok Plaie-des-orcs, les Tranchecrin qui pillaient la Horde et avaient laissé Mangletooth pourrir dans une cage",
    [880] = "ai ramassé des carapaces de Gueule d'acier pour que Tonga Runetotem sache comment les fissures changeaient les bêtes qui s'y abreuvaient",
    [881] = "ai fait sortir de son repaire Echeyakee, le roi de brume blanche des félins de la savane, avec un cor, et rapporté sa peau à Sergra Darkthorn",
    [882] = "ai appâté Ishamuhale, le plus féroce des raptors Écaille-solaire, avec une carcasse de zhévra, et rapporté son croc à Jorn Skyseer",
    [883] = "ai apporté le sabot de Lakota'mani, le grand kodo que les taurens appellent Secoue-terre, à Jorn à [[Camp Taurajo]]",
    [884] = "ai présenté l'épine caudale crépitante d'Owatanka, le lézard-tonnerre que les taurens appellent Éclair-bleu, à Jorn à [[Camp Taurajo]]",
    [885] = "ai chassé Washte Pawne, le rare faucon-tonnerre appelé Mord-l'esprit, et rapporté sa plume cuisante à Jorn Skyseer",
    [887] = "ai nettoyé le camp des flibustiers des Mers du sud au sud de [[Ratchet]], des pirates qui pillaient sans cesse les navires de Gazlowe",
    [888] = "ai fouillé le camp pirate à la recherche de la cargaison de bottes de Gazlowe et de la lentille qui manquait encore à son nouvel observatoire",
    [890] = "ai porté le livre de comptes de Gazlowe au maître des quais Dizzywig, pour savoir si sa cargaison disparue était jamais arrivée",
    [891] = "ai assiégé [[Northwatch Hold]], dont les canons coulaient sans cesse les navires du capitaine Brightsun, et tué le capitaine Fairmount",
    [893] = "ai pris une dague, une baguette et un bouclier aux Tranchecrin pour que Tatternack Steelforge étudie leurs armes plus solides",
    [894] = "ai atteint la console de contrôle d'un site de recherche de la KapitalRisk, pour trouver comment libérer le mystérieux samophlange",
    [895] = "ai traqué le baron de Longrivage de Gilnéas, capitaine de l'Insouciant, recherché par Gazlowe pour piraterie",
    [896] = "ai subtilisé à la KapitalRisk, à [[Boulder Lode Mine]], une émeraude grosse comme un poing pour le maître des quais Dizzywig, qui me promettait la moitié de la vente",
    [897] = "ai montré à Jorn Skyseer la tête du Moissonneur, une chose pareille à un insecte qui n'avait rien à faire dans [[Barrens]]",
    [898] = "ai escorté Gilthares Firebough, seul survivant d'un navire que Theramore avait coulé, de [[Northwatch Hold]] jusqu'à [[Ratchet]]",
    [899] = "ai rassemblé des défenses de Dos-hirsute pour Mankrik, dont la soif de vengeance contre les hommes-cochons était loin d'être étanchée",
    [900] = "ai fermé trois vannes de la console de la KapitalRisk pour que l'appareil du samophlange puisse être éteint",
    [901] = "ai arraché la clé de la console au bricoleur Sniggles pour ouvrir l'appareil de la KapitalRisk et atteindre le samophlange à l'intérieur",
    [902] = "ai retiré le samophlange de sa console pour Sputtervalve à [[Ratchet]], qui l'enverrait au syndicat des bricoleurs",
    [903] = "ai traqué les rôdeurs des savanes dans les hautes herbes pour leurs griffes, des proies capables de faire du chasseur le gibier",
    [905] = "ai déposé des plumes de raptor Écaille-solaire sur les nids des Faucheurs pour montrer aux leurs que je n'avais pas peur, comme le demandait Sergra Darkthorn",
    [906] = "ai apporté le crâne de Lok à Thork à [[Crossroads]], la preuve que le chef des raids contre ses lignes de ravitaillement était mort",
    [907] = "ai affronté les grands lézards-tonnerre du sud de [[Barrens]] et rapporté leur sang à Jorn Skyseer pour preuve",
    [913] = "ai tué un faucon-tonnerre pour ses ailes, la chasse qui menait l'enseignement de Jorn Skyseer près de sa fin",
    [914] = "ai tué les quatre chefs des druides du Croc pour leurs gemmes du rêve, afin de sauver [[The Barrens]] d'un avenir maudit",
    [918] = "ai ramassé des graines de sylvain autour de [[Lake Al'Ameth]] pour Denalan, qui espérait faire pousser des sylvains plus doux dans sa terre spéciale",
    [919] = "ai arraché les pousses de sylvain qui se répandaient autour de [[Lake Al'Ameth]] avant qu'elles ne deviennent assez grandes pour causer des ennuis",
    [922] = "ai porté une graine de sylvain à Rellian Greenspyre à [[Darnassus]], qui y a trouvé la souillure de sa plante mère",
    [923] = "ai abattu les sylvains corrompus du lac de la Source pour Rellian Greenspyre, leurs tumeurs moussues bonnes à brûler",
    [924] = "ai porté une pierre de pouvoir défectueuse au sommet de [[Dreadmist Peak]] avant qu'elle ne se consume, détruisant ainsi la Graine démoniaque de la [[faction:Burning Blade]]",
    [927] = "ai remis à Denalan le cœur encore battant de Mousse-noire le Fétide, enveloppé dans une mousse sombre et huileuse",
    [929] = "ai rempli une fiole au puits de lune près de [[Starbreeze Village]] pour Corithras Moonrage, qui commençait à raconter comment [[Teldrassil]] était né",
    [930] = "ai montré à Denalan un étrange fruit luminescent, une plante venue de loin qui réagissait bizarrement à la terre de [[Teldrassil]]",
    [931] = "ai apporté à Denalan une fronde chatoyante, une plante qu'il n'avait pas revue depuis des décennies, dans [[Swamp of Sorrows]]",
    [932] = "ai traqué le seigneur satyre Melenas, qui préparait quelque chose d'immonde à [[Fel Rock]], bien trop près de [[Dolanaar]]",
    [933] = "ai bravé les irascibles Pin-tordu pour remplir une fiole au puits de lune près des bassins d'Arlithrien pour Corithras Moonrage",
    [934] = "ai puisé de l'eau au puits de lune sous l'Arbre de l'oracle, et entendu pourquoi les dragons avaient refusé de bénir [[Teldrassil]]",
    [935] = "ai porté les eaux des puits de lune à l'archidruide Fandral Staghelm, sur les épaules duquel retombaient les malheurs de [[Teldrassil]]",
    [937] = "ai chassé les harpies de leurs nids autour de l'Arbre de l'oracle, après qu'elles avaient tué son messager pour [[Darnassus]]",
    [938] = "ai ramené Brume, une sabre-de-nuit grièvement blessée, à la sentinelle Arynia Cloudsbreak, qui croyait sa fidèle compagne morte",
    [940] = "ai porté le rapport de l'Arbre de l'oracle à Fandral Staghelm, son dernier messager ayant été tué par les harpies",
    [941] = "ai planté le cœur corrompu de Mousse-noire dans la terre nourricière de Denalan, qui l'a purifié",
    [942] = "ai porté le fossile par-delà la mer jusqu'à l'archéologue Flagongut, à [[Menethil Harbor]], qui croyait que ces fossiles recelaient un pouvoir caché",
    [943] = "ai arraché la pierre de Relu à un raptor qui l'avait avalée et récupéré le fossile de Whelgar, pour que Flagongut tente de les éveiller",
    [944] = "ai reconnu [[The Master's Glaive]], où est tombé jadis un ancien seigneur de la terre, et parlé de ses sectateurs à Onu par une coupe de divination",
    [945] = "ai aidé Therylune à échapper aux sectateurs de [[The Master's Glaive]], et annoncé à sa sœur Therysil qu'elle était saine et sauve",
    [947] = "ai cueilli des champignons rares derrière [[Cliffspring Falls]] pour la potion de Barithras Moonshade, et reconnu la grotte que craignaient les Anciens",
    [949] = "ai fouillé le camp du Marteau du crépuscule à [[The Master's Glaive]] en quête d'un indice sur ce que le culte y projetait",
    [950] = "ai arraché une page de gribouillages démentiels au Tome du crépuscule qui rendait fou, dans l'espoir qu'elle révèle à Onu les desseins du culte",
    [951] = "ai fouillé les ruines de [[Ruins of Mathystra]] à la recherche de reliques elfiques, pour savoir comment le culte comptait user de la magie elfique pour ramener ses maîtres",
    [953] = "ai déchiffré les tablettes de [[Ameth'Aran]] parmi ses esprits sans repos, pour que la sentinelle Tysha Moonblade puisse rapporter sa chute",
    [954] = "ai examiné l'étrange aura bleue d'un sanctuaire de [[Bashal'Aran]], dont ses satyres et ses farfadets n'osaient approcher",
    [955] = "ai pris des boucles d'oreille aux grells de [[Bashal'Aran]], où l'esprit Asterion espérait trouver une trace du sceau qui le liait",
    [956] = "ai arraché l'ancien sceau de pierre de lune, lien de la longue captivité d'Asterion, aux satyres qui menaient les grells",
    [957] = "ai détruit l'ancien sceau de pierre de lune dans la flamme bleue de [[Ameth'Aran]], libérant Asterion après des âges",
    [958] = "ai arraché des reliques des Bien-nés aux esprits de [[Ameth'Aran]], pour que Thundris Windweaver puisse détruire le mal endormi qu'elles recelaient",
    [959] = "ai poursuivi Magglish le Fou jusque dans [[Wailing Caverns]] pour le porto vieux de 99 ans volé, avant que le grutier Bigglefuzz ne perde sa place",
    [962] = "ai cueilli de la fleur de serpent dans les recoins les plus sombres de [[Wailing Caverns]] pour l'apothicaire Zamah de la Société royale des apothicaires",
    [963] = "ai libéré l'esprit hanté d'Anaya Dawnrunner pour Cerellean Whiteclaw, qui l'aimait et n'avait pas le cœur de le faire",
    [964] = "ai rassemblé des fragments de squelette à Andorhal pour l'apothicaire Dithers, le premier pas vers une clé de la porte barrée de [[Scholomance]]",
    [965] = "suis $gparti:partie; à la recherche de Balthule Shadowstrike, en retard pour sa garde à [[Tower of Althalaxx]], pour une Elissa Starbreeze inquiète",
    [966] = "ai pris des parchemins déchirés aux démonistes de [[Tower of Althalaxx]], des papiers qui les désignaient comme le culte du Sombre Brin",
    [967] = "ai porté en hâte l'avertissement de Balthule sur le culte du Sombre Brin à son maître, Delgren le Purificateur, à [[Maestra's Post]]",
    [968] = "ai rapporté un exemplaire abîmé des Puissances d'en-bas, un livre de culte obscur, à la boutique de Gerrig Bonegrip à [[Ironforge]]",
    [970] = "ai saisi la gemme d'âme luminescente à Ordil'Aran pour Delgren, qui croyait qu'elle détenait le secret du pouvoir du Sombre Brin",
    [971] = "ai récupéré le manuscrit de Lorgalis à [[Blackfathom Deeps]] pour Gerrig Bonegrip, qui collectionnait le savoir capable d'éveiller Ceux qui dorment",
    [973] = "ai tenu tête à [[name:Ilkrud Magthrull]], un puissant démoniste orc à [[Fire Scar Shrine]], et porté son tome à Delgren",
    [974] = "ai pris la température des points chauds de [[Fire Plume Ridge]] pour Krakle, pour savoir si le volcan chauffait les sources du cratère",
    [976] = "ai escorté [[name:Feero Ironhand]] à travers [[Ashenvale]] avec les vivres et les messages dont [[Auberdine]] avait besoin contre les sombres menaces de la forêt",
    [982] = "ai plongé jusqu'aux épaves de l'Aube argentée et du Voile de brume, coulés par les murlocs, pour les coffrets de leurs capitaines morts",
    [983] = "ai réparé la Bigobox 827 avec des pattes de clampant pour Wizbang, un inventeur dont les boîtes parlantes demandaient sans cesse des réparations",
    [984] = "ai reconnu un camp de furbolgs Noirbois à la recherche de signes de corruption, pour Terenthis, qui avait juré qu'aucun elfe de la nuit ne serait plus blessé",
    [985] = "ai combattu les furbolgs Noirbois dans leur camp au sud de [[Auberdine]], la plus grande menace pour les gens de [[Auberdine]]",
    [986] = "ai dépecé [[des:Moonstalker Sire]] et [[des:Moonstalker Matriarch]] pour de belles peaux, afin que Terenthis puisse faire une cape pour rejoindre Volcor sans encombre",
    [991] = "ai fouillé le sanctuaire de [[Lake Falathim]] à la recherche de Teronis, l'ami de [[name:Raene Wolfrunner]], et l'ai trouvé mort parmi les murlocs",
    [992] = "ai puisé dans un bassin près de [[Sandsorrow Watch]] pour la Compagnie des eaux de [[Gadgetzan]], ses puits perdus aux mains des nomades, et y ai croisé un étrange insecte",
    [993] = "ai retrouvé Volcor, le maître blessé de Grimclaw, dans une grotte de furbolgs et lui ai apporté une cape enchantée de traquelune",
    [994] = "me suis frayé un chemin hors de la grotte des furbolgs aux côtés de Volcor, jusqu'à la route où attendait Grimclaw",
    [995] = "me suis $gfaufilé:faufilée; hors de la grotte des furbolgs avec Volcor blessé, puis ai retrouvé Terenthis à [[Auberdine]]",
    [997] = "ai livré à Denalan un colis de terre rare longtemps attendu, pour ses expériences sur les plantes de [[Teldrassil]]",
    [1001] = "ai pêché des yeux de batteur en haute mer pour réparer la Bigobox 411, pendant que Wizbang hoquetait à travers la boîte",
    [1002] = "ai nourri la Bigobox 323 de crocs de traquelune pour un Wizbang qui semblait plus ivre à chaque boîte",
    [1003] = "ai réparé la Bigobox 525 avec des scalps vieillis, et appris que les boîtes distillaient aussi de l'alcool pour un commerce que les elfes de la nuit voyaient d'un mauvais œil",
    [1007] = "ai fouillé le lieu d'une embuscade naga sur [[Zoram Strand]] à la recherche de l'ancienne statuette de [[name:Talen]], la raison qui l'avait poussé sur cette côte",
    [1008] = "ai chassé les nagas Irequeue de [[Zoram Strand]], où gît la cité engloutie de Zoram, pour [[name:Shindrell Swiftfire]]",
    [1009] = "ai pris l'anneau de Zoram à [[name:Ruuzel]], chef des nagas, la clé dont [[name:Talen]] avait besoin pour percer les secrets de sa statuette",
    [1010] = "ai fouillé [[Bathran's Haunt]] à la recherche de cheveux de Bathran, une plante dont [[name:Orendil Broadleaf]] avait besoin pour soigner un enfant malade du village",
    [1011] = "ai volé une bouteille de maladie au camp réprouvé près de Dor'Danil, pour que [[name:Kayneth Stillwind]] apprenne ce qu'ils comptaient répandre",
    [1012] = "ai détruit les fantômes rendus fous des druides de Dor'Danil, assassinés par les Réprouvés, pour que leurs esprits trouvent enfin la paix",
    [1016] = "ai lu dans les bracelets des élémentaires qui avait empli les bassins de corruption, pour la sentinelle Velene Starstrike",
    [1017] = "ai tué [[name:Sarilus Foulborne]], le mage mort-vivant qui souillait les eaux avec des élémentaires corrompus, pour la sentinelle Velene Starstrike",
    [1020] = "ai porté le remède d'Orendil à [[name:Pelturas Whitemoon]] à [[Astranaar]], le parent de l'enfant malade",
    [1021] = "ai fouillé [[Xavian]] à la recherche des dryades parties reprendre la branche de Cénarius, et y ai trouvé Anilia mourante",
    [1022] = "ai étudié le tome de Mel'Thandris à [[Howling Vale]], pour comprendre pourquoi des hommes-loups avaient envahi le sanctuaire",
    [1023] = "ai trouvé la gemme luminescente que Teronis était mort en cherchant, et rapporté son journal à [[name:Raene Wolfrunner]]",
    [1025] = "ai combattu les furbolgs Vile-sylve qui attaquaient les voyageurs sur la route de l'est, pour aider les sentinelles à protéger la terre",
    [1026] = "ai pris une clé de bois aux sylvaniens corrompus pour ouvrir un coffre caché qui renfermait la pièce suivante du bâtonnet de Dartol",
    [1027] = "ai retrouvé la dernière pièce du bâtonnet de Dartol, cachée par les druides de Dor'Danil avant qu'ils ne soient tués",
    [1028] = "ai trouvé un sanctuaire caché dans les montagnes et y ai enchanté à nouveau le bâtonnet de Dartol, l'œuvre que Teronis était mort en commençant",
    [1030] = "ai pris la forme d'un furbolg grâce au bâtonnet de Dartol pour parler à un furbolg non corrompu, qui accusait les elfes de la nuit de la corruption des siens",
    [1031] = "ai tué [[name:Geltharis]] et rendu la branche de Cénarius aux dryades, le dernier vœu d'Anilia",
    [1032] = "ai tué les satyres qui avaient pris Anilia, pour sa sœur Illiyana, en deuil",
    [1033] = "ai rapporté la Larme d'Elune de l'île de [[Iris Lake]] à [[name:Pelturas Whitemoon]], pour laver la corruption qui rendait Relara malade",
    [1034] = "ai ramassé de la poussière givrée dans [[Ruins of Stardust]] pour un cataplasme qui ferait tomber la fièvre de Relara",
    [1035] = "ai tué l'oracle du Fourré-d'ombre pour une pierre de lune tombée, le pouvoir qui rendrait ses forces à Relara, selon [[name:Pelturas Whitemoon]]",
    [1037] = "ai interrogé [[name:Thyn'tel Bladeweaver]] à [[Darnassus]] au sujet de Velinde Starsong, la prêtresse disparue de [[Ashenvale]]",
    [1038] = "ai fouillé le coffre de Velinde Starsong dans le dortoir des sentinelles à la recherche de son journal, qui rendait sa disparition plus troublante encore",
    [1039] = "ai suivi Velinde Starsong dans les registres du maître des quais de [[Ratchet]], où elle avait réservé un passage pour [[Booty Bay]]",
    [1040] = "ai suivi Velinde jusqu'à [[Booty Bay]] et au caravanier Ruzzgot, à qui elle avait demandé comment voyager par voie de terre",
    [1041] = "ai suivi la route des caravanes jusqu'à [[Darkshire]], où Velinde avait quitté la caravane de Ruzzgot",
    [1042] = "ai cherché la famille Carevin de [[Darkshire]], chasseurs des worgens jusqu'auxquels la piste de Velinde avait mené",
    [1043] = "ai fouillé la mine infestée de worgens au sud de [[Darkshire]], où les hommes-loups avaient été vus pour la première fois, à la recherche de traces de la Faux d'Elune",
    [1044] = "ai annoncé à [[name:Thyn'tel Bladeweaver]] le sort de Velinde Starsong, la fin d'une longue recherche de [[Ashenvale]] à [[Duskwood]]",
    [1045] = "ai tué [[name:Ran Bloodtooth]] et ses gardes pour [[name:Krolg]], un furbolg non corrompu, résolu à ce que son peuple fasse lui-même sa police",
    [1046] = "ai rapporté le crâne de [[name:Ran Bloodtooth]] et le bâtonnet de Dartol à [[name:Raene Wolfrunner]], achevant ce que Teronis était mort en commençant",
    [1052] = "ai porté la lettre de recommandation du frère Anton à Raleigh le Dévot à [[Southshore]], pour une place d'honneur à [[Scarlet Monastery]]",
    [1054] = "ai tué [[name:Dal Bloodclaw]], chef des furbolgs Crin-de-Chardon, dont le nombre croissant pouvait bientôt les pousser à attaquer [[Astranaar]]",
    [1057] = "ai chassé les harpies Rougefurie de [[Charred Vale]] pour le gardien Albagorm, pour que la terre brûlée puisse repousser",
    [1058] = "ai rassemblé sève, moustaches, yeux de coursier et une écaille de dragon-faë pour la magie sylvestre du sorcier-docteur Jin'Zil, préparée pour ses elfes en cage",
    [1059] = "ai porté la supplique du gardien Albagorm à [[name:Falfindel Waywarder]], un druide capable d'appeler les esprits de la forêt pour reprendre [[Charred Vale]]",
    [1060] = "ai porté la lettre de Darsok Swiftdagger au sorcier-docteur Jin'Zil dans [[Stonetalon Mountains]], la nouvelle que Serena Bloodfeather était morte",
    [1062] = "ai tué [[des:Venture Co. Logger]] à [[Windshear Crag]] pour [[name:Seereth Stonebreak]], pour empêcher les gobelins de brûler et d'abattre la forêt",
    [1068] = "ai détruit les déchiqueteurs XT:4 et XT:9, les machines de la vision de Seereth qui abattaient les arbres à une vitesse impossible",
    [1069] = "ai ramassé des œufs d'araignée des mousses profondes dans [[Stonetalon Mountains]] pour Mebok Mizzyrix, à vendre à [[Booty Bay]], folle des omelettes aux œufs d'araignée",
    [1070] = "suis $gparti:partie; à la recherche de Kaela Shadowspear, envoyée enquêter à [[Stonetalon Mountains]] et dont on était sans nouvelles depuis",
    [1071] = "ai tenu la KapitalRisk en respect à [[Windshear Crag]] pour que [[name:Gaxim Rustfizzle]] puisse préparer les inventions qui, espérait-il, sauveraient la forêt",
    [1073] = "ai prouvé à [[name:Lomac Gearstrip]] à [[Ironforge]] un certain talent d'alchimiste avec quelques potions, le prix de son Nitromirglycéronium",
    [1074] = "ai rapporté le Nitromirglycéronium instable à [[name:Gaxim Rustfizzle]], l'étincelle de ses chariots de dynamite",
    [1076] = "ai porté des débris d'un diable de poussière de [[Westfall]] à [[name:Collin Mauren]], pour un parchemin qui ferait sauter les explosifs de Gaxim à distance",
    [1077] = "ai apporté le parchemin de messager à [[name:Gaxim Rustfizzle]], la dernière pièce de l'explosif à distance qui devait couvrir un raid sur le site de la KapitalRisk",
    [1078] = "ai rassemblé des écailles de basilic cristallisées à [[Charred Vale]] pour [[name:Collin Mauren]], réduites en composant pour ses sorts",
    [1079] = "ai créé une diversion à la scierie de [[Windshear Crag]] et volé les plans d'ingénieur de la KapitalRisk pour [[name:Gaxim Rustfizzle]]",
    [1080] = "ai volé les lettres de la KapitalRisk dans [[Windshear Mine]] à la faveur des explosifs de Gaxim",
    [1082] = "ai annoncé à la sentinelle Thenysil que Kaela et Gaxim étaient en vie, et en bonne voie pour arrêter les gobelins de la KapitalRisk",
    [1083] = "ai décimé les esprits ardents lâchés sur [[Charred Vale]] quand la KapitalRisk y avait mis le feu, pour Kaela Shadowspear",
    [1084] = "ai retiré des éclats d'obus rouillés d'un sylvanien blessé pour que Gaxim sache si les armes des gobelins l'avaient corrompu",
    [1087] = "ai tué les fils et les filles de Cénarius pour [[name:Braelyn Firehand]], qui détestait la façon dont les druides étouffaient le flux de la magie",
    [1088] = "ai pris la tête d'Ordanus, l'un des fils aînés de Cénarius, au sommet du Bois-Rayne, pour [[name:Braelyn Firehand]]",
    [1089] = "ai ouvert le trésor des druides dans l'antre des Serres, au pic des Serres-Rocheuses, avec les secrets que Braelyn avait arrachés à l'un d'eux",
    [1090] = "ai gardé [[name:Piznik]] pendant qu'il extrayait un échantillon du mystérieux minerai or et vert de Gerenzo, pour savoir ce que le gnome préparait",
    [1091] = "ai apporté les lettres volées de la KapitalRisk à Kaela Shadowspear, avec le récit de la réussite du raid",
    [1092] = "ai porté le minerai non identifié à [[name:Ziz Fizziks]], dont le nouveau patron paierait bien pour connaître les plans de Gerenzo",
    [1093] = "ai pris le plan du Super-Découpeur 6000 à l'un de ses pilotes pour [[name:Ziz Fizziks]], que Gerenzo voulait voir mort sur-le-champ",
    [1094] = "ai porté une enveloppe scellée de documents volés à la KapitalRisk de la part de [[name:Ziz Fizziks]] à [[name:Sputtervalve]] à [[Ratchet]]",
    [1095] = "ai porté les nouveaux ordres de Sputtervalve à [[name:Ziz Fizziks]] : Gerenzo, que les princes marchands n'approuvaient pas, devait disparaître",
    [1096] = "ai tué Gerenzo Wrenchwhistle, le gnome à moitié mécanique qui dirigeait le site de la KapitalRisk, et rapporté son bras de métal à [[name:Ziz Fizziks]]",
    [1101] = "ai tué [[name:Charlga Razorflank]], la mégère du kraal, pour que la bravoure d'Heralath et du nain Lonebrow n'ait pas été vaine",
    [1102] = "ai vengé les taurens chassés de leurs terres sacrées de [[The Barrens]], en prenant le cœur de [[name:Charlga Razorflank]] pour le vieux Stonespire",
    [1104] = "ai rassemblé du venin de scorpide acide pour [[name:Fizzle Brassbolts]], la base d'un carburant pour faire chauffer davantage le chariot-fusée des gnomes",
    [1105] = "ai ramassé des carapaces de tortue pour [[name:Wizzle Brassbolts]], afin de construire des réservoirs assez solides pour le nouveau carburant féroce de son frère",
    [1106] = "ai porté la lettre de Fizzle à [[name:Martek the Exiled]] dans [[Badlands]], un grand forgeron qui saurait peut-être faire des pistons plus durs",
    [1107] = "ai coupé des nageoires aux murlocs Écaille-salée du Récif infâme pour un composite qui empêcherait le chariot-fusée de se déchirer",
    [1108] = "ai pris des flocons d'indurium aux troggs Gardepierre pour que [[name:Martek the Exiled]] les teste, un métal qui pourrait supporter la chaleur du moteur de Fizzle",
    [1109] = "ai ramassé le guano des chauves-souris du kraal pour les ambitieuses expériences du maître apothicaire Faranell",
    [1110] = "ai récupéré des pièces de chariots-fusées accidentés sur [[Shimmering Flats]] pour que [[name:Kravel Koalbeard]] les revende aux pilotes",
    [1111] = "suis $gallé:allée; chercher auprès du maître des quais Dizzywig, à [[Ratchet]], les pièces que les gnomes attendaient depuis longtemps, pour [[name:Kravel Koalbeard]]",
    [1114] = "ai livré les pièces que [[name:Fizzle Brassbolts]] attendait depuis longtemps, moins une petite pièce que Kravel avait gardée",
    [1116] = "ai rassemblé de la poussière de rêve sur les dragonnets du marais pour la tabatière de Krazek, son prix pour des nouvelles de Nazz",
    [1117] = "ai apporté à Kravel les rumeurs que [[name:Krazek]] avait déterrées sur Nazz Steamboil, un secret que le pilote gobelin paierait une fortune pour garder",
    [1118] = "ai porté le nouveau plan de Kravel à [[name:Crank Fizzlebub]] à [[Booty Bay]], qui aurait besoin de quelque chose pour embrouiller l'esprit des pilotes",
    [1119] = "ai rapporté une bière du sot, brassée par [[name:Crank Fizzlebub]] avec la mixture de Zanzil, pour le plan de Kravel contre les pilotes",
    [1120] = "ai abreuvé de bière du sot l'équipe de mécaniciens gnomes avant la course, comme l'exigeait le plan de Kravel",
    [1121] = "ai glissé de la bière du sot à l'équipe de mécaniciens gobelins avant la course, pour que le pari de Kravel rapporte",
    [1125] = "ai libéré les esprits torturés des druides et des sentinelles dans les ruines de [[Southwind Village]], là où avait commencé le travail de [[name:Layo Starstrike]]",
    [1126] = "ai escaladé la tour de [[Southwind Village]] pour déloger sa ruche de silithides, et y ai trouvé une boîte incrustée qui semblait contenir un livre",
    [1127] = "ai rapporté à [[name:Crank Fizzlebub]] davantage de mixture de Zanzil pour brasser la bière du sot, une boisson réclamée aux courses",
    [1134] = "ai tué des ailes-fières près de [[Mirkfallon Lake]] pour priver de leur venin les assassins orcs qui s'en serviraient contre l'Alliance",
    [1138] = "ai prélevé de la belle chair de crabe sur des clampants de récif pour Gubber Blump, qui aimait le crabe plus que tout",
    [1139] = "ai récupéré la tablette de Volonté avant que le clan Ombreforge ne la trouve, pour que la mort de Hammertoe ne soit pas vaine",
    [1140] = "ai libéré les âmes des Bien-nés dont les gemmes d'âme, à [[Night Run]] et à [[Satyrnaar]], nourrissaient encore le pouvoir d'Athrikus",
    [1141] = "ai pêché des mérous de [[Darkshore]] pour Gubber Blump, aucun bateau n'étant sorti depuis l'arrivée des murlocs",
    [1142] = "ai rapporté à Treshala Fallowbrook, à [[Darnassus]], son pendentif d'union, avec la nouvelle de la mort solitaire de son mari Heralath",
    [1143] = "ai tué Athrikus Narassin au sommet de [[Tower of Althalaxx]] au milieu de ses démonistes, pour repousser les forces démoniaques qui s'y trouvaient",
    [1144] = "ai escorté Willix l'Importateur hors de [[Razorfen Kraul]], où il était retenu prisonnier après une chasse aux tubercules qui avait mal tourné",
    [1145] = "ai porté la note scellée de Korran à [[Orgrimmar]], qui avertissait que les insectes de [[Field of Giants]] étaient plus dangereux qu'on ne le pensait",
    [1147] = "ai repoussé les silithides loin du site de fouilles pour la troupe à moitié morte de [[name:Moktar Krin]], qui ne pouvait les combattre seule",
    [1148] = "ai apporté des cœurs, des serres et des carapaces de silithides à [[name:Korran]] à [[Crossroads]], pour savoir ce qu'étaient ces créatures",
    [1153] = "ai arraché un échantillon de minerai aux kobolds Groin-de-gravier pour Tatternack Steelforge, qui espérait forger une arme pour le chef de guerre",
    [1164] = "ai tué Kenata Dabyrie et ses fils dans leur ferme de [[Arathi Highlands]] pour Genavie Callow, qui voulait leurs têtes pour l'avoir volée",
    [1175] = "ai chassé les basilics loin de la piste pour le maître de piste Zherin, après que l'un d'eux avait causé un grave accident avec le Tonnerre rouge",
    [1176] = "ai rassemblé des os creux de vautour pour [[name:Pozzik]], légers et solides, pour régler les bolides des gobelins",
    [1179] = "ai porté une caisse de casques anti-accidents à [[name:Wizzle Brassbolts]], dont les pilotes de chariot-fusée se faisaient sans cesse des commotions dans les accidents",
    [1182] = "ai volé les plans du régulateur de carburant dans la maison verrouillée de Cozzle au lac Nazferiti, pour le pilote gobelin [[name:Pozzik]]",
    [1183] = "ai livré les plans du régulateur de carburant à [[name:Pozzik]], qui pouvait désormais en construire un meilleur pour son bolide, de A à Z",
    [1187] = "ai récupéré le propulseur à hydroglycérine de [[name:Razzeric]] dans un zeppelin écrasé à [[Dustwallow Marsh]], la puissance en plus qu'il voulait pour son bolide",
    [1188] = "ai porté le propulseur à hydroglycérine à [[name:Shreev]] à [[Gadgetzan]] pour qu'il en retire la sécurité, sur l'insistance téméraire de [[name:Razzeric]]",
    [1189] = "ai rendu le propulseur modifié à [[name:Razzeric]], avec l'avertissement de [[name:Shreev]] qu'une seule erreur ferait de lui une tache brûlée sur la piste",
    [1190] = "ai volé les plans de [[name:Rizzle Brassbolts]] à la faveur de la diversion de Zamek, pour savoir pourquoi les chariots des gnomes étaient devenus plus rapides",
    [1193] = "ai réparé un piège cassé avec un rouage en thorium et de l'huile glaciale, une vilaine surprise pour tout ogre qui passerait par là",
    [1194] = "ai apporté à [[name:Pozzik]] un échantillon de minerai d'indurium trouvé avec les plans de Rizzle, le secret des chariots plus rapides des gnomes",
    [1198] = "ai cherché la garde d'argent Thaelrid à [[Blackfathom Deeps]], une éclaireuse de l'Aube d'argent qui n'avait pas fait son rapport depuis des semaines",
    [1199] = "ai arraché des pendentifs aux cultistes du Marteau du crépuscule qui se massaient avec les nagas à [[Blackfathom Deeps]], pour déjouer leur sinistre plan",
    [1200] = "ai tué le seigneur du crépuscule Kelris, qui sacrifiait des innocents à Aku'Mai dans un temple d'Elune en ruine, pour le guetteur de l'aube Selgorm",
    [1221] = "ai lâché un gaufre-renifleur pour flairer des tubercules de feuillebleue dans [[Razorfen Kraul]], un mets rare que Mebok Mizzyrix comptait vendre",
    [1244] = "ai fouillé [[Addle's Stead]] à [[Duskwood]] à la recherche du registre des Défias, un indice sur le diplomate qui n'avait jamais atteint Theramore",
    [1245] = "ai porté le registre des Défias à Elling Trias",
    [1249] = "ai maîtrisé Tapoke Jahn, l'espion de la taverne de Menethil, avant qu'il ne file avec ce qu'il savait du diplomate disparu",
    [1265] = "ai fouillé [[Sentry Point]] à la recherche du soldat Hendel, dont on disait qu'il était l'homme des Défias à bord du navire du roi",
    [1275] = "ai récolté des troncs cérébraux de satyres et de nagas à [[Blackfathom Deeps]] pour Gershala Nightwhisper, qui craignait que les elfes de sang ne soient eux aussi difformes",
    [1302] = "ai cherché à [[Theramore Isle]] des nouvelles de James Hyal, un aubergiste dont le frère n'avait plus de nouvelles depuis un moment",
    [1318] = "suis $gparti:partie; à la recherche du gantelet de puissance gordok, volé il y a longtemps par l'elfe Tortheldrin, que seul le vrai roi gordok pouvait reprendre",
    [1324] = "ai rossé le soldat Hendel, l'homme des Défias à bord du navire du roi, pour que Theramore puisse l'interroger sur le roi disparu",
    [1338] = "ai porté la demande de bouclier du montagnard Stormpike à Furen Longbeard, l'armurier nain qu'il admirait à [[Stormwind City]]",
    [1358] = "ai porté des échantillons de cœur de loup à l'apothicaire Helbrim dans [[Barrens]], qui étudiait les toxines de Lordaeron chez les bêtes de Kalimdor",
    [1359] = "ai livré des échantillons de ces cœurs de loup étrangement toxiques à l'apothicaire Zinge, un nouveau poison à étudier pour la Société",
    [1360] = "suis $gallé:allée; chercher la chope chérie de Krom Stoutarm dans son coffre, dans la salle commune nord de [[Uldaman]], pleine de troggs",
    [1364] = "ai repris les essais de Khadgar aux créatures du marais qui avaient effrayé Dellis, et les ai portés au guetteur Mahar Ba à [[Nethergarde Keep]]",
    [1365] = "ai tué le khan Dez'hepah, chef des Kolkars de [[Desolace]], pour briser le clan avant que les centaures ne puissent s'unir",
    [1366] = "ai rassemblé des oreilles de centaures de tous les clans pour Felgur Twocuts, pour réduire leur nombre et étouffer toute idée d'expansion",
    [1367] = "ai tué des centaures gelkis pour gagner la confiance de leurs rivaux magram, pour que la Horde apprenne à battre tous les clans",
    [1368] = "ai tué des centaures magram pour gagner le respect des Gelkis, pour que la Horde apprenne à battre tous les clans",
    [1369] = "ai brisé les larmes de Theradras amassées par les Gelkis pour Warug, pour leur montrer que leur mère des centaures ne les protégerait pas",
    [1370] = "ai pillé les réserves de viande séchée des Magram pour Uthek le Sage, pour que les Gelkis continuent de se battre pendant que leurs rivaux auraient faim",
    [1371] = "ai trouvé à Warug un nouveau leurre perfectionné, comme l'homme de bois qui faisait signe et qu'il avait pris dans la charrette d'un gnome qu'il avait tué",
    [1373] = "ai gagné un fragment de draenéthyste auprès d'Ongeku dans [[Swamp of Sorrows]], un cristal venu d'une terre de démons pour renforcer la magie d'Uthek",
    [1374] = "ai décapité le khan Jehn des Magram pour Uthek le Sage, pour que le clan tombe sans son chef",
    [1375] = "ai décapité le khan Shaka des Gelkis pour Warug, qui voulait regarder la tête et rire",
    [1380] = "ai sonné le cor de guerre maraudine pour faire sortir le khan Hratha, et porté son fragment de clé à Uthek le Sage",
    [1381] = "ai tué le khan Hratha des Maraudine pour Warug, après avoir gagné une embouchure et soufflé dans le cor de guerre qui l'appelait",
    [1382] = "ai tué des centaures magram pour gagner la confiance des Gelkis, pour que l'Alliance puisse conclure un pacte avec l'un des clans en guerre",
    [1383] = "ai rassemblé des cœurs de panthère, du champignon de Boueux et une tumeur d'Arpentefonds pour le prétendu sérum de vérité de l'apothicaire Faustin",
    [1384] = "ai arraché des charmes bruts aux Kolkars pour Uthek le Sage, qui comptait les brûler et rire de leur faible magie",
    [1385] = "ai combattu les Gelkis pour gagner la faveur des Magram, pour que l'Alliance apprenne à battre les clans centaures en guerre",
    [1386] = "ai massacré des centaures kolkars au nord pour montrer à Warug qu'on pouvait les tuer à la manière des Magram",
    [1387] = "ai coupé des oreilles de centaures pour le caporal Melkins à [[Nijel's Point]], éclaircissant les clans cruels dans l'espoir de la paix",
    [1389] = "ai repris les cristaux sacrés de draenéthyste que les Égarés de [[Fallow Sanctuary]] avaient volés, de peur que le peuple de Magtoor ne perde son chemin",
    [1391] = "ai apporté une bière mêlée du sérum de vérité de Faustin à l'infiltrateur Marksen, captif à [[Stonard]], une discrète course pour les Réprouvés",
    [1392] = "ai apporté le gourdin de Noboru au chef de [[Harborage]], preuve que la brute qui tuait tous les Draeneï sur son chemin était morte",
    [1393] = "ai escorté Galen loin des créatures qui allaient le dévorer, pour le trésor de son coffre et le truc pour l'ouvrir",
    [1394] = "suis $gretourné:retournée; voir [[name:Dorn Plainstalker]] au terme de ses épreuves, pour être $grécompensé:récompensée; d'un esprit, d'un corps et d'une âme qui avaient fait leurs preuves",
    [1395] = "ai porté en hâte une caisse de pierres de puissance à [[Nethergarde Keep]] avant qu'elles ne perdent leur pouvoir, trop urgent pour attendre une caravane",
    [1396] = "ai chassé les bêtes qui rôdaient autour du camp du guetteur Biggs, tout ce qui restait de sa caravane après l'attaque des Égarés",
    [1398] = "ai trouvé du bois flotté séché au soleil sur la côte pour que le guetteur Biggs puisse réparer son chariot et atteindre [[Nethergarde Keep]]",
    [1421] = "ai récupéré des composants de sorciers dans un chariot traîné jusqu'à [[Fallow Sanctuary]], indispensables au travail de [[Nethergarde Keep]] sur la Porte des ténèbres",
    [1423] = "ai rapporté un tonneau de fournitures perdues à l'intendant Lungertz, à [[Nethergarde Keep]], tant de choses se perdant en route",
    [1424] = "ai rassemblé des artefacts atal'ai autour de [[Pool of Tears]] pour Fel'zerul, afin de savoir comment [[The Temple of Atal'Hakkar]] avait été englouti",
    [1425] = "ai porté à [[Nethergarde Keep]] les fournitures vitales sauvées de la caravane du guetteur Biggs, que l'on y croyait perdues",
    [1426] = "ai décimé les murlocs de la plage pour Katar, qui gardait la côte de [[Stonard]] et haïssait la mer et tout ce qui en sortait",
    [1428] = "ai tué encore davantage de murlocs des marais, des oracles parmi eux, pour Katar, qui réclamait la mort de tous les hommes-poissons",
    [1429] = "ai porté des artefacts atal'ai à un prêtre atal'ai exilé parmi les Witherbark de [[The Hinterlands]], pour connaître leur véritable usage",
    [1430] = "ai rapporté à Dar des pattes de clampant monstrueux de la côte, une viande très prisée de ses clients de [[Orgrimmar]]",
    [1437] = "ai cherché le chariot de Tyranis et Dalinda Malem, des nobles darnassiens disparus, et l'ai trouvé pris en embuscade et vide",
    [1438] = "ai trouvé Dalinda Malem dans [[Thunder Axe Fortress]], où la Lame ardente comptait la sacrifier à ses maîtres démons",
    [1439] = "ai réglé le sort de Tyranis Malem, dont la soif des arcanes avait livré sa sœur à la Lame ardente",
    [1440] = "ai escorté Dalinda Malem hors de [[Thunder Axe Fortress]] et l'ai ramenée à Vahlarriel Demonslayer à [[Nijel's Point]]",
    [1442] = "me suis $gaventuré:aventurée; dans [[Blackfathom Deeps]] pour prendre aux nagas une gemme de Kor, à purifier pour le rituel du forgeron Stilwell",
    [1445] = "ai saisi des fétiches d'Hakkar dans [[Sunken Temple]] pour Fel'Zerul, qui craignait qu'ils ne soient la clé du rituel atal'ai derrière tout cela",
    [1446] = "ai tué Jammal'an le Prophète, dont les fausses visions d'Hakkar avaient perdu les Atal'ai, pour l'exilé qui avait conseillé la prudence",
    [1447] = "me suis $gbagarré:bagarrée; avec Dashel Stonefist et ses amis dans la vieille ville jusqu'à ce qu'il parle du complot des Défias",
    [1448] = "ai trouvé le temple d'Atal'Hakkar englouti sous l'étang des Larmes, le mystère qui avait échappé au vieux Brohann Caskbelly",
    [1452] = "ai rassemblé des gésiers de roc et des foies de groddoc et de fourrure-de-fer pour le Kocktail de Kalimdor de Rhapsody Shindigger, le prix de son histoire",
    [1454] = "ai cherché le coffre que le mage Karnitol avait abandonné aux géants des mers, et l'ai trouvé forcé et vide",
    [1456] = "ai arraché la sacoche de Karnitol aux nagas Ondulame, qui avaient pillé son coffre dans l'épave",
    [1457] = "ai rendu la sacoche de Karnitol à Roetten Stonehammer à [[Ironforge]], pour que le mage retrouve ses affaires",
    [1458] = "ai rassemblé des griffes et des cornes de satyres Fielfurie pour Kreldig Ungor, les premiers composants de la liste de Leftwitch",
    [1459] = "ai rassemblé du venin scorpashi et de vieilles peaux de kodo pour la liste de Leftwitch, pour aider Kreldig Ungor à rentrer plus tôt à [[Ironforge]]",
    [1465] = "ai remis le pendentif des Malem à Vahlarriel Demonslayer, avec la nouvelle de traces menant au sud vers un fort de la Lame ardente",
    [1466] = "ai pris aux démons des cervelles de gangrechien, des ailes du Néant et du sang de garde funeste, les derniers et les pires composants de Leftwitch",
    [1467] = "ai rapporté la caisse de Leftwitch à Roetten Stonehammer à [[Ironforge]] pour toucher la paie des Récupérateurs",
    [1469] = "ai porté le fragment de tablette atal'ai de Rhapsody Shindigger à Brohann Caskbelly, la preuve que le temple englouti se trouvait sous le marais",
    [1475] = "ai rassemblé des tablettes atal'ai intactes dans [[Sunken Temple]] pour Brohann Caskbelly, la dernière obligation d'un vieux nain",
    [1480] = "ai montré une peau de démon écorché à Maurin Bonesplitter, qui a lu dans ses runes un contrat signé par le seigneur démon Azrethoc",
    [1481] = "ai scalpé un traqueur des ténèbres Fielfurie pour que Maurin Bonesplitter brise les protections du seigneur démon contre la divination",
    [1482] = "ai arraché un cristal d'oracle aux oracles Ondulame, le focalisateur dont Maurin Bonesplitter avait besoin pour trouver le seigneur Azrethoc",
    [1486] = "ai dépecé les créatures déviantes de [[Wailing Caverns]] pour Nalpak, qui croyait que leurs peaux pouvaient servir à quelque chose de bon",
    [1487] = "ai purgé [[Wailing Caverns]] de leurs bêtes déviantes, un premier pas des disciples de Naralex vers des Tarides restaurées",
    [1488] = "ai tué le seigneur Azrethoc et son serviteur démoniste Jugkar Grim'rod avant que le démon ne plie la Lame ardente à ses desseins",
    [1491] = "ai rassemblé de l'essence de lamentation sur les créatures ectoplasmiques des cavernes pour les potions d'intelligence de Mebok Mizzyrix, son espoir de fortune",
    [1492] = "ai porté une caisse de potions et de composants au maître des quais Dizzywig à [[Ratchet]], pour le prochain bateau vers la crique des Eaux-Noires",
    [1498] = "ai chassé les lézards-tonnerre de la crête du Tonnerre pour leurs écailles roussies, la preuve pour Uzzek d'$gun:une; $gguerrier:guerrière; digne d'être le bouclier de la Horde",
    [1503] = "ai repris les barres d'acier volées par les Tranchecrin à Thun'grim Firegaze, un forgeron à moitié aveugle qui promettait une arme en retour",
    [1560] = "ai ramené Tooga, perdu en allant chercher le dîner, auprès de sa femme Torta au sud de [[Steamwheedle Port]]",
    [1578] = "ai forgé des haches en cuivre et des ceintures de mailles pour Thorvald, pour que les montagnards de [[Loch Modan]] restent bien équipés contre les troggs",
    [1581] = "ai préparé des élixirs pour Syral Bladeleaf, dont le mari passait tant de temps à préparer des potions pour leur boutique qu'ils n'avaient jamais de temps l'un pour l'autre",
    [1582] = "ai honoré les commandes de cuir estampé de Lotherias pour les jeunes aventuriers de [[Darnassus]], afin d'apprendre la veste de Moonglow",
    [1618] = "ai fait des ceintures runiques en cuivre et de lourdes masses en cuivre pour Verner Osgood, toujours à court de matériel avec [[Redridge Mountains]] sous les attaques des Blackrock",
    [1640] = "me suis $gbagarré:bagarrée; avec Bartleby l'ivrogne au Cochon et au sifflet pour sa chope, l'épreuve que fixait Harry Burlguard avant d'enseigner la moindre prise",
    [1643] = "ai cherché dans [[Trade District]] de [[Stormwind City]] quelqu'un aux nobles intentions qui avait besoin d'aide, et trouvé Stephanie Turner",
    [1644] = "ai apporté du lin à Stephanie Turner pour qu'elle couse des vêtements aux orphelins que le Fléau avait laissés à sa charge",
    [1647] = "ai cherché dans l'anneau extérieur de [[Ironforge]] quelqu'un qui avait besoin de la bonté d'un paladin, et trouvé John Turner",
    [1648] = "ai donné à John Turner le lin qu'il lui fallait pour envoyer enfin des vêtements à l'orphelinat que sa femme et lui tiennent à [[Stormwind City]]",
    [1650] = "suis $gparti:partie; vers le [[Longshore]] de [[Westfall]] soutenir Daphne Stilwell, seule face aux Défias pendant que son mari était absent",
    [1651] = "ai défendu la maison de Daphne Stilwell contre vague après vague de Défias, une épreuve de bravoure pour un paladin face à des forces écrasantes",
    [1655] = "ai repris aux ogres Mo'grosh la cargaison de minerai de Jordan Stilwell, dont ils avaient attaqué le convoi, pour Bailor Stonehand",
    [1656] = "ai porté un ballot de fourrures à l'aubergiste Kauth à [[Bloodhoof Village]] pour un jeune tauren trop épuisé par le rite de Force",
    [1657] = "ai lancé des boules puantes réprouvées au cœur de [[Southshore]] pour la Mande-ténèbres Yanka, un hommage de la Sanssaint à la libération des Réprouvés",
    [1658] = "suis $gallé:allée; observer la fête de l'Homme d'osier des Réprouvés [[at:Tirisfal Glades]] pour le sergent Hartman, qui craignait les ennuis qu'elle vaudrait à [[Southshore]]",
    [1667] = "ai repris l'insigne du maréchal Haggard dans le camp de Jack Dent-morte, pour que les Défias qui l'avaient dupé ne puissent se faire passer pour un officiel",
    [1678] = "ai pris la tête de Vejrek, le plus coriace des trolls près de [[Frostmane Hold]], pour prouver ma valeur de $gguerrier:guerrière; à Muren Stormpike",
    [1681] = "ai vengé le mentor de Tormus Deepforge sur les Sombrefer du camp d'Ironband et repris le minerai ombreux qui les avait attirés",
    [1683] = "ai détruit le satyre Vorlus Sabot-vil, qui souillait un puits de lune caché de [[Teldrassil]], et rapporté sa corne à Elanaria",
    [1686] = "ai vaincu l'ombre d'Elura, une capitaine condamnée à garder sa cargaison engloutie au large de [[Auberdine]], et remonté son élunite pour une arme",
    [1690] = "ai repoussé les bandits et les larrons Bat-le-désert qui avaient pris presque tous les puits autour de [[Gadgetzan]]",
    [1691] = "ai décimé les mages de l'ombre, les voleurs et les assassins des nomades pour que la Compagnie des eaux de [[Gadgetzan]] reprenne ses puits",
    [1699] = "ai couru le défi de Rethban pour Yorus Barleybrew, en évitant les gnolls jusqu'à la première fourche des cavernes, aller-retour en moins d'une heure",
    [1700] = "ai porté les notes de Furen Longbeard à Grimand Elmore, un fier forgeron qui détestait l'idée d'apprendre quoi que ce soit de son ancien élève",
    [1701] = "ai rassemblé des matériaux rares pour la cotte de mailles durcie au feu de Furen Longbeard, en bravant des chimères pour certains",
    [1702] = "ai porté un tonneau de Barleybrew Scalder au fabricant de boucliers Furen Longbeard à [[Stormwind City]], pour obtenir le bouclier promis par Yorus",
    [1703] = "ai porté les notes de Furen sur ses nouvelles techniques d'armure jusqu'au forgeron Mathiel à [[Darnassus]]",
    [1704] = "ai porté les notes de Furen à Klockmort Spannerspan à [[Ironforge]], qui était presque hors de lui devant la découverte de Furen",
    [1705] = "ai pris du sang ardent aux worgens Plaie-de-nuit de [[Roland's Doom]] et une pierre ardente à Gutspill, pour l'armure de Grimand Elmore",
    [1708] = "ai ramassé du corail brûlant sur la côte au sud de [[Menethil Harbor]] pour Klockmort Spannerspan, impatient d'essayer les techniques de Furen",
    [1710] = "ai fouillé sous les nids de wyvernes de [[Highperch]] à la recherche de coquilles d'œufs brûlées par le soleil, pour une armure que Mathiel ferait selon les nouvelles techniques de Furen",
    [1712] = "ai rassemblé ce dont Bath'rah le Guetteur des vents avait besoin pour invoquer le seigneur du vent Cyclonien, une épreuve de force et de ruse",
    [1713] = "ai vaincu Cyclonien, le seigneur du vent dont Bath'rah le Guetteur des vents attendait la chute depuis des siècles, et pris son cœur de tourbillon",
    [1719] = "ai remporté la Mêlée de l'île de la Dispute, en battant chaque adversaire puis le grand Will, pour gagner l'enseignement de Klannoc Macleod",
    [1783] = "ai relevé Narm Faulk grâce au symbole de vie, là où il était tombé sous les coups des nains Sombrefer au sud de [[Helm's Bed Lake]]",
    [1784] = "ai pris un script sombrefer près du lac du Lit d'Helm, une preuve pour le conseil sceptique de [[Ironforge]] que les Sombrefer étaient [[at:Dun Morogh]]",
    [1786] = "ai relevé Henze Faulk grâce au symbole de vie sur [[Heroes' Vigil]], où il était tombé en retenant des mages défias pour permettre à Gazin de fuir",
    [1787] = "ai saisi les papiers des sorciers défias renégats sur [[Heroes' Vigil]], une preuve pour les conseillers du roi que les Défias étaient dans [[Elwynn Forest]]",
    [1819] = "ai descellé Ulag le Fendoir et l'ai tué, un captif du Fléau que les gardes de la Mort n'avaient pas réussi à libérer du roi-liche",
    [1821] = "ai volé dans la crypte de la famille Agamand ses armes de famille pour Coleman Farthing, dont les maîtres, de son vivant, avaient causé la mort",
    [1824] = "suis $grevenu:revenue; en courant de [[Field of Giants]] avec des antennes qui frémissaient encore pour Ruga Ragetotem, une épreuve contre la montre sur la voie du guerrier",
    [1838] = "ai rassemblé du fer fumeux, de l'azurite, des barres de fer et du phlogiston pour que Thun'grim Firegaze forge la première pièce d'une armure de guerrier",
    [1842] = "ai pris les sabots enflés des satyres qui siphonnaient la magie de [[Ashenvale]], pour qu'Ula'elek mette leur pouvoir dans des gantelets brutaux",
    [1844] = "ai tué une matriarche chimère dans [[Charred Vale]] couvert de cendres pour mettre fin à sa misère, et rapporté sa corne galvanisée à Orm Stonehoof",
    [1846] = "ai rassemblé de solides tibias Dragonmaw [[at:Wetlands]] pour des jambières brutales de Velora Nitely, une fine armurière même dans la mort",
    [1861] = "ai puisé de l'eau au lac du Miroir pour que Jennea Cannon y cherche une souillure magique, de peur que ceux qui y buvaient n'en souffrent",
    [1880] = "ai récupéré parmi les gnomes lépreux le bidulotron de youplala de Bink, laissé dans une hutte aux portes de [[Gnomeregan]] quand les gnomes avaient fui",
    [1882] = "ai cueilli des gueules-de-loup à la ferme des Balnir pour que les mages réprouvés mesurent jusqu'où la peste s'était glissée [[at:Tirisfal Glades]]",
    [1884] = "ai détruit les tas de ju-ju que le démoniste Zalazane avait plantés sur [[Echo Isles]] pour dévier le flux de la magie [[at:Durotar]]",
    [1918] = "ai rapporté un globe d'eau souillée de [[Mystral Lake]] à [[name:Mastok Wrilehiss]], au cas où il renfermerait ce qui avait souillé le lac",
    [1920] = "ai capturé les créatures invisibles lâchées dans la Recluse bleue pour Jennea Cannon, qui craignait qu'une faille de mana s'y soit ouverte",
    [1921] = "ai rassemblé de l'étoffe de lin et des gemmes chargées de la faille dans [[Silver Stream Mine]] pour que Wynne Larson tisse une robe digne d'un mage",
    [1938] = "ai repris le traité d'Ur sur la magie des ombres dans la tour d'Ilgalar, où le mage déchu Morganth l'avait emporté",
    [1940] = "ai prélevé de la soie intacte sur les recluses charognardes de [[Duskwood]] pour une robe plus fine, digne d'un mage confirmé",
    [1944] = "ai rempli une flasque aux plus hautes chutes de [[Xavian]], aux mains des satyres, pour Deino, qui cherchait la magie légendaire de ses eaux",
    [1945] = "ai pris des mèches de cheveux aux sœurs rieuses de [[Ashenvale]], des dryades qui ne les auraient jamais données de leur plein gré, pour les robes de Kil'hala",
    [1948] = "ai trouvé du jade et chargé une ronce de foudre pour Tabetha, les premiers matériaux d'une baguette de mage",
    [1950] = "ai cherché l'apprenti disparu du magus Tirth autour des courses de [[Shimmering Flats]], pour la phrase qui ouvrait son coffre",
    [1951] = "ai repris les Rituels du pouvoir de Tirth, vendus à [[Scarlet Monastery]] pour payer ses dettes de jeu, pour le rituel de baguette de Tabetha",
    [1954] = "ai arraché un orbe infernal à un invocateur de la Lame ardente [[at:Desolace]], le réceptacle dont Tabetha avait besoin pour un bâton ou un orbe",
    [1955] = "ai tué le démon que Tabetha avait chassé de l'orbe infernal avant qu'il ne puisse y retourner d'un bond",
    [1956] = "ai vaincu la sentinelle d'obsidienne de [[Uldaman]] pour son antique source d'énergie, pour renforcer l'orbe de Tabetha",
    [1957] = "ai détruit les éruptions de mana qui jaillissaient d'une faille ouverte par Tabetha, pour que leur énergie remplisse l'orbe vide",
    [1960] = "ai capturé les créatures de magie invisibles lâchées dans la boutique d'Algernon, pour que les mages de [[Undercity]] sachent pourquoi elles étaient venues",
    [1961] = "ai pris des gemmes de mana aux mages de Dalaran de [[Silverpine Forest]] pour que Josef Gregorian les couse dans des robes de feu-sorcier",
    [2038] = "ai repris les outils et les capsuleurs soufflants que les troggs avaient volés à Bingles, dont l'assaut aérien sur [[Gnomeregan]] dépendait",
    [2040] = "ai récupéré l'alimentation d'un déchiqueteur gobelin dans [[Deadmines]] pour [[name:Shoni the Shilent]], pour forer un chemin de retour vers [[Gnomeregan]]",
    [2078] = "ai ramené [[name:The Threshwackonator 4100]], le second mécanique de Gelkak, auprès de son capitaine englouti pour régler son compte aux murlocs",
    [2098] = "ai repris aux bêtes du rivage les morceaux de la clé brisée de Gelkak Gyromast, pour que son second puisse fonctionner de nouveau",
    [2118] = "ai capturé vivant [[un:Rabid Thistle Bear]] pour Tharnariun Treetender, qui espérait guérir le mal qui rendait les ours fous",
    [2138] = "ai abattu des ours des chardons enragés pour Tharnariun, son remède ayant échoué, afin de ralentir les dégâts que la peste causait à la forêt",
    [2139] = "ai tué [[le:Den Mother]] dans sa grotte près de [[Bashal'Aran]], la dernière mise à mort que Tharnariun m'a demandée pour soulager la forêt",
    [2160] = "ai porté une caisse de ravitaillement par le col tenu par les troggs jusqu'à Tannok Frosthammer à [[Kharanos]]",
    [2161] = "ai porté le chargement de vivres du péon Ukor à l'aubergiste Grosk, à [[Razor Hill]], le péon ayant trop peur des bêtes de la route",
    [2178] = "ai chassé des trotteurs près de [[Auberdine]] pour leur viande, pour gagner la recette secrète du ragoût de trotteur frais d'Alanndarian Nightsong",
    [2198] = "ai remonté la piste d'un collier magique brisé, frappé du sceau de [[Ironforge]] et des lettres TdK, jusqu'au joaillier qui l'avait fait",
    [2199] = "suis $gallé:allée; chercher des barres d'argent pour Talvash del Kissel, un joaillier ruiné par les rumeurs d'un rival, pour ce qu'il savait du collier",
    [2200] = "ai fouillé [[Uldaman]] à la recherche des restes du paladin qui avait eu le collier de Talvash en dernier, pour laver le joaillier d'une malédiction dont on le disait frappé",
    [2201] = "ai pris les gemmes du collier dans une barricade Ombreforge, une urne trogg et sur le chef trogg Grimlok, comme le paladin l'avait écrit",
    [2202] = "ai ramassé des chapeaux de champignon magenta sur le site de fouilles de [[Uldaman]] pour Jarkal Mossmeld, curieux de leur usage en alchimie",
    [2204] = "ai abattu la plus puissante construction de [[Uldaman]] pour la source d'énergie dont Talvash del Kissel avait besoin pour rendre sa magie à son collier",
    [2240] = "ai exploré la chambre cachée de Khaz'mul grâce au journal de Baelog, une découverte qui pourrait pousser les dirigeants de [[Ironforge]] à reprendre [[Uldaman]]",
    [2278] = "ai appris du gardien des pierres des disques de Norgannon l'histoire des terrestres, des troggs et des nains",
    [2279] = "ai porté une miniature des disques de Norgannon à la Ligue des explorateurs à [[Ironforge]], peut-être la découverte du siècle",
    [2280] = "ai présenté une miniature des disques de Norgannon aux sages de [[Thunder Bluff]], qui y ont senti des secrets longtemps gardés par la terre",
    [2283] = "ai fouillé le site de fouilles de [[Uldaman]] à la recherche du précieux collier d'un paladin mort, pour les récupérateurs Dran Droffers et fils",
    [2284] = "suis $gredescendu:redescendue; dans [[Uldaman]] pour les gemmes manquantes du collier, et trouvé le journal taché de sang du paladin mort",
    [2338] = "ai prêté le collier à Jarkal Mossmeld pour qu'il l'étudie en secret, en échange d'une traduction du journal du paladin",
    [2339] = "ai récupéré à [[Uldaman]] les trois gemmes et la source d'énergie de la plus puissante construction, pour l'arrangement secret de Jarkal Mossmeld",
    [2340] = "ai remis le collier et les gemmes à Dran Droffers à [[Orgrimmar]], sans rien dire de la part de Jarkal Mossmeld dans l'affaire",
    [2342] = "ai repris à [[Uldaman]] l'arme de prédilection de la famille Garrett pour Patrick Garrett, qui s'est révélée être un balai",
    [2398] = "ai fouillé le fond de [[Uldaman]] à la recherche de Baelog et de sa bande, des nains pris au piège derrière les lignes troggs quand le site de fouilles avait été envahi",
    [2418] = "ai rassemblé des pierres de puissance à [[Uldaman]] pour Rigglefuzz, chassé par les Ombreforge une fois qu'il leur avait livré le secret des pierres",
    [2438] = "ai repris à [[Starbreeze Village]], aux mains des furbolgs, le capturêve d'émeraude de Tallonkai Swiftroot, un cadeau rare du gardien Gaerolas",
    [2459] = "ai repris l'émeraude que Ferocitas le Mange-rêves avait volée sur le capturêve de Tallonkai, et décimé ses mystiques Pin-tordu",
    [2499] = "ai traqué Chênebourru, autrefois grand chef des sylvains, dont la tumeur gargantuesque répandait la corruption autour de [[Lake Al'Ameth]]",
    [2500] = "ai rassemblé des gésiers, des crocs de coyote et des fragments d'élémentaire dans [[Badlands]] pour réapprovisionner l'alchimiste Ghak Healtouch",
    [2501] = "ai tiré le sang des dragons gardiens brûlés de [[Badlands]] pour Ghak Healtouch, en échange de la recette de son breuvage",
    [2518] = "ai mis fin aux souffrances de dame Sathrah, une araignée jadis aimée d'Elune devenue folle, et pris ses filières d'argent",
    [2520] = "ai offert les filières de dame Sathrah à la fontaine du temple, pour que les eaux sacrées lavent sa corruption et qu'elle puisse renaître",
    [2521] = "ai trouvé une sphère de draenéthyste sans défaut, l'un des cristaux les plus rares, pour Kum'isha, qui espérait ouvrir grâce à elle une faille vers chez elle",
    [2522] = "ai récupéré une autre sphère de draenéthyste sans défaut pour Kum'isha la Collectionneuse, toujours pleine d'espoir après l'échec du premier portail",
    [2541] = "ai pris un charme vaudou aux chamans Pin-tordu pour Oben Rageclaw, dont ils avaient arraché l'esprit à son corps endormi",
    [2561] = "ai tué le corps sans âme d'Oben Rageclaw, retourné par les Pin-tordu contre la Tanière, pour que son esprit repose dans le Rêve d'émeraude",
    [2581] = "ai rassemblé des bajoues, des poumons et une pince pour le mage de sang Drazial, qui avait vu des mâchoires de hyène trancher l'acier de thorium",
    [2582] = "suis $gallé:allée; chercher d'autres morceaux pour une nouvelle dose de l'essai Raillecroc du mage de sang Drazial, malgré ses avertissements sur ses séquelles durables",
    [2583] = "ai servi de premier cobaye à l'élixir des sangliers robustes du mage de sang Drazial, après lui avoir apporté les poumons et les pinces",
    [2584] = "suis $gretourné:retournée; dans la désolation pour un autre cocktail au jus de poumon du mage de sang Drazial, qui rendait dépendants même les esprits les plus forts",
    [2585] = "ai chassé des scorpoks, des vautours et un sanglier pour la tentative du mage de sang Drazial de mettre en bouteille la grâce et la vivacité du scorpok",
    [2586] = "ai échangé d'autres pinces et gésiers au mage de sang Drazial contre un échantillon de l'essai scorpok, les neuf autres gardés pour ses recherches",
    [2601] = "ai récolté des cervelles de basilics pierre-rouge pour la mage de sang Lynnore, qui avait vu ces bêtes réfléchir plus habilement que certains humanoïdes",
    [2602] = "ai apporté à la mage de sang Lynnore d'autres cervelles de basilic et gésiers pour une nouvelle dose de son composé, dont l'effet s'était dissipé",
    [2603] = "ai rassemblé des gésiers de vautour pour la mage de sang Lynnore, curieuse de savoir comment les charognards résistaient à la pestilence, dans l'espoir d'un remède",
    [2604] = "ai rassemblé d'autres gésiers et bajoues pour la gomme de gésier de la mage de sang Lynnore, une fois son euphorie spirituelle dissipée",
    [2605] = "suis $gallé:allée; chercher une glande de rosée remplie dans le jardin de cactus pour Marin Noggenfogger, qui espérait brasser une boisson contre sa terrible soif",
    [2621] = "ai demandé au commandant des missions Ruag, à [[Stonard]], ce qu'il était advenu des ordres que le Héros déchu n'avait jamais attendus",
    [2623] = "ai repris les ordres du chef de guerre dans la grotte du Parleur des marécages, saisis quand des murlocs avaient tendu une embuscade aux soldats qui les portaient",
    [2641] = "ai plongé dans un lac de [[Hinterlands]] pour un tragan violet, l'ingrédient secret de Sprinkle pour rendre buvable l'infecte rosée de Marin",
    [2662] = "ai regardé Marin Noggenfogger mélanger la rosée et la poudre violette dans l'élixir qui, jurait-il, lui rapporterait des millions",
    [2681] = "ai brisé les pierres qui liaient les hommes du Héros déchu au service de Razelikh, pour que leurs âmes torturées puissent reposer",
    [2721] = "ai découvert ce qu'il était advenu du lieutenant Kirith, entendu pour la dernière fois hurlant sous les expériences de l'archimage Allistarj",
    [2742] = "ai escorté Rin'ji, un troll captif, hors du pavillon de Quel'Danil, pour le secret qu'il jurait avoir caché à [[Overlook Cliffs]]",
    [2744] = "suis $gallé:allée; trouver le chasseur de démons Loramus Thalipedes [[at:Azshara]], puisque la triade de Razelikh ne pouvait mourir dans [[Blasted Lands]]",
    [2746] = "ai apporté à Tyrion de la soie et les pommes de Clara pour le déguisement qui ferait passer Espiobot devant les gardes de Lescovar",
    [2751] = "ai forgé des brassards, des espadons et des griffes en bronze pour Orokk Omosh, dernier de sa lignée, pour que les recettes des Omosh ne meurent pas avec lui",
    [2752] = "ai martelé des haches de bataille et des marteaux de guerre en bronze sur l'enclume d'Orokk Omosh, la leçon suivante de la voie des Omosh",
    [2753] = "ai fait des heaumes, des brassards et des jambières en fer vert pour Orokk Omosh, son avant-dernière leçon pour perpétuer l'héritage des Omosh",
    [2754] = "ai apporté à Orokk Omosh des masses en fer massif et des bottes et des gantelets en bronze argenté, la dernière leçon de la forge familiale des Omosh",
    [2755] = "ai regardé Orokk Omosh exécuter la danse de joie des Omosh, le dernier secret de famille d'un forgeron qui disait pouvoir désormais mourir heureux",
    [2758] = "ai fait des brassards en écailles dorées pour Hank le Marteau, qui avait promis à son vieux maître Galvan de former tout forgeron résolu",
    [2761] = "ai fondu des barres de fer et de mithril pour Galvan l'Ancien, qui tenait qu'un forgeron accompli doit aussi être mineur",
    [2762] = "ai apporté à Galvan l'Ancien du mithril et du vrai-argent, pour apprendre les gants ornés en mithril, et que le vrai-argent est un menteur",
    [2763] = "ai renforcé du mithril avec des citrines auprès de Galvan l'Ancien, une leçon sur la façon dont les gemmes amplifient la magie qu'un forgeron y met",
    [2765] = "ai reçu de Galvan l'Ancien la récompense d'$gun:une; $gforgeron:forgeronne; $gexpert:experte;, une babiole plus puissante que celle sacrifiée pour arriver jusqu'à lui",
    [2766] = "ai porté la balise de détresse d'[[name:Oglethorpe Obnoticus]] jusqu'à son robot de repérage écrasé près du val de la Balafre sauvage, pour qu'il puisse être récupéré",
    [2767] = "ai escorté le robot OOX-22/FE jusqu'au quai de [[The Forgotten Coast]], d'où il pourrait commencer son long décollage vers chez lui",
    [2768] = "ai repris le bâtonnet divino-matic que le sergent Bly avait volé, dont l'ingénieur en chef Bilgewhizzle avait besoin pour trouver de nouveaux points d'eau",
    [2770] = "ai fait sortir la grande bête Gahz'rilla du bassin sacré des trolls et pris son écaille électrique pour le chariot de [[name:Wizzle Brassbolts]]",
    [2771] = "ai échangé des leçons avec Trenton Lighthammer, des coiffes en mithril et une épaulière ornée contre son secret du heaume orné en mithril",
    [2772] = "ai fait un pantalon orné en mithril pour le tournoi de Trenton Lighthammer contre un déchiqueteur de la KapitalRisk, en échange de ses bottes ornées",
    [2773] = "ai montré au Gamin de mithril, Trenton Lighthammer, les gants ornés qu'il ne savait pas faire lui-même, en échange de son plastron orné",
    [2781] = "ai traqué le calife Dard-de-scorpide, chef des hors-la-loi Bat-le-désert, recherché pour le meurtre d'employés de la Compagnie des eaux de [[Gadgetzan]]",
    [2782] = "ai montré la tablette aux marques Witherbark de Rin'ji à l'érudit Oran Snakewrithe à [[Undercity]], pour savoir ce qu'elle valait",
    [2783] = "ai mis de côté la guerre contre les orcs pour rejoindre le Héros déchu de la Horde contre la Légion ardente",
    [2821] = "ai rassemblé des peaux de yéti épaisses pour Pratt McGrubben, un travailleur du cuir certain qu'une fois bien traitées elles seraient plus solides que le fer",
    [2822] = "ai chassé les yétis du val de la Balafre sauvage pour les peaux épaisses dont Jangdor Swiftstrider voulait rehausser la qualité de son cuir",
    [2844] = "ai cherché Shay Leafrunner, la jeune elfe de la nuit qui s'était éloignée dans les ruines alors que Mordroche était censé la surveiller",
    [2845] = "ai ramené Shay Leafrunner au camp de Mordroche, en faisant sonner sa précieuse clochette chaque fois qu'elle s'éloignait",
    [2846] = "ai arraché la tiare des abysses à l'hydromancienne Velratha, qui avait envoyé des voleurs la prendre à [[name:Tabetha]]",
    [2847] = "ai payé dix cuirs épais à Pratt McGrubben pour commencer à apprendre l'armure en cuir sauvage à [[Feathermoon Stronghold]]",
    [2848] = "ai fabriqué des renforts d'armure épais et trouvé une sauvageonne pour Pratt McGrubben, le prix du patron des épaulières en cuir sauvage",
    [2849] = "ai fabriqué des cuirasses et des gants en écailles de tortue pour les commandes de Pratt McGrubben, afin de gagner le gilet en cuir sauvage",
    [2850] = "ai honoré la commande de tuniques et de bandeaux de la nuit de Pratt McGrubben pour le patron du casque en cuir sauvage",
    [2851] = "ai cousu des pantalons et des bottes de la nuit et trouvé deux sauvageonnes, pour apprendre les bottes en cuir sauvage de Pratt McGrubben",
    [2852] = "ai fabriqué des casques et des brassards en écailles de tortue pour Pratt McGrubben, gagnant le patron des jambières en cuir sauvage",
    [2853] = "ai porté la lettre de Pratt McGrubben à son propre maître Telonis, pour être $greconnu:reconnue; comme son égal et apprendre le dernier patron en cuir sauvage",
    [2854] = "ai payé dix cuirs épais à Jangdor Swiftstrider pour devenir son apprenti en armure de cuir sauvage à [[Camp Mojache]]",
    [2855] = "ai fabriqué des renforts d'armure épais et trouvé une sauvageonne pour Jangdor Swiftstrider, le prix du patron des épaulières en cuir sauvage",
    [2856] = "ai fabriqué des cuirasses et des gants en écailles de tortue pour Jangdor Swiftstrider, afin de gagner le gilet en cuir sauvage",
    [2857] = "ai cousu des tuniques et des bandeaux de la nuit pour la leçon de Jangdor Swiftstrider sur le casque en cuir sauvage",
    [2858] = "ai fabriqué des pantalons et des bottes de la nuit et trouvé deux sauvageonnes, pour apprendre les bottes en cuir sauvage de Jangdor Swiftstrider",
    [2859] = "ai fabriqué des casques et des brassards en écailles de tortue pour Jangdor Swiftstrider, gagnant le patron des jambières en cuir sauvage",
    [2860] = "ai porté la lettre de Jangdor Swiftstrider à son maître Una, à [[Thunder Bluff]], pour être $greconnu:reconnue; comme son égal et apprendre le dernier patron",
    [2862] = "ai pris les crinières des gnolls Griffebois pour Hadoken Swiftstrider, dont les attaques menaçaient de chasser [[Camp Mojache]] de [[Feralas]]",
    [2863] = "ai tué des alphas Griffebois coup sur coup, pour que la perte soudaine de leurs chefs plonge les gnolls dans le chaos",
    [2865] = "ai rassemblé des carapaces de scarabée intactes à [[Zul'Farrak]] pour [[name:Tran'rek]], les scarabées ayant été chassés presque jusqu'à l'extinction ailleurs",
    [2866] = "ai exploré les ruines de Solarsal, tout juste envahies par les nagas Hainecrête, et trouvé l'étrange gloriette couverte de glyphes en leur cœur",
    [2869] = "ai pris des écailles aux nagas Hainecrête pour affaiblir leur emprise sur [[Sardor Isle]] avant qu'ils ne la prennent pour eux",
    [2870] = "ai tué le seigneur Shalzaru, un cruel prince naga, et saisi l'étrange relique que ses fouilleurs avaient déterrée sur [[Isle of Dread]]",
    [2871] = "ai porté la relique mystérieuse à Vestia Moonspear, une prêtresse et érudite qui saurait peut-être ce que c'était",
    [2873] = "ai repris le rhum de Stoley dans la ville pirate du capitaine Cuergo pour que Stoley puisse régler un pari avec MacKinley de [[Booty Bay]]",
    [2874] = "ai réglé le pari de MacKinley avec une bouteille de rhum de cale de Gentepression, portée jusqu'à [[Booty Bay]]",
    [2875] = "ai mis fin aux jours du pirate André Barbe-en-feu, recherché pour ses crimes contre Gentepression et [[Gadgetzan]], et rapporté sa tête",
    [2876] = "ai remis à [[Steamwheedle Port]] la copie pirate de ses horaires de navires, les traversées vers [[Booty Bay]] annotées de butins et de rudes combats",
    [2877] = "ai débarrassé l'ancienne base de la Horde à [[Skulk Rock]] de ses vases et de ses limons, pour que les Wildhammer étendent leur emprise",
    [2879] = "ai chargé le bâton de Troyas des quatre flammes de Vent-du-corbeau pour ouvrir le monolithe d'Equinex et l'artefact qui y était scellé",
    [2880] = "ai pris des colliers tribaux aux trolls qui étouffaient les collines de [[Hinterlands]], pour prouver un peu ma valeur aux Wildhammer, si indépendants",
    [2882] = "ai suivi une carte au trésor jusqu'à une plage au sud de Wheedle, avec un mât, un drapeau et des ossements, pour déterrer l'or de Cuergo",
    [2902] = "ai fouillé les camps Griffebois à la recherche des plans de bataille des gnolls, pour comprendre pourquoi leurs attaques contre [[Camp Mojache]] étaient devenues si coordonnées",
    [2903] = "ai apporté à Hadoken Swiftstrider les plans de bataille des Griffebois, qui montraient que les gnolls menaient une guerre sur deux fronts",
    [2932] = "ai planté la pique de Nimboya, chargée de crânes Witherbark, dans l'un de leurs villages pour punir les trolls qui avaient trahi Thrall",
    [2933] = "ai porté une bouteille de l'infect venin vert que gardaient les Witherbark à un apothicaire de [[Tarren Mill]], qui en voudrait peut-être un échantillon",
    [2934] = "ai chassé les araignées près de [[Shadra'Alor]] pour une glande à venin intacte, un échantillon frais pour l'apothicaire Lydon",
    [2936] = "ai vaincu Theka le Martyr pour la tablette portant le vrai nom de la déesse araignée des Witherbark, pour que maître Gadrin puisse l'invoquer",
    [2937] = "ai invoqué Shadra, la déesse araignée des Witherbark, à son autel de [[Shadra'Alor]] et l'ai vaincue pour le venin de l'apothicaire Lydon",
    [2938] = "ai porté le venin de Shadra, le poison le plus puissant que l'apothicaire Lydon ait connu, au maître apothicaire Faranell à [[Undercity]]",
    [2942] = "ai rendu le bâton d'Equinex et la pierre étincelante du monolithe à Troyas Moonbreeze, qui l'a nommée la pierre de l'Aurore",
    [2943] = "ai apporté le vieux livre de Daryn Lightwind, Feralas : une histoire, à Troyas Moonbreeze, qui espérait y apprendre ce qu'était son bâton",
    [2944] = "ai pris une photo de la tortue géante Gammerita avec le Preneur d'images FX, le prix du prêt du livre de Daryn Lightwind",
    [2954] = "ai appris du gardien des pierres de Norgannon que seules les tablettes d'Uldum ouvriraient le chemin d'Uldum",
    [2969] = "ai libéré avec Kindal Moonweaver les fées fléchetteuses enfermées dans le camp des Totem-sinistre, et vu les dragons féeriques s'en sortir vivants",
    [2970] = "ai porté le combat dans les camps des Totem-sinistre avec Kindal et Jer'kai Moonweaver, en représailles pour les dragons féeriques qu'ils avaient mis en cage",
    [2972] = "ai porté la chevalière de Jer'kai Moonweaver à Tyrande Whisperwind à [[Darnassus]], la nouvelle que sa prêtresse allait bien",
    [2973] = "ai rassemblé des ailes de fées fléchetteuses pour que Krueg Skullsplitter fasse une nouvelle cape à Korrin, sa compagne, qui aimait les beaux vêtements",
    [2974] = "ai pris des cornes aux Totem-sinistre pour Krueg Skullsplitter, puisque Belgrom à [[Orgrimmar]] avait mis leur tête à prix",
    [2975] = "ai repoussé les ogres Gordunni à leur avant-poste en amont de la rivière, avant qu'ils ne s'étendent davantage [[at:Feralas]]",
    [2976] = "ai porté une caisse de cornes de Totem-sinistre à Belgrom Rockmaul à [[Orgrimmar]], avec la nouvelle que les Totem-sinistre étaient [[at:Feralas]]",
    [2978] = "ai apporté un parchemin Gordunni souillé à Rok Orhan, dont les images montraient une réunion ou une cérémonie, trouvé à l'avant-poste des ogres",
    [2979] = "ai pris un orbe à un seigneur-mage Gordunni pour que Rok Orhan sache tout de la sombre cérémonie que préparaient les ogres",
    [2980] = "ai chassé les Gordunni les plus forts des vieilles ruines elfiques des Hautes-terres sauvages, où la terre s'était flétrie autour d'eux",
    [2982] = "ai débarrassé les ruines des Hautes-terres sauvages de leurs ogres pour Angelas Moonbreeze, pour que son Troyas y soit plus en sécurité sans le savoir",
    [2987] = "ai déterré le cobalt que les Gordunni enterraient près de leur avant-poste pour Orwin Gizzmick, qui comptait le vendre à bon prix",
    [2988] = "ai fouillé les cages des villages Witherbark à la recherche de Becaiguisé, l'héritier du plus puissant griffon de [[Aerie Peak]], qu'on croyait pris par les trolls",
    [2989] = "suis $gmonté:montée; sur l'autel de Zul, où les trolls Vilebranch faisaient leurs sacrifices, à la recherche du griffon disparu Becaiguisé",
    [2990] = "ai remis une plume du nid de Becaiguisé au devin Thadius Grimshade, dont la magie pourrait remonter jusqu'au griffon",
    [2991] = "ai pris le médaillon de Nekrum l'Étripeur pour [[name:Thadius Grimshade]], le prix de son aide pour retrouver le griffon Becaiguisé",
    [2994] = "me suis $gbattu:battue; jusqu'en haut de [[Jintha'Alor]] et tué la prêtresse infâme Hexx pour la clé de la cage de Becaiguisé, pour que le jeune griffon puisse rentrer chez lui",
    [2995] = "ai brûlé les archives de Hautval au pavillon de Quel'Danil pour couper les hauts-elfes de leurs alliés potentiels",
    [3002] = "ai porté l'orbe Gordunni à Uthel'nay à [[Orgrimmar]], une mage capable de dire quel était son dangereux pouvoir",
    [3022] = "ai porté une caisse d'œufs d'hippogriffe au druide Erelas Ambersky à [[Rut'theran Village]], qui les faisait éclore et dressait les petits",
    [3042] = "ai rassemblé de l'agent durcissant troll sur les trolls Sandfury pour [[name:Trenton Lighthammer]], un produit recherché pour tremper ses ouvrages",
    [3062] = "ai invoqué la reine harpie Edana Serrehaine aux pierres de Serrehaine et pris son cœur noir pour [[name:Talo Thornhoof]]",
    [3063] = "ai vengé le vieux [[name:Talo Thornhoof]] sur les harpies de Sourcenord, dont l'embuscade hantait le chasseur depuis des années",
    [3121] = "ai porté la tête de nain réduite du sorcier-docteur Uzer'i à Neeru Fireblade à [[Orgrimmar]], en échange des herbes dont il avait besoin",
    [3122] = "ai rapporté la bourse d'herbes de Neeru au sorcier-docteur Uzer'i, la dernière chose qu'il lui fallait pour préparer son réceptacle de muisek",
    [3124] = "ai tué des hippogriffes Plume-usée et capturé leurs esprits fidèles dans le réceptacle de muisek du sorcier-docteur Uzer'i",
    [3125] = "ai capturé le muisek des fées fléchetteuses pour le sorcier-docteur Uzer'i, pour que la Horde partage la force de leur esprit",
    [3126] = "ai abattu des marche-forêts errants et enfermé leurs esprits protecteurs dans le réceptacle de muisek du sorcier-docteur Uzer'i",
    [3127] = "ai abattu des géants des montagnes et scellé leur puissant muisek dans le réceptacle, le dernier esprit dont le sorcier-docteur Uzer'i avait besoin",
    [3128] = "ai rassemblé des bûches fendues, des minéraux, des tendons et des éclats de métal pour que le sorcier-docteur Uzer'i lie le muisek à des armes",
    [3161] = "ai déterré des ornements gahz'ridian, reliques du dieu hydre des trolls Gahz'rilla, pour que Marvon Rivetseeker les étudie",
    [3181] = "ai apporté au montagnard Pebblebitty la grande corne où était resté planté le fer de sa propre hache, pour qu'il la traite de fausse",
    [3182] = "ai prouvé au conservateur Thorius à [[Ironforge]] que la corne était bien celle de Margol l'Enragé, le prix d'une clé de [[Searing Gorge]]",
    [3281] = "ai repris l'argent volé aux gardes de [[Crossroads]] dans les nids de raptors de [[Raptor Grounds]], leur solde du mois suivant",
    [3301] = "ai livré une carapace de Gueule d'acier luisante à Mura Runetotem, qui espérait que son secret guérirait la forêt mourante des Pins argentés",
    [3321] = "ai été $gaccueilli:accueillie; dans l'ordre du Mithril par Trenton Lighthammer, qui m'a rendu la babiole sacrifiée pour arriver jusqu'à Galvan",
    [3361] = "ai repris aux trolls le coffre, la boîte et le seau de boulons de Felix Whindlebolt, perdus quand il avait fui [[Gnomeregan]] irradié",
    [3362] = "ai débarrassé [[Thistleshrub Valley]] de ses chardonniers pour que Tran'rek ose y retourner",
    [3364] = "ai porté en courant un thé brûlant à Durnan Furcutter à [[Anvilmar]] avant qu'il ne refroidisse",
    [3367] = "ai essayé d'aider Dorius, grièvement blessé, à regagner [[Ironforge]], saignant de l'intérieur et la tête qui tournait",
    [3368] = "ai porté la lettre roussie de Dorius à son frère Thorius à [[Ironforge]], une supplique pour libérer l'équipe de fouilles asservie par Lathoric le Noir",
    [3369] = "ai porté un éclat du Rêve d'émeraude à Hamuul Runetotem à [[Thunder Bluff]], un cauchemar dont Falla refusait de parler",
    [3370] = "ai porté un éclat du Rêve d'émeraude à Mathrengyl Bearwalker à [[Darnassus]], un cauchemar dont Falla refusait de parler",
    [3372] = "ai porté une relique du Marteau du crépuscule à l'autel de Suntara, pour libérer les archéologues forcés de travailler même après leur mort",
    [3373] = "ai déposé l'essence d'Eranikus dans les fonts de son repaire, pour tenter de purger l'esprit du dragon vert de la souillure des trolls",
    [3374] = "me suis $gengagé:engagée; à aider le Vol draconique d'Ysera en remettant à Itharius l'essence enchaînée d'Eranikus, pour racheter l'âme du dragon",
    [3375] = "ai rassemblé une potion de mana, du charbon et du nectar sucré pour que Talvash del Kissel, en ronchonnant, fasse une nouvelle fiole de divination",
    [3376] = "ai apporté au brave Windfeather la tête du chef Brochaigu Mantépine, dont les Dos-hirsute faisaient la guerre aux taurens du plateau",
    [3378] = "ai repris aux adorateurs de l'idole la prière dorée de Zamael à Elune pour Astarii Starseeker, pour que la prière d'une âme en cage soit entendue",
    [3379] = "ai traqué les braconniers qui massacraient les araignées de [[Searing Gorge]], la source de la soie d'ombre, pour Nilith",
    [3382] = "ai défendu la capitaine Vanessa Beltis, son équipage et ses passagers lors d'une attaque naga de nuit, un combat auquel tout son équipage n'a pas survécu",
    [3385] = "ai tué le maître d'artisanat Kovic et son sbire Clonk, dont le marché noir sans pitié entretenait des liens étroits avec les nains Sombrefer",
    [3442] = "ai rassemblé des cœurs des flammes et de l'huile de golem pour la torche de Kalaran Windblade, destinée à incendier les tours de guet Sombrefer",
    [3443] = "ai pris des dagues plaquées en thorium aux contremaîtres et aux esclavagistes Sombrefer, pour les reforger en manche pour la torche de Kalaran Windblade",
    [3444] = "suis $gallé:allée; chercher une pierre marquée d'un serpent dans l'atelier de Marvon Rivetseeker à [[Ratchet]], pour réveiller ses souvenirs de [[Sunken Temple]]",
    [3446] = "ai cherché l'autel d'Hakkar dans [[Sunken Temple]], le secret que Marvon Rivetseeker avait entrevu après avoir failli mourir dans un piège",
    [3447] = "ai percé le secret du cercle de statues de [[Sunken Temple]], qui cachait selon Marvon un trésor plus grand encore",
    [3452] = "ai saisi un symbole de Ragnaros dans le camp du Marteau du crépuscule, sa magie immonde destinée à l'enveloppe de la torche",
    [3463] = "ai incendié les quatre tours de guet Sombrefer avec la torche du châtiment, laissant vide leur première ligne de défense",
    [3510] = "ai tué Hetaera, la fausse reine des mers qui tuait les enfants du seigneur Arkkoroc, pour ses trois têtes et le vrai nom d'un seigneur démon",
    [3511] = "ai porté la trempe de sang du seigneur Arkkoroc et le vrai nom du seigneur démon à Loramus Thalipedes, pour forger des armes contre lui",
    [3513] = "ai porté un parchemin runique à l'air officiel à la tour de garde près de la frontière de [[Ashenvale]], au cas où il concernerait les elfes de la nuit",
    [3514] = "ai tué Rynthariel le Maître des clés et planté une bannière de la Horde dans l'antre des Serres, pour que l'Alliance n'envoie plus de messagers",
    [3517] = "ai trouvé quatre tablettes bien-nées dans les ruines d'Eldarath pour Jediga, une orque qui tirait le meilleur parti de sa punition [[at:Azshara]]",
    [3518] = "ai livré la tablette de Beth'Amara à Magatha à [[Thunder Bluff]], qui espérait qu'elle aiderait les Réprouvés à redevenir humains",
    [3520] = "ai capturé les esprits des hurleurs du val de [[Feralas]] pour Yeh'kinya, qui les disait liés à un très, très vieux dieu",
    [3524] = "ai pris les os d'une créature marine échouée, cernée de murlocs Grisebrume, pour comprendre pourquoi de telles bêtes s'échouaient",
    [3527] = "ai arraché les deux tablettes Mosh'aru à Theka le Martyr et à l'hydromancienne Velratha, une prophétie sur la façon de contenir l'essence d'Hakkar",
    [3528] = "ai invoqué l'avatar d'Hakkar dans [[Sunken Temple]] et capturé son essence dans l'œuf d'Hakkar pour Yeh'kinya",
    [3541] = "ai remis la tablette de Jin'yael à Jes'rimon, le receleur de Jediga dans la Herse, ravi d'apprendre où elle se trouvait",
    [3542] = "ai porté la tablette de Markri à Andron Gant à [[Undercity]], pour les mages désireux d'étudier l'invocation des Bien-nés",
    [3561] = "ai porté la tablette de Sael'hai à l'archimage Xylem dans sa tour au-dessus de [[Azshara]], l'acheteur dont Jediga se méfiait le plus",
    [3566] = "ai tué Lathoric le Noir et Obsidion pour Thorius, pour découvrir que le piège était l'œuvre de son propre frère",
    [3568] = "ai rempli des fioles aux bassins de marée des ruines d'Eldarath pour que le chimiste Cuely sache ce qui avait rendu malade Thersa Windsong",
    [3569] = "ai donné l'élixir de Cuely à Thersa Windsong, souffrante, qui n'avait trouvé aucun autre remède, dans l'espoir qu'il la sauve",
    [3601] = "ai pillé le camp de base thalassien pour l'équipement que les elfes de sang avaient gardé après s'être retournés contre Kim'jael, poulet empaillé compris",
    [3602] = "ai récupéré du cristal d'azsharite sur les terres des violents géants des falaises au sud de [[Azshara]], le corps des armes de Loramus",
    [3621] = "ai porté l'azsharite trempée à Galvan l'Ancien [[at:Stranglethorn Vale]], un forgeron capable de canaliser l'énergie gangrenée dans des armes",
    [3627] = "ai tué Grol le Destructeur, dame Sevine et l'archimage Allistarj pour les morceaux de l'amulette qui invoque Razelikh",
    [3628] = "ai détruit Razelikh le Souilleur au sommet de la plus haute montagne de [[Blasted Lands]], sa corne un symbole d'espoir",
    [3638] = "ai juré le secret à vie aux ingénieurs gobelins, renonçant pour de bon à l'ingénierie gnome",
    [3639] = "ai fabriqué de grandes bombes en fer, de la dynamite solide et des moutons explosifs pour [[name:Nixx Sprocketspring]], pour gagner une carte de membre des ingénieurs gobelins",
    [3640] = "ai signé la promesse de secret des ingénieurs gnomes pour le Bricomaître Overspark, fermant pour de bon la porte à l'ingénierie gobeline",
    [3641] = "ai fabriqué des tubes en mithril, une lunette et des leurres pour le Bricomaître Overspark, pour gagner une carte de membre des ingénieurs gnomes",
    [3642] = "ai prêté le serment de secret des ingénieurs gnomes devant [[name:Oglethorpe Obnoticus]] à [[Booty Bay]], renonçant à l'ingénierie gobeline",
    [3643] = "ai montré à [[name:Oglethorpe Obnoticus]] des échantillons de mon travail, des tubes en mithril, une lunette et des leurres, pour une carte de membre des ingénieurs gnomes",
    [3741] = "ai retrouvé le collier d'Hilary dans le lac de [[Lakeshire]], où l'on avait interdit aux enfants de se baigner",
    [3764] = "ai déterré de l'humus de [[Un'Goro Crater]] pour le Cercle cénarien à [[Darnassus]], pour démêler le vrai du faux sur ses qualités magiques",
    [3785] = "ai fait pousser de la fibre d'aurore à partir de graines de Tharlendis dans l'humus d'Un'Goro, une herbe mystérieuse que l'archidruide voulait percer",
    [3791] = "ai apporté de la fibre d'aurore à Quintis Jonespyre, troublé que l'archidruide en amasse tant au nom du Cercle",
    [3822] = "ai repris l'anneau de nez de mariage de Sha'ni à son assassin Krom'Grul et l'ai porté, avec ses dernières paroles, à Thal'trak, en deuil",
    [3823] = "ai affaibli les ogres Brûlentrailles qui gardaient [[Dreadmaul Rock]] et les lignes de ravitaillement des orcs Blackrock, sur les ordres délirants d'Oralius",
    [3824] = "ai tranché la tête de Gor'tesh le Seigneur brutal, maître des ogres Brûlentrailles, pour le coup décisif que préparait Oralius",
    [3825] = "ai planté la tête de Gor'tesh sur une pique au sommet de [[Dreadmaul Rock]], pour faire fuir de terreur les derniers ogres Brûlentrailles",
    [3841] = "ai porté un œuf de fée fléchetteuse, sauvé d'un nid dont la mère était morte, à Quentin dans [[Thousand Needles]] pour le voir éclore",
    [3842] = "ai apporté à Quentin des élixirs de robustesse pour un petit sort qui protégerait l'œuf de fée fléchetteuse avant l'éclosion",
    [3843] = "ai porté en hâte le fragile œuf de fée fléchetteuse à Agnar Beastamer à [[Aerie Peak]] en moins d'une heure, avant que le petit ne meure",
    [3844] = "ai fouillé l'étang près d'un radeau naufragé à la recherche d'un indice sur son propriétaire, et tiré du fond un sac gorgé d'eau",
    [3845] = "ai rendu un sac perdu à Linken à [[Marshal's Refuge]], qui n'a reconnu qu'à moitié ses propres affaires",
    [3881] = "ai récupéré la nourriture et le matériel de recherche des camps envahis de l'expédition échouée de Williden Marshal",
    [3882] = "ai déterré des os de dinosaure pour Spark Nilminer des Expéditions Marshal, qui préférait ne pas savoir s'ils venaient de bêtes vivantes",
    [3883] = "ai gratté une paroi de ruche gorishi pour Hol'anyee Marshal, qui voulait savoir pourquoi ces insectes venus d'ailleurs étaient arrivés [[at:Un'Goro Crater]]",
    [3884] = "ai rendu un journal abîmé à Williden Marshal, dont l'expédition avait fui les bêtes du cratère vers les hauteurs",
    [3904] = "ai sauvé la récolte de raisin de Milly Osworth dans les vignes envahies, avant que les voleurs défias ou les gardes qui piétinaient tout ne la gâchent",
    [3905] = "ai livré le manifeste des vendanges de Milly au frère Neals dans le clocher de l'abbaye, l'heureuse nouvelle de raisin frais pour plus de vin",
    [3906] = "ai tué le grand seigneur Pyron, le seigneur du feu invoqué par les nains Sombrefer, avant qu'il n'accable la terre de sécheresse",
    [3908] = "ai porté l'épée de Linken à Donova Snowden dans [[Winterspring]] pour qu'elle la trempe, même si Linken ne se rappelait plus pourquoi",
    [3909] = "ai retrouvé Gregan Brewspewer dans les terres sauvages de [[Feralas]] pour l'élixir de Videre, pour que l'épée de Linken soit achevée",
    [3912] = "ai bu l'élixir de Videre dans le cimetière aux portes de [[Gadgetzan]] pour parler à Gaeriyan, qui pouvait achever l'épée de Linken",
    [3913] = "ai déposé l'épée de Linken dans le creux sous la pierre tombale dont parlait Gaeriyan, où un éclair de lumière l'a transformée",
    [3914] = "ai rendu l'épée transformée à Linken, qui ne se rappelait toujours pas pourquoi il en avait besoin",
    [3921] = "ai porté le samophlange cassé à l'astucieuse Wenikee Boltbucket près du rempart de Mor'shan, dans l'espoir qu'elle le répare",
    [3922] = "ai pillé les seaux à outils de la KapitalRisk dans [[Sludge Fen]] pour des rondelles de métal, pour que Wenikee Boltbucket se mette au samophlange",
    [3923] = "ai apporté le samophlange cabossé à Rilli Greasygob à [[Orgrimmar]], une ancienne de la KapitalRisk qui saurait peut-être le réparer",
    [3924] = "ai repris le manuel du samophlange et ses pages au patron Copperplug, pour que Rilli Greasygob apprenne à réparer l'appareil",
    [3961] = "ai apporté le totem en argent d'Aquementas à Linken, dans l'espoir qu'il lui rappelle qu'il était venu combattre Blazerunner",
    [3962] = "ai brisé l'aura de Blazerunner et l'ai vaincu sur [[Fire Plume Ridge]] pour la Flamme dorée, un pouvoir trop dangereux pour un cœur mauvais",
    [4005] = "ai invoqué Aquementas à [[Lost Rigger Cove]] avec le livre d'Aquor pour forger un totem capable de briser l'aura de Blazerunner",
    [4021] = "ai combattu les Kolkars vengeurs venus de [[Desolace]] jusqu'à l'apparition du seigneur de guerre Krom'zar, et pris un morceau de sa bannière",
    [4061] = "ai arraché des fragments aux automates de roche de [[Burning Steppes]] pour que Theodora Mulvadania découvre d'où venaient les golems",
    [4084] = "ai rassemblé des griffes argentées et un cœur d'arbrefer à [[Felwood]] pour Eridan Bluewind, vers un pouvoir capable de dissiper l'aura de Blazerunner",
    [4120] = "ai affronté les ours et les loups rendus fous par la gangrène de [[Felwood]] pour [[name:Talo Thornhoof]], pour savoir si la corruption les rendait plus forts",
    [4125] = "ai fouillé la côte de [[Feralas]] à la recherche du bateau de Raschal, un messager de Pennelune disparu depuis une semaine",
    [4127] = "ai apporté à Ginro Hearthkindle un couteau trouvé dans la boue près du bateau échoué de Raschal, le premier indice sur le sort du messager",
    [4129] = "ai porté le couteau de Raschal au druide Quintis Jonespyre, dont la psychométrie pourrait montrer ce qui était arrivé au messager",
    [4131] = "me suis $gjeté:jetée; sur les camps des gnolls Griffebois à la recherche des sacs de Raschal, la trace suivante du messager disparu",
    [4135] = "ai suivi la note hâtive de Raschal jusqu'au fond de [[The Writhing Deep]], où il était parti à la poursuite d'insectes qui menaçaient tout [[Feralas]] selon lui",
    [4141] = "ai cueilli des pétales-de-sang pour Muigin, qui espérait dresser les créatures végétales du cratère pour embêter Larion, qu'il tenait pour responsable de leurs ennuis",
    [4142] = "ai montré un pétale-de-sang à Gregan Brewspewer [[at:Feralas]], un expert capable d'expliquer l'étrange intelligence de ces plantes",
    [4143] = "ai recueilli de la brume atal'ai dans le temple d'Atal'Hakkar pour Muigin, l'horrible substance qui lui permettrait de contrôler les pétales-de-sang",
    [4145] = "ai abattu les pétales-de-sang nuisibles que Muigin envoyait sans cesse embêter Larion, qui le tenait pour responsable de les avoir perdus",
    [4146] = "ai recueilli de la brume atal'ai sur les limons et les rôdeurs du temple pour alimenter une baguette à insectes contre les pétales-de-sang nuisibles",
    [4161] = "ai ramassé seulement les pattes d'araignée que demandait Zarrin, pas une de plus que ce qu'il lui fallait",
    [4182] = "ai repoussé les dragonides noirs rassemblés sous la crête d'Helendis Riverhorn, dans [[Burning Steppes]]",
    [4183] = "ai porté l'avertissement d'Helendis Riverhorn au magistrat Solomon : le vol noir était le vrai maître des orcs Blackrock",
    [4184] = "ai plaidé la cause de [[Lakeshire]] devant le généralissime Bolvar Fordragon, car la ville ne pouvait survivre à la fois aux orcs Blackrock et aux dragons noirs",
    [4186] = "suis $grevenu:revenue; à [[Lakeshire]] avec le décret de Bolvar",
    [4224] = "ai retrouvé John le Loqueteux dans sa grotte pour savoir ce qu'il était advenu du maréchal Windsor et des renseignements sur les Blackrock perdus avec lui",
    [4243] = "ai fouillé le repaire des singes à [[Fungal Rock]] à la recherche d'A-Me 01, la guenon mécanique de Karna Remtravel, et l'ai trouvée cabossée et sans énergie",
    [4244] = "ai monté une nouvelle caisse en mithril dans A-Me 01 pour que la guenon mécanique de Karna Remtravel puisse remarcher",
    [4245] = "ai escorté A-Me 01, bien cabossée, jusqu'à Karna Remtravel en évitant les gorilles de [[Un'Goro Crater]]",
    [4262] = "ai tué le grand seigneur Pyron à la carrière de Blackrock pour que l'expédition de Jalinda Sprig puisse entrer dans [[Blackrock Depths]]",
    [4265] = "ai libéré Raschal, le messager disparu de Pennelune, vivant, d'un cocon de la ruche zukk'ash",
    [4267] = "ai porté le rapport de Raschal sur l'infestation à Gracina Spiritmight à [[Darnassus]], une prêtresse qui connaissait ce genre de créatures",
    [4281] = "ai livré à Falfindel Waywarder, au relais de Thalanaar, le colis que le messager disparu n'avait jamais apporté",
    [4283] = "ai arraché des médaillons aux orcs Blackrock pour Oralius, qui voulait des insignes pour aller avec sa collection d'oreilles d'ogres",
    [4284] = "ai rassemblé des cristaux de puissance de quatre couleurs pour J.D. Collie, qui y sentait un pouvoir que ses expériences n'avaient pas encore trouvé",
    [4285] = "ai trouvé le pylône de cristal du nord pour J.D. Collie, qui ne cessait de se demander à quoi servaient les pylônes",
    [4287] = "ai localisé le pylône de cristal de l'est pour satisfaire enfin la curiosité de J.D. Collie au sujet des pylônes dont on parlait",
    [4288] = "ai cherché le pylône de cristal de l'ouest, dans l'espoir qu'il détienne la clé des expériences infructueuses de J.D. Collie sur les cristaux",
    [4289] = "ai dépecé les grands singes du nord de [[Un'Goro Crater]] pour Torwa Pathfinder, des peaux pour vêtir la tribu et une preuve de force",
    [4290] = "ai volé de la viande sur la dernière proie de Lar'korwi pour provoquer la bête qui avait autrefois traqué le frère de Torwa Pathfinder",
    [4291] = "ai provoqué les compagnes ravasaures de Lar'korwi pour leurs glandes à phéromones, l'appât dont Torwa Pathfinder avait besoin pour le faire sortir",
    [4292] = "ai appâté Lar'korwi avec la viande volée et l'odeur de ses compagnes, et rapporté la tête du monstre à Torwa Pathfinder",
    [4293] = "ai testé des échantillons de limon de [[Felwood]] pour trouver les plus corrompus, pour que le chimiste Fuely étudie les créatures de ses bassins gangrenés",
    [4294] = "ai rassemblé les limons les plus purs de [[Un'Goro Crater]] pour le chimiste Fuely, qui se demandait comment évoluaient les créatures épargnées par la corruption",
    [4296] = "ai recopié la tablette des Sept dans les ruines de Thaurissan pour Maxwort Uberglint, qui espérait que son savoir nain les rendrait riches",
    [4297] = "ai chassé des traqueurs Crins-d'argent pour leurs flancs crus, pour que le petit de fée fléchetteuse ait de quoi manger",
    [4298] = "ai pris la fée fléchetteuse tout juste éclose des mains d'Agnar Beastamer, pour qu'elle s'attache à son nouveau parent",
    [4301] = "ai vaincu U'cha, l'énorme singe que Torwa Pathfinder appelait l'un des plus grands fils de la Terre-Mère, et rapporté sa peau",
    [4449] = "ai donné une leçon aux géologues Sombrefer pour le nain qu'ils avaient enfermé dans des latrines, qui voulait aussi de la soie pour des raisons qu'il taisait",
    [4450] = "ai rassemblé les marchandises du registre de Krinkle Goodsteel et les lui ai portées à [[Gadgetzan]], un travail que le prisonnier des latrines avait laissé inachevé",
    [4451] = "ai trouvé la clé des latrines de Grimesilt et l'ai tournée pour libérer le vieux Locheed des latrines où l'avaient enfermé les Sombrefer",
    [4491] = "ai ramené Ringo, terrassé par la chaleur sur [[Fire Plume Ridge]], auprès de son ami Spraggle Frock",
    [4492] = "ai cherché Ringo sur [[Fire Plume Ridge]], un ami pour qui Spraggle Frock s'inquiétait depuis qu'il était parti explorer le volcan",
    [4496] = "ai rassemblé une glande olfactive gorishi et de l'humus de [[Un'Goro Crater]] pour le leurre de Pestlezugg, destiné à faire sortir la reine de la ruche silithide",
    [4501] = "ai décimé les pterreurdactyles qui menaçaient les voyageurs du cratère, pour que Spraggle Frock, terrifié, ose quitter le camp",
    [4502] = "ai recueilli les cendres des élémentaires de feu du volcan pour Liv Rizzlefix à [[Ratchet]], qui étudiait l'activité volcanique du cratère",
    [4503] = "ai rassemblé des écailles étoilées de pterreurdactyles et de dimeurtrodons pour les ailes de la machine volante de Shizzle, son moyen de rentrer chez lui",
    [4504] = "ai récolté du goudron sur les bêtes des fosses de goudron de [[Un'Goro Crater]] pour la dernière combine de Tran'rek, pour gagner vite un peu d'or",
    [4507] = "ai attiré la reine de la ruche gorishi et l'ai tuée, puis j'ai apporté son cerveau à Pestlezugg pour qu'il étudie les silithides",
    [4508] = "ai porté le rapport de Pestlezugg sur [[Un'Goro Crater]] à Gracina Spiritmight, dans l'espoir que les chefs de l'Alliance prennent garde à la menace silithide",
    [4509] = "ai porté le rapport de Pestlezugg sur [[Un'Goro Crater]] à Zilzibin Drumlore, dans l'espoir que les chefs de la Horde prennent garde à la menace silithide",
    [4542] = "ai porté un avertissement urgent de nouvelles attaques centaures au garde-falaise Longhorn à [[Freewind Post]]",
    [4581] = "ai porté le rapport de Shindrell au druide [[name:Kayneth Stillwind]], qui craignait une corruption gagnant [[Ashenvale]]",
    [4621] = "ai tué l'amiral Seahorn et le baron Revilgaz de [[Booty Bay]], pour que la Voile sanglante navigue librement, et suis $gdevenu:devenue; leur amiral",
    [4642] = "ai lâché un limon de [[Felwood]] près d'un limon primordial de [[Un'Goro Crater]] pour le chimiste Fuely, et rapporté ce qui restait de la rencontre",
    [4681] = "ai plongé jusqu'à un squelette de tortue de mer à l'ouest de [[Auberdine]], une vraie chance de comprendre pourquoi les créatures marines s'échouent",
    [4701] = "ai détruit Halycon, la bête corrompue à l'origine des worgs des orcs Blackrock, dont le nombre ne diminuait jamais",
    [4722] = "ai prélevé des échantillons sur une tortue de mer échouée depuis longtemps, dépecée par les murlocs campant autour, pour [[Temple of the Moon]]",
    [4723] = "ai pris les os d'un batteur géant échoué sur [[Mist's Edge]], bien trop grand pour que les murlocs qui s'en repaissaient l'aient tué",
    [4724] = "ai tué Halycon, la gigantesque mère de la tanière des worgs Bloodaxe, et survécu à son compagnon Gizrul l'Asservisseur",
    [4725] = "ai trouvé une boîte aux marques étranges sur la carapace d'une tortue échouée, un travail de nagas qui expliquait leur présence [[at:Darkshore]]",
    [4726] = "ai capturé de l'essence de rejeton avec le Draco-Incarcinatrix 900 de [[name:Tinkee Steamboil]], pour son étude des dragonnets",
    [4727] = "ai prélevé un échantillon sur une carcasse de tortue des plages du nord dont même les murlocs Grisebrume semblaient se tenir à l'écart",
    [4728] = "ai recueilli un échantillon sur une créature marine échouée que la Ligue des explorateurs étudiait jusqu'à ce que des murlocs la chassent",
    [4729] = "ai capturé un jeune worg Bloodaxe à [[Blackrock Spire]] pour [[name:Kibler]], qui dressait des bêtes exotiques pour en faire les familiers des riches",
    [4730] = "ai prélevé des os sur une créature marine à moitié dévorée gardée par des murlocs plus forts, pour l'étude de Gwennyth sur les échouages",
    [4731] = "ai porté à Gwennyth une autre boîte naga trouvée sur la carapace d'une tortue échouée, qui se demandait si elle avait été destinée à [[Ashenvale]]",
    [4732] = "ai récupéré ce que les murlocs Grisebrume avaient laissé d'une tortue de mer échouée, pour que [[Temple of the Moon]] l'étudie",
    [4733] = "ai rapporté les os d'un batteur plusieurs fois plus grand que tous ceux de la région, échoué sur [[Twilight Shore]]",
    [4734] = "ai essayé l'œufilloscope de [[name:Tinkee Steamboil]] sur un œuf de dragon noir dans la Colonie, tout en haut de [[Blackrock Spire]]",
    [4735] = "ai gelé et rassemblé des œufs de dragon noir dans la Colonie pour [[name:Tinkee Steamboil]] et son commanditaire",
    [4740] = "ai tué [[name:Murkdeep]], le murloc accusé de la mort d'une sentinelle et du naufrage de deux cargos, pour que [[Auberdine]] puisse dormir tranquille",
    [4742] = "ai pris les trois gemmes de commandement aux généraux du bas du pic, pour orner le sceau d'ascension de [[name:Vaelan]]",
    [4743] = "ai brisé la volonté de l'ancien drake Brandeguerre dans [[Wyrmbog]] et l'ai forcé à cracher sa flamme sur le sceau d'ascension",
    [4762] = "ai prélevé de l'eau de [[Cliffspring River]] souillée pour Thundris Windweaver, qui craignait que sa corruption n'atteigne [[Auberdine]]",
    [4763] = "ai attiré le corrupteur satyre avec une coupe de purification pour son talisman de corruption, qui pourrait un jour libérer les furbolgs",
    [4764] = "ai trouvé le fermoir de Doomrigger, une relique naine incrustée de gemmes, dans la salle de la Fortune en ruine, pour le commanditaire de [[name:Mayara Brightwing]]",
    [4765] = "ai livré le fermoir de Doomrigger dans sa caisse au comte Remington Ridgewell à [[Stormwind City]], pour le musée de sa famille",
    [4767] = "ai ramassé des œufs de wyverne à [[Highperch]] pour [[name:Elu]], qui avait besoin de plus de wyvernes pour les chevaucheurs du vent et espérait en devenir un",
    [4768] = "ai récupéré la tablette de Darkstone, les recherches de l'alchimiste fou Urheld Darkstone, à [[Blackrock Spire]] pour Vivian Lagrave",
    [4770] = "ai escorté [[name:Pao'ka Swiftmountain]], perdu depuis des jours pour s'être trop approché des nids de wyvernes, de [[Highperch]] à [[Whitereach Post]]",
    [4771] = "ai planté le Gambit de l'aube dans la salle d'observation de [[Scholomance]] et vaincu le mage mort-vivant Vectus et ses étudiants du Fléau",
    [4787] = "ai récupéré l'œuf ancien dans une grotte tout en haut de [[Jintha'Alor]] pour Yeh'kinya, la relique qui pourrait selon lui contenir l'essence d'Hakkar",
    [4788] = "ai pris les dernières tablettes Mosh'aru aux trolls Smolderthorn du pic pour le prospecteur Ironboot, qui craignait ce qui s'annonçait",
    [4808] = "ai porté la lettre de Tinkee à Felnok Steelspring à [[Everlook]], qui demandait des pièces pour congeler des œufs de dragonnets",
    [4811] = "ai fouillé les montagnes de l'est à la recherche du cristal rouge qui, disait-on, attirait des séléniens hostiles, pour la sentinelle Glynda Nal'Shea",
    [4812] = "ai versé de l'eau du puits de lune sur le cristal rouge, qui est devenu clair et a laissé voir des fragments d'os et une demi-mâchoire à l'intérieur",
    [4821] = "ai pris l'œuf étrange d'un repaire de serpents pour [[name:Hagar Lightninghoof]], qui voulait savoir ce que les serpents gardaient de si près",
    [4841] = "ai attaqué le camp des centaures galaks au nord de [[Freewind Post]] pour venger la caravane qu'ils avaient massacrée",
    [4862] = "ai rassemblé des œufs d'araignée du pic pour [[name:Kibler]], qui avait envoyé Bijou les chercher et n'avait plus de nouvelles d'elle depuis des semaines",
    [4865] = "ai annoncé à [[name:Motega Firemane]] que la légende d'Arikara était vraie, et que la vengeance était venue à [[Thousand Needles]]",
    [4866] = "me suis laissé empoisonner exprès par la mère Ignitoile, pour que John le Loqueteux puisse traire le venin pour sa bière",
    [4867] = "ai récupéré le mojo de Warosh à [[Blackrock Spire]], pour lever la malédiction qu'Urok avait jetée sur son esprit",
    [4881] = "ai prévenu [[name:Kanati Greycloud]] du complot centaure pour le tuer, lui qui avait osé installer un camp de chasse",
    [4903] = "ai tué le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak et saisi leurs documents pour le seigneur de guerre Goretooth",
    [4904] = "ai escorté [[name:Lakota Windsong]] hors de [[Darkcloud Pinnacle]], où Arnak l'avait emmenée après avoir tué son frère, et l'ai ramenée à Thalia",
    [4921] = "ai cherché dans [[Barrens]] une trace de la femme de Mankrik, perdue quand les Dos-hirsute avaient submergé leur camp",
    [4966] = "ai tenu bon aux côtés de [[name:Kanati Greycloud]] contre les assassins centaures envoyés pour le tuer",
    [4971] = "ai délogé les parasites temporels des silos d'Andorhal pour que Chromie répare le cours du temps, que le Fléau avait altéré selon elle",
    [4972] = "ai fouillé les décombres d'Andorhal à la recherche des montres enfermées dans des coffrets depuis la peste, dont Chromie avait besoin pour réparer le temps de la ville",
    [4973] = "ai trouvé d'autres montres d'Andorhal pour Chromie, pour l'aider à repousser ce qui se mêlait du cours du temps de la ville",
    [4974] = "ai porté la tête du chef de guerre Rend Blackhand à Thrall à [[Orgrimmar]], un coup terrible pour les orcs Blackrock",
    [4981] = "ai retrouvé Bijou à [[Blackrock Spire]], une agente gobeline qui avait dépensé l'argent de la Horde en travaillant pour [[name:Kibler]]",
    [4982] = "ai récupéré le matériel de reconnaissance que Bijou avait caché dans le pic après avoir déclenché une alarme, le prix de son retour",
    [4983] = "ai porté le rapport de reconnaissance de Bijou au grand maître Lexlort à [[Kargath]], un avantage sur les orcs Blackrock",
    [4984] = "ai mis fin aux souffrances des loups malades pour Mulgris Deepriver, un druide tauren venu soigner les ravages de la peste",
    [4985] = "ai mis fin au tourment des grizzlys malades près de la frontière est, la dernière chose que m'a demandée Mulgris Deepriver avant de mourir",
    [4986] = "ai porté la branche de chêne glyphée de Mulgris Deepriver au Cercle cénarien à [[Darnassus]], avec tout ce qu'il savait de la peste",
    [4987] = "ai apporté la branche de chêne glyphée de Mulgris Deepriver au Cercle cénarien à [[Thunder Bluff]], avec tout ce qu'il avait appris de la peste",
    [5001] = "ai récupéré les affaires de la gobeline Bijou à [[Blackrock Spire]] en échange de ce qu'elle avait appris de la menace Blackrock",
    [5002] = "ai apporté la carte de Bijou au maréchal Maxwell, qui marquait où les lieutenants de Nefarian tenaient le bas de la citadelle",
    [5021] = "ai fouillé la grange des Felstone à la recherche du colis qu'un fantôme effrayé suppliait encore qu'on livre, avec quatre ans de retard",
    [5022] = "ai demandé au recensement de [[Stormwind City]] où trouver Emma Felstone, la destinataire du colis du fantôme, envoyé plus de quatre ans plus tôt",
    [5023] = "ai retrouvé Jeremiah Felstone grâce au recensement de [[Undercity]], pour que le colis du fantôme, en retard depuis si longtemps, lui parvienne",
    [5041] = "ai récupéré les caisses de ravitaillement prises par les Tranchecrin lors de leur raid, des vivres dont [[Crossroads]] avait cruellement besoin",
    [5047] = "ai porté un morceau de chair luisante, arraché par Finkle Einhorn aux entrailles de la Bête, à [[name:Malyfous Darkhammer]] à [[Everlook]]",
    [5048] = "suis $gallé:allée; trouver la vieille Emma, la femme qui marmonnait dans les rues de [[Stormwind City]], qui était bien Emma Felstone, avec un colis de sa sœur Janice",
    [5049] = "ai retrouvé Jeremiah Payson, le marchand de cafards de [[Undercity]], pour lui remettre un colis de sa sœur morte depuis longtemps, Janice Felstone",
    [5050] = "ai rendu la moitié d'un charme porte-bonheur au fantôme de Janice Felstone, dans l'espoir que les affaires de sa sœur lui permettraient de reposer",
    [5051] = "ai reconstitué le charme porte-bonheur des Felstone avec sa moitié perdue, ce qui a enfin libéré le fantôme de Janice Felstone",
    [5052] = "ai apporté à Mangletooth un joyau de sang Dos-hirsute, pour montrer que je comprenais la magie d'Agamaggan et gagner ses bénédictions",
    [5058] = "ai lu la dernière page du journal de Mme Dalson, écrite après que son mari Harold s'était transformé et qu'elle l'avait enfermé",
    [5059] = "ai ouvert les toilettes des Dalson avec la clé du squelette de Mme Dalson, et affronté la goule qu'était devenu son mari",
    [5060] = "ai ouvert le cabinet des Dalson avec la clé tirée des restes de goule du fermier, où les derniers biens de la famille étaient restés intacts",
    [5062] = "ai récolté de l'agave d'incendia pour [[name:Magatha Grimtotem]], qui l'enchanterait en une poudre capable d'invoquer Arikara",
    [5064] = "ai volé trois notes secrètes à [[Darkcloud Pinnacle]], pour savoir ce que les Totem-sinistre complotaient avec des agents inconnus",
    [5065] = "ai arraché les troisième et quatrième tablettes Mosh'aru aux trolls écorcheurs de mousse pour le prospecteur Ironboot, qui craignait leurs secrets",
    [5081] = "ai détruit le maître de guerre Voone, le généralissime Omokk et le seigneur Wyrmthalak pour plonger le commandement Blackrock dans le chaos",
    [5088] = "ai invoqué Arikara au feu sacré de la vie et l'ai tuée, une créature qui traquait Cairne Bloodhoof selon les craintes de Magatha",
    [5089] = "ai apporté au maréchal Maxwell une lettre du général Drakkisath, trouvée sur le cadavre d'un serpent abattu",
    [5092] = "ai décimé les morts-vivants de la colline des Chagrins pour que le commandant Ashlam Valorfist puisse frapper Andorhal par sa route est, moins bien gardée",
    [5096] = "ai brûlé la tente de commandement de la Croisade écarlate et y ai laissé une bannière du Fléau, pour que la Croisade s'en venge sur le Fléau",
    [5097] = "ai marqué les quatre tours de guet d'Andorhal avec une torche de signal, des cibles pour les troupes du commandant Ashlam Valorfist",
    [5098] = "ai planté des signaux aux quatre tours de guet d'Andorhal pour le grand exécuteur Derrington, pour préparer l'attaque de la Horde sur la ville",
    [5102] = "ai détruit le général Drakkisath à [[Blackrock Spire]] pour le maréchal Maxwell, qui portait le combat jusqu'au seuil des dragons noirs",
    [5103] = "ai arraché des gantelets en plaques jamais cuits près des os calcinés d'un mort, puis suis $gsorti:sortie; du feu pour trouver qui savait s'en servir",
    [5122] = "ai repris le médaillon de foi pour qu'Aurius puisse quitter la chapelle et partir à la poursuite du baron Rivendare, qui avait aidé à le corrompre",
    [5125] = "ai accompagné Aurius jusqu'au bout de son jugement à [[Stratholme]], qui a laissé le paladin mourant mais son âme sauvée",
    [5127] = "ai tué Goraluk Anvilcrack et lui ai planté dans le cœur la pique gangrenée de Lorax, pour reprendre l'âme qu'il avait vendue",
    [5141] = "me suis $gengagé:engagée; pour de bon dans le travail du cuir de dragon, avec de l'armure de scorpide et des écailles de dragon pour Peter Galen [[at:Azshara]]",
    [5142] = "ai fouillé les ruines de [[Darrowshire]] à la recherche de la petite Pamela, la nièce qu'un esprit errant y avait cachée au début de la bataille",
    [5143] = "ai choisi pour de bon le travail du cuir tribal, en offrant à Caryssia Moonhunter, [[at:Feralas]], les plus belles pièces d'armure en cuir sauvage",
    [5144] = "me suis $gengagé:engagée; dans le travail du cuir élémentaire, en apportant à Sarah Tanner, dans [[Searing Gorge]], des essences de feu, d'eau, de terre et de vent",
    [5145] = "ai choisi pour de bon la voie du cuir de dragon, en le prouvant à Thorkaf Dragoneye dans [[Badlands]] avec de l'armure de scorpide et des écailles de dragon",
    [5146] = "me suis $gvoué:vouée; au seul travail du cuir élémentaire, avec les essences des quatre éléments pour Brumn Winterhoof dans les montagnes d'Arathi",
    [5147] = "ai livré à la justice Arnak Grimtotem, le paria recherché pour meurtre et enlèvement, pour le garde-falaise Longhorn",
    [5148] = "ai adopté pour de bon le travail du cuir tribal, en apportant à Se'Jib, dans [[Stranglethorn Vale]], les plus beaux exemples d'armure en cuir sauvage",
    [5149] = "ai trouvé la poupée que la petite Pamela avait laissée en ville, quelque chose à serrer pendant qu'elle attendait seule que son père vienne la chercher",
    [5151] = "ai tué la panthère en cage qui portait l'hypercapaciteur de [[name:Wizlo Bearingshiner]], le seul survivant d'un raid centaure contre une caravane",
    [5152] = "ai porté des nouvelles de Pamela à sa tante Marlene, qui n'avait pas le cœur de dire à l'enfant ce qu'il était advenu de son père",
    [5153] = "ai déterré l'alliance de Joseph Redpath pour Chromie, dans l'espoir de changer le sort d'un homme que le Fléau avait perverti",
    [5154] = "ai récupéré les Annales de Darrowshire à l'hôtel de ville d'Andorhal, dans l'espoir qu'elles montreraient à Chromie comment sauver Joseph Redpath",
    [5160] = "ai porté l'écaille d'Awbee à [[name:Haleh]] dans [[Winterspring]], pour que la matrone protectorat devine ce qu'Awbee avait senti dans le pic",
    [5166] = "ai rassemblé une carapace chromatique, des écailles et du sang de héros pour le plastron de Jeziba la Sculptrice contre le vol chromatique",
    [5167] = "ai fourni à Jeziba la Sculptrice des écailles chromatiques, du sang de héros et des peaux d'ombre pour des jambières contre le vol chromatique",
    [5168] = "ai rassemblé le libram de Davil Lightfire et le bouclier fendu du capitaine Redpath pour Carlin Redpath, reliques des héros de [[Darrowshire]]",
    [5181] = "ai récupéré le crâne d'Horgus le Ravageur et l'épée brisée de Marduk le Noir, les scélérats de la bataille de [[Darrowshire]]",
    [5206] = "ai chassé des champions du Fléau pour des crânes qui faisaient résonner le cristal de Carlin Redpath, le dernier composant du sort de Chromie",
    [5210] = "ai apporté à Carlin Redpath les Annales de Darrowshire, dont les nouvelles pages racontaient les jours qui avaient suivi la bataille",
    [5211] = "ai libéré les âmes des défenseurs tombés de [[Darrowshire]] en détruisant les goules et les écorcheurs que le Fléau avait faits d'eux",
    [5212] = "ai rassemblé de la chair pestiférée à [[Stratholme]] pour Betina Bigglezink, qui craignait que la peste ne devienne plus forte",
    [5213] = "ai fouillé les ziggourats de [[Stratholme]] à la recherche de données du Fléau, pour savoir ce qui avait changé dans les agents actifs de la peste",
    [5214] = "ai fouillé les ruines de la boutique de tabac de Fras Siabi à la recherche d'une boîte rescapée de son célèbre tabac, pour Smokey LaRue",
    [5216] = "ai tué le seigneur du chaudron Bilemaw au champ de Felstone pour la clé de son chaudron, et prélevé son poison pour un contre-agent",
    [5218] = "ai versé des composants dans le chaudron du champ de Felstone jusqu'à ce que le Fléau alentour recule devant le nuage qu'il crachait",
    [5219] = "ai tué le seigneur du chaudron des Larmes de Dalson et mis ses ichors en bouteille pour que la grande prêtresse MacDonnell les retourne contre le Fléau",
    [5221] = "ai versé le contre-agent dans le chaudron des Larmes de Dalson jusqu'à ce que le Fléau alentour recule devant ses propres vapeurs",
    [5222] = "ai ouvert le chaudron du Repaire putride avec la clé de son seigneur et mis son breuvage en bouteille, une troisième occasion de retourner les poisons du Fléau",
    [5224] = "ai nourri le chaudron du Repaire putride des composants qui changeaient son poison, pour que le nuage qu'il crachait agisse contre le Fléau",
    [5225] = "ai affronté les âmes en peine et les fantômes de la Flétrissure de Gahrron pour tuer le seigneur du chaudron Âmecourroux et prélever le dernier chaudron de l'ouest",
    [5227] = "ai ajouté le contre-agent au chaudron de la Flétrissure de Gahrron, retournant la peste du Fléau contre ceux qui l'avaient faite",
    [5229] = "ai vaincu le seigneur du chaudron Bilemaw au champ de Felstone et prélevé le poison de son chaudron pour que l'apothicaire Dithers l'étudie",
    [5231] = "ai abattu le seigneur du chaudron des Larmes de Dalson et mis en bouteille le breuvage de toxines de ce chaudron pour la prêtresse des ombres Vandis",
    [5233] = "ai pris la clé du seigneur du chaudron du Repaire putride et mis en bouteille la peste qu'il brassait, pour le contre-agent des Réprouvés",
    [5235] = "ai bravé les âmes en peine de la Flétrissure de Gahrron pour tuer le seigneur du chaudron Âmecourroux et mettre en bouteille le breuvage du dernier chaudron de l'ouest",
    [5241] = "ai cherché l'oncle Carlin de Pamela pour lui dire qu'elle l'attendait, lui et son histoire de lapins et de confiture de baies",
    [5243] = "ai récupéré l'eau bénite de l'Aube d'argent dans les caisses de ravitaillement de [[Stratholme]] pour Leonid Barthalomew le Révéré",
    [5246] = "ai récupéré les textes sacrés des Bien-nés [[at:Azshara]], pour qu'Aurora Skycaller puisse réparer le cristal de Zin-Malor",
    [5247] = "suis $gallé:allée; chercher du thorium, du cristal de restauration et de l'eau redoutable à [[Dire Maul]], pour qu'Aurora Skycaller puisse ressouder le cristal",
    [5248] = "ai porté le cristal de Zin-Malor réparé à [[Lake Kel'Theril]], pour montrer à un esprit bien-né que l'ancien tort était réparé",
    [5251] = "ai détruit l'archiviste Galford et brûlé les archives écarlates de [[Stratholme]], des années de renseignements de la Croisade perdues",
    [5262] = "ai apporté la tête de Balnazzar, le seigneur de l'effroi qui se faisait passer pour le Grand croisé, au duc Nicholas Zverenhoff pour preuve",
    [5263] = "ai détruit le baron Rivendare, le larbin de Kel'Thuzad qui régnait sur [[Stratholme]], et apporté sa tête au duc Nicholas Zverenhoff",
    [5265] = "ai ouvert le Fort d'argent, fermé depuis des années, après de longs services rendus à l'Aube d'argent",
    [5281] = "suis $gallé:allée; trouver Egan, dont le travail avec les fantômes pourrait aider les esprits sans repos de ceux qui étaient morts dans la chute de [[Stratholme]]",
    [5282] = "ai libéré les âmes sans repos des citoyens fantômes de [[Stratholme]] avec le pistolet d'Egan, dans l'espoir que sa mère soit parmi eux",
    [5283] = "ai forgé des heaumes, des bottes et un plastron ornés en mithril pour Grumnus, le talent brut qu'il exigeait avant de faire de quelqu'un un fabricant d'armures",
    [5284] = "ai fait des épées larges en acier lunaire, des haches en fer et en mithril et des masses noires pour Ironus, l'épreuve avant la voie du fabricant d'armes",
    [5301] = "ai forgé des heaumes, des bottes et un plastron ornés en mithril pour Okothos, sa tâche avant de prendre un forgeron sur la voie du fabricant d'armures",
    [5302] = "ai fait des épées larges, des haches et des masses pour Borgosh, qui rêvait d'un marteau de chef de guerre, l'épreuve pour devenir fabricant d'armes",
    [5305] = "ai tué le forgeron de marteaux cramoisi à [[Stratholme]] pour son tablier, le prix du secret du marteau de bataille enchanté de Lilith",
    [5306] = "ai tué la chasseresse des ombres Vosh'gajin à [[Blackrock Spire]], la vengeance de Kilram pour sa cicatrice, pour le secret du Fil de l'aube",
    [5307] = "ai détruit le forgeur d'épées de la Garde noire à [[Stratholme]], qui gardait les plans volés de la grande lame Corruption",
    [5321] = "ai guidé le somnolent Kerlonian Evershade, tout juste sorti du Rêve d'émeraude, jusqu'à Liladris Moonriver à [[Maestra's Post]]",
    [5341] = "ai récupéré les quatre titres de propriété des Barov dans [[Scholomance]] pour Alexi Barov, avant que son frère vivant Weldon ne puisse les réclamer",
    [5342] = "ai assassiné Weldon Barov à [[Chillwind Camp]] pour que son frère Alexi détienne seul le pouvoir et la fortune de la maison Barov",
    [5343] = "ai récupéré les titres de propriété des Barov dans [[Scholomance]] pour Weldon Barov, avant que son frère mort-vivant Alexi ne mette la main dessus",
    [5344] = "ai pris la tête d'Alexi Barov sous la protection de la Horde, à [[The Bulwark]], pour que la fortune de Weldon soit assurée",
    [5361] = "ai porté le rapport du garde-falaise Longhorn sur une activité centaure inhabituelle à son frère Nataka, à [[Ghost Walker Post]] [[at:Desolace]]",
    [5381] = "ai pris la boîte démoniaque à la Lame ardente, qui renfermait la Main d'Iruxos dont ils se servaient pour ouvrir des portails à [[Mannoroc Coven]]",
    [5382] = "ai détruit le docteur Theolen Krastinov, le Boucher de milliers d'innocents, et brûlé les restes d'Eva et de Lucien Sarkhoff",
    [5384] = "ai attiré Kirtonos le Héraut avec le sang d'innocents et l'ai détruit, le maître que Krastinov avait servi",
    [5386] = "suis $gallé:allée; chercher des ventres-rouges à [[Shadowprey Village]] pour Nataka Longhorn, à qui l'odeur du poisson cuit manquait depuis longtemps",
    [5461] = "ai fouillé les ruines de [[Stromgarde Keep]] à la recherche d'un souvenir de la vie de Ras Murmegivre, pour que le magistrat Marduke le rende de nouveau mortel",
    [5463] = "ai déposé le livre du souvenir sur le Don de Menethil, le sol impie de [[Stratholme]] où Ras Murmegivre était devenu une liche",
    [5464] = "ai porté le souvenir lié à Leonid Barthalomew, pour qu'une âme s'accroche à Ras Frostwhisper comme elle s'était accrochée au souvenir",
    [5466] = "ai rendu mortelle la liche Ras Murmegivre grâce au souvenir lié avant de l'abattre, un coup mortel pour le Fléau",
    [5481] = "ai cueilli de l'herbe des ténèbres pour Gordo aux grandes mains, pour apprendre que son maître, l'apothicaire subalterne Holland, n'en avait pas besoin",
    [5482] = "ai ramassé de l'herbe maléfique près du charnier pour l'apothicaire subalterne Holland, l'herbe que son serviteur Gordo se trompait toujours à cueillir",
    [5501] = "ai ramassé des os de kodo à [[Kodo Graveyard]] pour Bibbly F'utzbuckle, dont les clients en faisaient des meubles et de la poudre explosive",
    [5515] = "ai abattu Jandice Barov dans les catacombes pour le sac des horreurs de Krastinov, le moyen d'invoquer son maître Kirtonos",
    [5518] = "ai apporté de l'étoffe, du cuir et du fil au gobelin enchaîné [[name:Knot Thimblejack]] pour un costume d'ogre qui me ferait passer devant le capitaine Kromcrush",
    [5522] = "ai remis les œufs de dragon congelés de Tinkee à Leonid Barthalomew, qui l'avait dupée pour qu'ils n'atteignent jamais son maître malfaisant",
    [5525] = "ai libéré [[name:Knot Thimblejack]], un gobelin enchaîné dans l'aile Gordok qui s'attendait à finir en amuse-gueule d'ogre",
    [5526] = "ai mis fin à la corruption d'Alzzin le Modeleur à [[Dire Maul]] et scellé un éclat de la gangrevigne dans le reliquaire de pureté",
    [5527] = "ai fouillé les ruines de [[Southwind Village]] [[at:Silithus]] à la recherche d'un reliquaire de pureté, le seul réceptacle capable de contenir la gangrevigne",
    [5529] = "ai tué les jeunes dragons pestiférés élevés dans [[Scholomance]], avant que le Fléau ne lève un vol de dragons bien à lui",
    [5531] = "ai apporté les œufs de dragon congelés, soustraits aux expériences du Fléau, à Betina Bigglezink et à son arme contre eux",
    [5534] = "ai arraché aux nagas d'Eldarath la rune que cherchaient les elfes de sang, la vengeance de Kim'jael sur les employeurs qui l'avaient trahi",
    [5535] = "ai libéré les esprits bien-nés sans repos du sanctuaire de Chantelombre, comme Loh'atu l'avait promis aux sentinelles",
    [5536] = "ai purgé des satyres Haldarr les terres sacrées autrefois parcourues par Cénarius, pour tenir le serment de Loh'atu envers la Terre-Mère",
    [5537] = "ai rassemblé des fragments de squelette autour d'Andorhal pour l'alchimiste Arbington, le début d'une clé squelette pour ouvrir [[Scholomance]]",
    [5541] = "ai récupéré une caisse de munitions abandonnée par un coursier près de [[Grizzled Den]] et l'ai portée à Hegnar Rumbleshot",
    [5542] = "ai décimé les chiens pestiférés et leurs petits pour Tirion Fordring",
    [5543] = "ai détruit les chauves-souris pestiférées qui frappaient du haut du ciel des Maleterres, à la demande de Tirion Fordring",
    [5544] = "ai récolté de la chair de ver putride, la seule bête que la peste avait épargnée, pour que Tirion Fordring refasse ses provisions pour l'hiver",
    [5561] = "ai secoué de vieux kodos jusqu'à les rendre dociles avec le kombobulateur de Smeed Scrabblescrew, pour la caravane dont il était l'associé",
    [5581] = "ai banni les portails démoniaques de [[Mannoroc Coven]] avec la Main d'Iruxos, pour endiguer le flot de démons dans le monde",
    [5582] = "ai pris une rare écaille saine sur un jeune dragon pestiféré pour Betina Bigglezink, pour étudier les machinations du Fléau",
    [5601] = "ai fouillé [[Darrowshire]] à la recherche de la famille qu'une réfugiée de Lordaeron avait laissée derrière elle, surtout sa petite sœur Pamela",
    [5713] = "ai défendu la sentinelle Aynasha, empoisonnée, contre le furbolg Marosh et ses pisteurs jusqu'à ce que son antidote fasse effet",
    [5721] = "ai revécu la bataille de [[Darrowshire]] avec ses esprits relevés, pour vaincre Redpath le Corrompu et sauver l'âme de Joseph Redpath",
    [5722] = "ai fouillé [[Ragefire Chasm]] à la recherche du corps de Maur Grimtotem, le serviteur de Magatha, et de ce qu'il avait trouvé avant de mourir",
    [5724] = "ai apporté à Rahauro à [[Thunder Bluff]] la sacoche que Maur Grimtotem serrait encore quand les troggs l'avaient abattu",
    [5725] = "ai pris deux livres de sorts d'ombre à la Lame brûlante pour Varimathras, des cadeaux de la Légion que la Dame noire voulait avoir en main",
    [5728] = "ai tué Bazzalan et Jergosh l'Invocateur, chefs de la Lame brûlante sous [[Orgrimmar]], pour Thrall, à l'insu de Neeru Fireblade",
    [5741] = "ai arraché le sceptre de lumière à un voyant de la Lame ardente dans [[Thunder Axe Fortress]], une relique qui, disait-on, pouvait engloutir des villes entières",
    [5761] = "ai tué Taragaman l'Affameur, le gangregarde qui menait la Lame brûlante dans [[Ragefire Chasm]], pour Neeru Fireblade",
    [5762] = "ai livré la caisse de munitions spéciales de Kravel au camp de chasse de [[name:Hemet Nesingwary]] [[at:Stranglethorn Vale]]",
    [5763] = "ai porté la corne de kodo de Roon Wildmane à [[name:Hemet Nesingwary]] [[at:Stranglethorn Vale]], une invitation à chasser de nouveau ensemble",
    [5781] = "ai retrouvé le marteau jouet que le jeune Taelan avait enterré sur la fausse tombe de son père, pour l'aider à retrouver ce qu'il avait perdu",
    [5801] = "ai forgé une clé squelette dans le lac de lave au sommet de [[Fire Plume Ridge]] pour l'alchimiste Arbington, un pas de plus vers Araj l'Invocateur",
    [5802] = "ai forgé une clé squelette dans le lac de lave au sommet de [[Fire Plume Ridge]] pour l'apothicaire Dithers, un pas de plus vers Araj l'Invocateur",
    [5803] = "ai détruit Araj l'Invocateur, autrefois maître de [[Scholomance]], et arraché le scarabée de son phylactère pour couronner la clé squelette",
    [5804] = "ai brisé l'emprise d'Araj l'Invocateur sur Andorhal et pris son scarabée, la dernière pièce de la clé de [[Scholomance]] de l'apothicaire Dithers",
    [5821] = "ai protégé la caravane de Gizelton au passage du village kolkar, dont les tambours de guerre arrêtaient d'ordinaire ses kodos",
    [5845] = "ai rapporté le symbole de l'honneur perdu, l'étendard que Taelan avait jeté à Northdale en reniant tout ce qu'il avait connu",
    [5846] = "ai fouillé [[Caer Darrow]] à la recherche du portrait de Tirion Fordring avec sa femme et son fils peint par Renfray, son plus cher souvenir",
    [5848] = "ai découvert le tableau De l'amour et de la famille sous une peinture des lunes jumelles du bastion Écarlate, pour Tirion Fordring",
    [5862] = "me suis $gglissé:glissée; à [[Hearthglen]] sous l'illusion de Myranda pour remettre le Don de Tirion entre les mains de son fils, le généralissime Taelan Fordring",
    [5863] = "ai brisé le camp Cognedune et tué Gor'marok le Ravageur avant que les ogres ne puissent rassembler une armée [[at:Tanaris]]",
    [5881] = "ai annoncé à [[name:Grish Longrunner]], au Grand élévateur, qu'on venait le relever, pour qu'il puisse enfin rendre visite à sa famille",
    [5901] = "ai rempli un pot de termites de [[Plaguewood]] pour Mickey Levine, qui comptait prendre une scierie à la Croisade écarlate",
    [5902] = "ai lâché un tonneau de termites dans la scierie de Nordcrête, pour priver la Croisade écarlate de son précieux bois",
    [5903] = "ai rempli un pot de termites des Maleterres près de [[Stratholme]] pour que Nathaniel Dumah les lâche sur la scierie de la Croisade écarlate",
    [5904] = "ai placé un tonneau de termites au cœur de la scierie de Nordcrête, pour la rendre inutile à la Croisade écarlate",
    [5929] = "suis $gallé:allée; trouver l'esprit du Grand ours à [[Moonglade]], comme tout druide le doit, pour apprendre de lui la vraie nature de l'ours",
    [5930] = "me suis $gassis:assise; aux pieds de l'esprit du Grand ours à [[Moonglade]], le premier maître de tout druide dans la nature de l'ours",
    [5941] = "ai porté la liasse de reliques à Chromie à Andorhal, qui disait qu'avec elles [[Darrowshire]] pouvait encore être sauvé",
    [5942] = "ai ouvert le coffre derrière la maison de Pamela avec la clé que son père m'avait envoyée avec ses remerciements",
    [5943] = "ai protégé la caravane de Gizelton à travers [[Mannoroc Coven]], où quelque chose effrayait les kodos",
    [5944] = "ai escorté le généralissime Taelan Fordring hors de [[Hearthglen]] jusqu'à son père Tirion, une fuite qui a coûté la vie à Taelan",
    [6001] = "ai appelé Lunegriffe à la pierre des séléniens près de [[Auberdine]] et l'ai affronté, pour la force de corps et de cœur qu'il faut à un druide",
    [6002] = "ai affronté Lunegriffe à la pierre des séléniens à l'ouest de Taurajo, pour la force de corps et de cœur que doit avoir l'un de ceux de la Griffe",
    [6004] = "ai décimé le camp de la Croisade écarlate sous [[Hearthglen]] pour Kirsta Deepshadow, une éclaireuse trop épuisée pour continuer à se battre seule",
    [6021] = "ai tué Zaeldarr le Paria, le troll mort dont la bande volait les corps de la fosse de [[Light's Hope Chapel]]",
    [6022] = "ai massacré le Fléau de [[Corin's Crossing]] pour de la pourriture vivante, broyée assez vite pour nourrir les chiens de Nathanos le Flétrisseur",
    [6023] = "ai tué le veneur Radley et le cavalier Durgen, les piliers de la Croisade écarlate aux portes de [[Hearthglen]], pour Kirsta Deepshadow",
    [6024] = "ai accédé à la supplique de l'infiltrateur Hameya, qui voulait mourir avant que les murmures de la liche ne le poussent à infecter davantage des siens",
    [6025] = "suis $gmonté:montée; sur un point élevé de [[Hearthglen]] pour estimer le nombre des croisés écarlates pour Kirsta Deepshadow, trop épuisée pour y aller elle-même",
    [6026] = "ai rassemblé du thorium, un bâtonnet doré, des bombes et des déclencheurs pour Smokey LaRue, engagé par l'Aube d'argent pour quelques démolitions",
    [6027] = "ai invoqué le gardien du livre des Anciens sur [[Ranazjar Isle]], et rapporté les secrets des nagas à Azore Aldamort",
    [6041] = "ai fait sauter les ziggourats et les abattoirs du Fléau de [[Plaguewood]] que Smokey LaRue avait marqués pour l'Aube d'argent",
    [6042] = "ai chassé les chauves-souris pestiférées de la ferme pour que Nathanos le Flétrisseur puisse lancer ses chiens sur le Fléau sans être importuné",
    [6061] = "ai apprivoisé un trotteur des plaines adulte avec le bâtonnet de Yaw Sharpmane, un premier pas vers une bête bien à moi",
    [6062] = "ai soumis un sanglier tacheté redoutable près de [[Razor Hill]] avec le bâtonnet de domptage de Thotar, une première épreuve de commandement sur une bête",
    [6063] = "ai apprivoisé une rôdeuse Tissebois avec le bâtonnet de Dazalar, pour la leçon suivante de Dazalar",
    [6064] = "ai essayé un grand sanglier des rochers comme compagnon avec le bâtonnet de domptage de Grif Wildheart, pour voir quelle sorte de bête me convenait",
    [6082] = "ai maîtrisé un scorpide blindé, la dernière épreuve de Thotar, pour gagner le pouvoir d'apprivoiser et de commander la bête de mon choix",
    [6083] = "ai apprivoisé un clampant de l'écume au large de [[Echo Isles]] pour Thotar",
    [6084] = "ai gagné la confiance d'un léopard des neiges pour Grif Wildheart, un compagnon plus rapide et plus agile que le massif sanglier des rochers",
    [6085] = "ai apprivoisé un ours Griffeglace, la dernière épreuve de Grif Wildheart avant de m'accorder le pouvoir d'apprivoiser un familier fidèle de toute espèce",
    [6087] = "ai apprivoisé un traqueur des prairies pour Yaw Sharpmane, pour prendre sa nature rapide et intrépide et combattre comme un seul être avec une bête",
    [6088] = "ai fait descendre un rapace du ciel avec le bâtonnet de domptage, la dernière épreuve de Yaw Sharpmane avant de choisir un compagnon",
    [6101] = "ai apprivoisé un rôdeur sabre-de-nuit pour Dazalar, pour apprendre en quoi les créatures d'une nature changeante diffèrent les unes des autres",
    [6102] = "ai fait descendre un hurleur strigide du ciel, la dernière épreuve de Dazalar avant de choisir un compagnon de la terre, de l'eau ou du ciel",
    [6122] = "ai puisé de l'eau dans la grotte près des chutes de la Bondissante, en évitant les nagas, pour trouver le poison qui rendait malades les daims de [[Darkshore]]",
    [6123] = "ai rassemblé de la terrestrine et du champignon lunaire pour le baume qu'Alanndarian Nightsong préparerait pour les daims empoisonnés de [[Darkshore]]",
    [6124] = "ai soigné les daims malades de tout [[Darkshore]] avec le baume d'Alanndarian Nightsong, victimes d'une souillure qui gagnait la terre",
    [6127] = "ai puisé de l'eau au sommet du pic de Brume-funeste, sans doute souillée par la Lame ardente, pour remonter au poison qui rendait malades les gazelles",
    [6128] = "ai abattu des kodos pour leurs cornes et trouvé de la terrestrine, pour le baume de Tonga Runetotem contre les gazelles empoisonnées",
    [6129] = "ai soigné les gazelles malades du nord de [[Barrens]] avec le baume de Tonga Runetotem, pour donner de l'avance au remède",
    [6132] = "ai sorti Melizza Brimbuzzle de [[Valley of Spears]] avant que les centaures maraudine ne la mettent dans leur marmite",
    [6133] = "ai attaqué le pavillon des hauts-elfes de Quel'Lithien pour le registre de Quel'Thalas, pour Nathanos le Flétrisseur",
    [6134] = "ai attiré les fantômes magram de [[Valley of Bones]] vers des aimants fantômes pour leur fantôm-o-plasme, à revendre aux centaures",
    [6135] = "ai traqué Crépuscaile, la chauve-souris démoniaque albinos, pour la fourrure blanche dont Nathanos le Flétrisseur ferait une récompense",
    [6136] = "ai détruit Creusechair, la bête-asticot corpulente qui avait coûté à Nathanos le Flétrisseur des régiments entiers",
    [6142] = "ai extrait de la chair de praire près d'une épave sur la côte pour Mai'Lahii, l'appât de la pêche qui guérissait son mal de tête",
    [6143] = "ai vengé l'équipage de pêche de Drulzegar, massacré par les nagas Ondulame près de [[Ranazjar Isle]], dont il était le seul survivant",
    [6145] = "ai intercepté le courrier écarlate pour les ordres du Grand croisé, le rapport quotidien qui était la clé pour frapper la Croisade",
    [6146] = "ai mangé une pomme pourrie pour passer pour $gun:une; $gcroisé:croisée; à [[Tyr's Hand]] et livrer des ordres modifiés, une ruse pour démasquer l'Oracle écarlate",
    [6148] = "ai traqué Demetria, l'Oracle écarlate et principale conseillère du Grand croisé, sur la route de [[Tyr's Hand]]",
    [6161] = "ai trouvé les clés d'argent et d'or de Rackmore et ouvert le coffre au trésor qu'il avait caché sur [[Ranazjar Isle]]",
    [6163] = "ai tué Ramstein Grandgosier, l'abomination qui avait terrassé Nathanos le Flétrisseur, pour le venger",
    [6164] = "suis $gallé:allée; chercher le livre de comptes d'Augustus le Touché dans sa chambre à l'auberge, pour qu'il puisse rouvrir boutique à [[Terrordale]]",
    [6185] = "ai parcouru les Maleterres en quête de nouvelles du Flétrisseur et des agents du SI:7 disparus, que Flint Shadowmore craignait morts",
    [6186] = "ai appris au généralissime Bolvar Fordragon que Nathanos Marris, autrefois noble seigneur forestier, était devenu le Flétrisseur des Réprouvés",
    [6187] = "ai rassemblé une armée pour détruire Nathanos le Flétrisseur, le seigneur forestier humain devenu champion des Réprouvés",
    [6281] = "ai porté par les airs la note de l'intendant Lewis à Osric Strang à [[Stormwind City]], une demande d'armures car les réserves de [[Sentinel Hill]] s'épuisaient",
    [6282] = "ai décimé les harpies Rougefurie de [[Stonetalon Mountains]] pour [[name:Maggran Earthbinder]], qui craignait qu'elles ne se répandent dans tout Kalimdor",
    [6283] = "ai tué [[name:Bloodfury Ripper]], presque une reine pour les harpies, pour que leur nombre diminue enfin",
    [6284] = "ai tué [[name:Besseleth]], la vieille araignée du canyon de Sishir, pour que les voyageurs puissent venir à [[Sun Rock Retreat]] sans crainte",
    [6285] = "ai rapporté la caisse d'armures d'Osric à l'intendant Lewis pour les combattants et les combattantes de [[Sentinel Hill]]",
    [6301] = "ai ramassé des graines de Gaea à [[Mirkfallon Lake]] pour que [[name:Tammra Windfield]] les bénisse, afin de commencer à guérir la terre ravagée",
    [6323] = "ai porté par les airs la commande de Podrig à Gordon Wendham à [[Undercity]], pour des armes qui remplaceraient celles que les gardes de la Mort avaient perdues",
    [6324] = "ai rapporté la caisse d'armes de Gordon au garde de la Mort Podrig, pour que les gardes de [[The Sepulcher]] ne soient pas pris au dépourvu",
    [6342] = "me suis $grendu:rendue; en vol à [[Auberdine]] avec les arêtes et les écailles de poisson de Nessa pour Laird, afin de comparer les prises de [[Teldrassil]] à celles du continent",
    [6343] = "ai rapporté à Nessa Shadowsong la réponse de Laird, qui soupçonnait l'arbre-monde de faire grandir autant les poissons là-bas",
    [6362] = "ai porté par les airs un ballot de peaux de [[Barrens]] à Ahanu à [[Thunder Bluff]], qui en ferait des articles de cuir",
    [6364] = "ai rapporté par les airs les articles de cuir d'Ahanu à Jahan Hawkwing, pour les vendre aux chasseurs qui se pressaient à [[Crossroads]]",
    [6381] = "ai planté des graines de Gaea enchantées au cœur de [[Charred Vale]], pour aider le cycle de la vie à revenir sur la terre brûlée",
    [6384] = "ai porté par les airs les meilleurs morceaux de viande de Zargh à son amie Gryshka, l'aubergiste de [[Orgrimmar]]",
    [6386] = "ai rapporté à Zargh la lettre de remerciement de Gryshka, qu'il a prise pour la preuve qu'elle aimait ses steaks",
    [6389] = "ai forcé le tonneau de termites dans la scierie de Nordcrête et échappé à la nuée, ce qui a permis au père de Nathaniel Dumah de reposer",
    [6390] = "ai lâché les termites dans la scierie de Nordcrête pour Mickey Levine, pour ruiner le travail de la Croisade écarlate",
    [6391] = "ai porté par les airs la liste des meilleurs élèves mineurs de Brock Stoneseeker à [[Ironforge]], où les attendaient leurs pioches d'honneur",
    [6392] = "ai rapporté par les airs les pioches d'honneur à Brock Stoneseeker pour ses élèves mineurs, impatients de les essayer sur le minerai de [[Loch Modan]]",
    [6393] = "ai détruit des élémentaires de feu à [[Charred Vale]] pour [[name:Tsunaman]], dont le Tribunal des marées faisait la guerre à ses cousins de flamme",
    [6401] = "ai annoncé à [[name:Tammra Windfield]] que sa nièce Kaya avait survécu à l'attaque de son village",
    [6403] = "me suis $gtenu:tenue; aux côtés du maréchal Reginald Windsor quand il a démasqué dame Prestor, qui était Onyxia, et donné sa vie pour libérer [[Stormwind City]] de son sortilège",
    [6421] = "ai exploré la grotte des kobolds de [[Boulderslide Ravine]] à la recherche de cristaux de résonite, pour que [[name:Mor'rogal]] sache quel mal rôdait en dessous",
    [6441] = "ai rassemblé des cornes de satyre pour [[name:Pixel]], une marchande en route pour [[Ratchet]], où elles se vendaient très bien",
    [6442] = "ai rejeté à la mer les nagas Irequeue de [[Zoram Strand]], une terre que la Horde avait eu bien du mal à prendre",
    [6461] = "ai tué les araignées des mousses profondes qui pillaient la nuit les camps de Malaka'Jin pour voler le gibier des trolls",
    [6462] = "ai repris à [[Thistlefur Village]] les charmes sacrés des proches de [[name:Mitsuwa]], pris par les furbolgs qui les avaient tués sur la route",
    [6481] = "ai brisé le fût de résonite et tué Goggeroc, un terrestre que les kobolds avaient déterré, avant qu'il ne menace Kalimdor",
    [6482] = "ai escorté Ruul, le frère de [[name:Yama Snowhoof]], hors du camp Crin-de-Chardon, où les furbolgs l'avaient pris pour un ours et affamé",
    [6501] = "ai cherché de par le monde quelqu'un du sang des dragons capable de restaurer le fragment de l'Œil de dragon, la clé du repaire d'Onyxia",
    [6502] = "ai pris le sang du champion des dragons noirs au général Drakkisath, pour refaire l'amulette qui ouvre le repaire d'Onyxia",
    [6503] = "ai chassé [[les:Ashenvale Outrunner]] qui espionnaient les défenses de la Horde, pour aveugler l'Alliance avant qu'elle ne puisse attaquer",
    [6504] = "ai retrouvé les pages éparses d'un manuel de déchiqueteur pour [[name:Gurda Ragescar]], qui ne pouvait pas faire marcher le nouveau déchiqueteur sans elles",
    [6523] = "ai escorté Kaya Flathoof jusqu'à [[Camp Aparaje]] après son sauvetage, pour que son père Makaba la sache en sécurité",
    [6543] = "ai porté les ordres de Kadrak aux éclaireurs Warsong de [[Ashenvale]] et rapporté leurs rapports pour la campagne de la Horde",
    [6544] = "ai combattu aux côtés des pillards de Torek dans leur attaque contre [[Silverwing Outpost]] et sa cheffe, Duriel Moonfire",
    [6548] = "ai tué des pillards Totem-sinistre pour [[name:Makaba Flathoof]], qui leur avait échappé de justesse quand ils avaient massacré son village",
    [6561] = "ai tué le seigneur du crépuscule Kelris, qui livrait des innocents à Aku'Mai dans un temple d'Elune déchu, et porté sa tête à Bashana Runetotem",
    [6563] = "ai arraché des saphirs d'Aku'Mai aux murs de [[Blackfathom Deeps]] avant que les nagas ne puissent se servir de leur pouvoir élémentaire",
    [6569] = "ai rassemblé des yeux de draconides noirs dans le haut du pic pour Myranda la Mégère, pour une illusion qui tromperait le gardien du vol noir",
    [6571] = "ai rassemblé lames de scie, corde, huile et haches pour [[Warsong Lumber Camp]], reprenant la corde et l'huile aux furbolgs et aux satyres",
    [6602] = "ai tué le général Drakkisath et rapporté son sang à [[name:Rexxar]], pour éveiller la clé du repaire d'Onyxia",
    [6610] = "ai rassemblé des œufs géants, de la chair de palourde et de l'emmental d'Alterac pour l'omelette aux palourdes de Dirge Quikcleave, le prix de leçons de cuisine exotique",
    [6621] = "ai planté la bannière de Karang sur le tertre totémique des Vile-sylve et l'ai tenue jusqu'à ce que le chef Murgut sorte se battre, et tombe sous mes coups",
    [6629] = "ai tué Grundig Darkcloud, qui avait mené l'attaque des Totem-sinistre contre le village de [[name:Makaba Flathoof]]",
    [6641] = "ai gardé [[name:Muglash]] pendant qu'il attirait [[name:Vorsha the Lasher]], l'hydre qui attaquait sans cesse Zoram'gar, et aidé à la tuer",
    [6661] = "ai attiré les rats de [[Deeprun Tram]] avec la flûte de Monty et les ai ramenés vivants, la seule façon pour que les brochettes de rat de son frère ne tournent pas",
    [6662] = "ai pris le tram avec une caisse de rats vivants pour le stand de brochettes de rat de Nipsy, avant qu'ils ne se gâtent",
    [6804] = "ai guéri les élémentaires d'eau pestiférés de [[Eastern Plaguelands]] avec l'aspect de Neptulon, et vaincu les éruptions rendues folles",
    [6805] = "ai vaincu les tempêtes de poussière et les grondeurs du désert de [[Silithus]], serviteurs de l'air et de la terre, pour prouver ma conviction au duc Hydraxis",
    [6821] = "ai tué le Gardien pyrogène, un serviteur du feu retenu à [[Blackrock Spire]], pour l'œil que voulait le duc Hydraxis comme preuve de ma force",
    [6822] = "ai affronté un seigneur du feu, un géant de lave, un chien du Magma et une éruption de lave dans [[Molten Core]], la vraie épreuve de force du duc Hydraxis",
    [6824] = "ai pris les mains de Lucifron, Sulfuron, Gehennas et Shazzrah dans [[Molten Core]], un terrible coup porté aux seigneurs du feu",
    [6844] = "ai porté la trouvaille incrustée à [[name:Umber]], archiviste du Cercle cénarien à [[Nighthaven]], dans l'espoir d'une fenêtre sur le passé",
    [6921] = "ai récupéré le noyau de la Brasse dans les ruines du sanctuaire de la Lune, pour que le Cercle terrestre sache ce que faisait le Marteau du crépuscule",
    [6922] = "ai apporté à [[name:Je'neu Sancrea]] l'étrange globe qui avait nourri le baron Aquanis à [[Blackfathom Deeps]], la preuve de ce qui l'avait corrompu",
    [6962] = "suis $gallé:allée; chercher des biscuits de pain d'épice et du lait glacé pour Grand-père Hiver, épuisé d'avoir salué les gens toute la journée",
    [6963] = "ai fouillé les neiges de [[Alterac Mountains]] à la recherche de l'agent des Gourmandises Fumebois parti chercher un chargement disparu de friandises du Voile d'hiver",
    [6981] = "ai porté à [[Ratchet]] un éclat luminescent inquiétant, où tournoyait une fumée, pour savoir ce que c'était",
    [6983] = "ai repris les friandises volées du Voile d'hiver à l'abominable Grinch, la créature qui avait changé Sacks en bonhomme de neige",
    [7003] = "ai essayé l'Ultra-réducteur gobelin de Zorbin Fandazzle sur les géants de [[Feralas]], un test qu'il préférait ne pas risquer lui-même",
    [7025] = "ai apporté à Grand-père Hiver des biscuits de pain d'épice et du lait glacé, une douceur bien méritée après une longue journée de salutations",
    [7042] = "ai cherché dans [[Alterac Mountains]] l'enquêteur disparu des Gourmandises Fumebois, envoyé à la recherche d'un chargement perdu de friandises de fête",
    [7043] = "ai traqué l'abominable Grinch, qui avait volé les friandises du Voile d'hiver des Gourmandises Fumebois et changé le pauvre Sacks en bonhomme de neige",
    [7061] = "ai porté un livre des anciennes légendes du Voile d'hiver à Cairne Bloodhoof, qui voulait que le savoir de son peuple reste vivant",
    [7063] = "ai apporté un livre sur la fête du Voile d'hiver au roi Magni Bronzebeard, heureux de voir les vieilles légendes encore en mémoire",
    [7321] = "ai chassé les claquemâchoires du lac Lordamere pour de la viande de tortue, pour que Christoph Jeffcoat partage sa recette secrète de bisque de tortue apaisante",
    [7383] = "ai rempli une fiole au puits de lune de l'Arbre de l'oracle, le premier et le plus puissant de [[Teldrassil]], tandis que Corithras racontait le refus des dragons",
    [7429] = "ai défait les chaînes de [[name:Knot Thimblejack]] dans l'aile Gordok",
    [7441] = "ai poursuivi le diablotin Pusillin à travers le quartier de Crochebois pour reprendre le livre des incantations volé à Azj'Tordin",
    [7461] = "ai détruit Immol'thar dans sa prison et achevé le prince Tortheldrin, pour que reposent les esprits d'Eldre'Thalas",
    [7463] = "ai extrait l'essence d'Hydrogénos, une anomalie de l'aile est que le gardien du savoir Lydros voulait cataloguer, pour un petit sort utile",
    [7481] = "ai fouillé [[Dire Maul]] à la recherche de Kariel Winthalus, un maître elfe qui s'était enfui avec des artefacts anciens, pour n'apprendre que leur perte",
    [7482] = "ai parcouru [[Dire Maul]] à la recherche du maître elfe disparu Kariel Winthalus et du savoir qu'il portait, sans trouver trace de lui",
    [7483] = "ai apporté au gardien du savoir Lydros le libram de rapidité et des composants coûteux, pour un arcanum qui donne à une armure un peu de hâte",
    [7484] = "ai trouvé le libram de focalisation, perdu quelque part dans cette aile, pour que le gardien du savoir Lydros puisse en tirer son arcanum",
    [7485] = "ai rendu au gardien du savoir Lydros le libram de protection, dont la perte avait fait pleurer son propriétaire comme un nourrisson, pour un arcanum",
    [7488] = "ai arrêté la mage elfe de sang Lethtendris et pris son filet, qui prenait au piège la magie de [[Dire Maul]], avant qu'il ne fasse des dégâts durables",
    [7489] = "ai vaincu Lethtendris, qui voulait retourner contre ses ennemis la magie souillée de [[Dire Maul]], et rapporté son filet à [[name:Talo Thornhoof]]",
    [7495] = "ai présenté la tête d'Onyxia au généralissime Bolvar Fordragon, longtemps sous son regard, et vu l'honneur de [[Stormwind City]] restauré",
    [7507] = "ai rapporté à l'Athenaeum le guide du tueur de dragons de Foror, son sceau brisé",
    [7508] = "ai présenté au gardien du savoir Lydros une lame elfique émoussée, à chauffer au souffle d'un dragon et à tremper dans son sang",
    [7509] = "ai laissé le souffle d'Onyxia chauffer la lame ancienne, puis l'ai tuée et ai planté la lame dans son cadavre pour forger Quel'Serrar",
    [7632] = "ai cherché le propriétaire d'une ancienne feuille pétrifiée qui luisait de vert, de quelque chose de vieux et de puissant",
    [7634] = "ai tué un dragon bleu adulte pour son tendon, pour que Hastat l'Ancien lie sa feuille en un carquois comme on n'en avait pas vu depuis dix mille ans",
    [7635] = "ai tué un dragon noir adulte pour son tendon, pour que Stoma l'Ancien enchante une corde d'arc presque indestructible",
    [7636] = "ai affronté $gseul:seule; les quatre corrupteurs démoniaques de la Légion ardente, pour leurs têtes et le bâton de Vartrus l'Ancien",
    [7637] = "ai acheté l'encensoir d'exorcisme du grand prêtre Rohan par un généreux don, un premier sacrifice sur la route d'un destrier",
    [7640] = "ai chassé de [[Terrordale]] les esprits tourmentés avec l'encensoir d'exorcisme, leur infligeant le jugement de la Lumière",
    [7642] = "ai réuni étoffe runique, arcanite, larmes d'Arthas, eau bénite et une somme rondelette pour que Grimand Elmore fasse le caparaçon d'un destrier",
    [7643] = "ai tué [[name:Tendris Warpwood]] à [[Dire Maul]] pour libérer l'ancien esprit équin, et l'ai apaisé pour qu'il bénisse le caparaçon",
    [7645] = "ai payé Merideth Carlson, que la Main d'argent avait autrefois traitée de folle, en or et en biscuits de manne pour son fourrage de cheval spirituel",
    [7646] = "ai trouvé un diamant d'Azeroth et un diamant noir parfait pour le seigneur Grayson Shadowbreaker, les dernières pièces d'un clairvoyant",
    [7647] = "ai vaincu le chevalier de la mort Darkreaver dans le grand ossuaire de [[Scholomance]] pour racheter l'âme du destrier déchu qu'il montait",
    [7649] = "ai rendu un tome de l'Athenaeum au gardien du savoir Lydros, qui en a arraché la recette d'armure en plaques en remerciement",
    [7650] = "ai rapporté au gardien du savoir Lydros un deuxième tome de l'Athenaeum sur les armures en plaques de thorium enchanté, pour la page qu'il en a arrachée",
    [7651] = "ai rendu le troisième volume sur les armures en plaques de thorium enchanté au gardien du savoir Lydros, son gardien légitime, pour la recette qu'il contenait",
    [7701] = "ai tué le surveillant Maltorius, le traître de la Confrérie du thorium qui commandait l'équipe Sombrefer du Puits des scories, pour la prime",
    [7703] = "ai repris le gantelet de puissance gordok au prince Tortheldrin",
    [7704] = "ai apporté l'énorme oreiller orné de la femme de chambre Pillaclencher à Evonice Sootsmoker, ravie de le récupérer",
    [7721] = "ai rassemblé des noyaux d'élémentaires d'eau le long de [[The Forgotten Coast]] pour alimenter l'Ultra-réducteur de Zorbin Fandazzle et éclaircir les élémentaires",
    [7722] = "ai repris les plans secrets du flux embrasé de la Confrérie du thorium, volés par le traître Maltorius et emportés dans le Puits des scories",
    [7723] = "ai cogné les golems de guerre lourds autour du Chaudron pour Hansel Heavyhands, dont les doigts avaient trop gonflé pour qu'il se batte",
    [7724] = "ai tué les grandes araignées de lave cracheuses de feu qui inquiétaient les enfants, une tâche que m'avait confiée Hansel Heavyhands",
    [7725] = "ai réduit d'autres géants de [[Feralas]] à leur juste taille pour Zorbin Fandazzle, qui promettait de faire passer le mot à ses amis gobelins",
    [7726] = "ai arraché d'autres noyaux aux élémentaires des mers pour Zorbin Fandazzle, qui peinait toujours à monter boutique sur [[The Forgotten Coast]]",
    [7727] = "ai débarrassé les bassins de lave du Puits des scories de leurs incendosaures pour que la Confrérie du thorium puisse y envoyer ses équipes",
    [7728] = "ai repris une tuyère de forge et la longue-vue d'un guetteur que les Sombrefer avaient volées à la Confrérie du thorium",
    [7729] = "ai décimé les sous-chefs et les esclavagistes Sombrefer de [[Searing Gorge]] pour le sous-chef Scrange, pour qu'il se débarrasse de la concurrence",
    [7730] = "me suis $genfoncé:enfoncée; dans [[The Writhing Deep]] pour décimer les insectes zukk'ash qui rendaient les gnolls fous furieux contre [[Camp Mojache]]",
    [7731] = "ai tué Fouet-dard, un insecte géant de [[The Writhing Deep]], et prélevé ses glandes pour que Hadoken Swiftstrider les étudie",
    [7732] = "ai porté le rapport de [[Camp Mojache]] sur les Zukk'ash à Zilzibin Drumlore à [[Orgrimmar]], un expert de ces créatures venues d'ailleurs",
    [7733] = "ai pris les peaux des yétis plus coriaces de [[Rage Scar Hold]] pour Pratt McGrubben, une source encore meilleure pour son travail du cuir",
    [7734] = "ai bravé les yétis de [[Rage Scar Hold]] pour des peaux que Jangdor Swiftstrider s'attendait à trouver plus dures encore une fois traitées",
    [7735] = "ai apporté à Pratt McGrubben une peau de yéti intacte, peut-être la plus belle qu'il ait vue, dont il comptait faire quelque chose de spécial",
    [7738] = "ai offert à Jangdor Swiftstrider une peau de yéti parfaite, le plus beau spécimen qu'il ait jamais vu, pour en faire quelque chose de spécial",
    [7761] = "ai trouvé la marque que gardait le général Drakkisath, pour porter la Marque de Drakkisath qui ouvre le chemin de l'Aile noire",
    [7781] = "ai déposé la tête de Nefarian, seigneur de Blackrock, devant le généralissime Bolvar Fordragon, une victoire que l'Alliance n'avait pas connue depuis des années",
    [7786] = "ai apporté les liens du Cherchevent, de l'élémentium et l'essence du Seigneur du feu pour que le généralissime Demitrian libère Thunderaan",
    [7787] = "ai forcé le menteur généralissime Demitrian, après la défaite du Cherchevent, à éveiller la lame endormie Thunderfury",
    [7788] = "ai défendu le Fort d'Aile-argent dans [[Warsong Gulch]] contre la Horde, qui abattait la forêt sacrée pour ses machines de guerre",
    [7789] = "ai combattu les Sentinelles d'Aile-argent dans [[Warsong Gulch]], pour une Horde qui comptait exploiter les bois de [[Ashenvale]]",
    [7815] = "ai tué les claquemâchoires d'eau salée qui volaient sans cesse les appâts de Katoom le Pêcheur, un service rendu aux pêcheurs de [[Revantusk Village]]",
    [7816] = "ai traqué Gammerita, la cheffe voleuse des claquemâchoires d'eau salée, pour arracher de son estomac le meilleur leurre de Katoom le Pêcheur",
    [7828] = "ai traqué les loups Crins-d'argent qui guettaient les chasseurs des Vengebroche, qui avaient perdu bien des trolls courageux à cause d'eux",
    [7829] = "ai tué les sauvages chouettards dont les griffes et les becs avaient coûté aux Vengebroche bien des bons guerriers",
    [7830] = "ai abattu un seigneur céleste Tranchebec pour le veneur Markhor, qui se demandait combien de ses chasseurs le vieux griffon avait dévorés",
    [7838] = "ai gagné une douzaine de breloques de maître de l'arène dans l'arène des Gurubashi, assez pour en être $gnommé:nommée; grand maître",
    [7839] = "ai repris aux Vilebranch les outils volés du forgeron Slagtree, un cadeau du gnome qui lui avait sauvé la vie dans sa jeunesse",
    [7840] = "suis $gallé:allée; chercher le déjeuner de Lard à son coin de pique-nique secret sur l'île au nord, d'où les Vilebranch l'avaient chassé",
    [7841] = "ai massacré les hauts-elfes de Hautval au pavillon de Quel'Danil, un message de sang aux Wildhammer pour leur nouvelle alliance",
    [7842] = "ai tué les griffons de [[Hinterlands]] pour leurs longues plumes, la suite du message d'Otho Moji'ko aux Wildhammer",
    [7843] = "ai planté la lance ensanglantée d'Otho Moji'ko près du puits au cœur de [[Aerie Peak]], le dernier message aux Wildhammer",
    [7844] = "ai détruit des scalpeurs et des devins Vilebranch pour le mystique Yayo'jin, une tribu dépravée qui se nourrit d'autres trolls",
    [7845] = "ai gravi [[Jintha'Alor]] pour trouver l'ancien Défense-brisée, le compagnon de la primordiale Défense-brisée, enlevé lors d'un raid pour être sacrifié à Hakkar",
    [7846] = "ai tué Hitah'ya la Gardienne pour la clé des chaînes de l'ancien Défense-brisée, le libérant pour qu'il rentre à [[Revantusk Village]]",
    [7848] = "ai récupéré un fragment du Magma dans [[Blackrock Depths]], pour que Lothos Riftwaker puisse ouvrir la faille vers la gueule du seigneur du feu",
    [7849] = "ai repris les os du frère jumeau du veneur Markhor aux limons et aux loups Vilebranch, pour sauver au moins son âme",
    [7850] = "ai volé les réceptacles de sang souillé de [[Jintha'Alor]], la magie du dieu du sang qui poussait les Vilebranch à la férocité et à la folie",
    [7861] = "ai tué la prêtresse infâme Hexx et sa garde aman'zasi au sommet de [[Jintha'Alor]], un coup terrible pour les Vilebranch",
    [7862] = "ai abattu des berserkers, des chasseurs des ombres, des buveurs de sang et des mange-âmes Vilebranch pour postuler au poste de capitaine de la garde des Vengebroche",
    [7871] = "ai repoussé la Horde loin du Fort d'Aile-argent dans [[Warsong Gulch]], pour épargner les arbres de la forêt sacrée",
    [7872] = "ai combattu la Horde dans [[Warsong Gulch]] pour les Sentinelles d'Aile-argent, dont la forêt sacrée tombait pour des machines de guerre",
    [7873] = "ai défendu le Fort d'Aile-argent dans [[Warsong Gulch]] contre la Horde, qui abattait la forêt sacrée pour ses machines de guerre",
    [7874] = "ai abattu les Sentinelles d'Aile-argent dans [[Warsong Gulch]], qui voulaient empêcher la Horde d'exploiter les bois de [[Ashenvale]]",
    [7875] = "ai combattu l'Alliance dans [[Warsong Gulch]] pour les Voltigeurs Warsong, pour que la Horde continue d'abattre les arbres de [[Ashenvale]]",
    [7876] = "ai combattu les Sentinelles d'Aile-argent dans [[Warsong Gulch]], pour une Horde qui comptait exploiter les bois de [[Ashenvale]]",
    [7881] = "ai fabriqué des bottes de forain pour la foire de Sombrelune, en échange de ses tickets",
    [7882] = "ai cousu de robustes tuniques de cuir pour la foire de Sombrelune en échange de ses tickets",
    [7883] = "ai apporté à la foire de Sombrelune des pièces de costume pour le plus grand gnome du monde, si l'on en trouvait jamais un assez grand",
    [7884] = "ai fabriqué ce dont la foire de Sombrelune avait besoin pour son numéro de l'enfant crocilisque et du murloc barbu",
    [7885] = "ai fourni à la foire de Sombrelune des renforts d'armure, dont un parfait pour rapiécer une déchirure dans une tente",
    [7889] = "ai fabriqué des cailloux grossiers pour la foire de Sombrelune, ni trop lourds ni trop légers pour se faire des muscles",
    [7890] = "ai apporté des silex à aiguiser lourds à un employé de la foire qui comptait se faire des muscles en les soulevant",
    [7894] = "ai fabriqué des modulateurs en cuivre pour une construction secrète de la foire de Sombrelune",
    [7895] = "ai bricolé des bidules bourdonnants en bronze pour un stand de la foire censé être la merveille du monde",
    [7896] = "ai fabriqué des fusées vertes pour annoncer qu'un stand de la foire de Sombrelune était prêt, quel que soit le jour où il le serait",
    [7897] = "ai fourni des trousses de réparation mécanique pour que le bricoleur de la foire puisse tout remettre en marche",
    [7898] = "ai fabriqué des rouages en thorium pour Yebb, un gnome malin et peut-être retors de la foire de Sombrelune",
    [7899] = "ai rassemblé de petites pattes en fourrure pour des jouets et des babioles qui attireraient plus de visiteurs à la foire",
    [7900] = "ai rassemblé des peaux d'ours déchirées à coudre en peluches pour la foire, que tous les enfants d'Azeroth envieraient",
    [7901] = "ai rapporté des queues fournies et soyeuses, des prix pour rendre heureux les visiteurs de la foire et leur faire amener leurs amis",
    [7902] = "ai rassemblé des plumes vibrantes pour enflammer l'imagination au spectacle de la foire de Sombrelune",
    [7903] = "ai chassé des chauves-souris pour leurs yeux maléfiques, de quoi effrayer les visiteurs de la foire de Sombrelune",
    [7907] = "ai rapporté à la foire de Sombrelune une suite complète de cartes de Fauves, comme me l'avait demandé une mystérieuse neuvième carte",
    [7927] = "ai présenté à la foire la suite de Portails complète pour l'une de ses cartes majeures, comme le demandait la neuvième carte de la suite",
    [7928] = "ai rapporté à la foire de Sombrelune la suite de Seigneurs de guerre achevée",
    [7929] = "ai remis à la foire de Sombrelune une suite complète de cartes d'Élémentaires, dont la neuvième carte promettait une récompense",
    [7937] = "ai suivi la bonne fortune prédite par Sayge jusqu'à une meule de foin près de l'écurie de [[Eastvale Logging Camp]], où était caché un coffret",
    [7938] = "ai suivi une prédiction jusque dans [[The Deadmines]], à travers un portail scintillant, jusqu'à un étrange coffre contenant un coffret",
    [7944] = "ai cherché fortune au cœur de [[Wailing Caverns]], où un étrange coffre est apparu au-delà d'un portail scintillant",
    [7945] = "ai suivi une prédiction jusqu'à une souche d'arbre devant [[Palemane Rock]], [[at:Mulgore]], où était caché un coffret",
    [8149] = "ai déposé un tribut de la fête des moissons au tombeau d'Uther, dans [[Western Plaguelands]], en l'honneur du sacrifice d'Uther le Porteur de Lumière",
    [8150] = "ai déposé un tribut de la fête des moissons au monument de Grom, dans [[Demon Fall Canyon]], en l'honneur de la force et du sacrifice de Grom Hellscream",
    [8153] = "ai chassé les coursiers sabot-de-mousse pour des ramures parfaites, signe d'une confiance suprême, pour le charme de chasseur d'Ogtinc",
    [8222] = "ai rassemblé du sang de scorpide luminescent pour une peinture qui changerait la camelote en trésors luisants à la foire",
    [8231] = "ai pisté les vandales des flots le long de la côte de [[Azshara]] pour des écailles qui reflètent la force d'un chasseur, pour le charme d'Ogtinc",
    [8232] = "ai tué le drake vert Morphaz dans [[Sunken Temple]] avec d'autres, pour le dernier trophée du charme d'Ogtinc",
    [8251] = "ai arraché de la poussière lumineuse aux elfes de sang de [[Azshara]], qui avaient tué l'apprenti de l'archimage Xylem venu commercer avec eux",
    [8252] = "ai arraché du corail enchanté aux sirènes Fouette-bile, qui en avaient dépouillé la baie, pour les recherches de l'archimage Xylem",
    [8253] = "ai tué le drake vert Morphaz dans [[Sunken Temple]] pour le fragment d'arcane dans son estomac, avalé en même temps que l'apprenti de l'archimage Xylem",
    [8277] = "ai rassemblé des dards et des crocs pour que [[name:Beetix Ficklespragg]] tente de préparer un antidote pour son cousin [[name:Noggle Ficklespragg]], empoisonné",
    [8278] = "ai rapporté des échantillons de venin des créatures les plus redoutables du grand sud pour l'antidote de [[name:Noggle Ficklespragg]], qui l'a enfin remis sur pied",
    [8279] = "ai arraché aux gardiens du crépuscule les trois chapitres du Lexique du crépuscule, pour que l'ermite Ortell puisse déchiffrer la tablette",
    [8280] = "ai décimé [[les:Dredge Striker]] qui avaient ravagé une cargaison de grain-du-lendemain, pour garder ouvertes les lignes de ravitaillement de [[Cenarion Hold]]",
    [8281] = "ai tué [[des:Dredge Crusher]] avant que les vers plus gros du sud ne prennent la place des frappeurs le long des lignes de ravitaillement du fort",
    [8282] = "ai retrouvé la sacoche de réactifs rares que [[name:Noggle Ficklespragg]] avait perdue en fuyant [[name:Deathclasp]], sans laquelle le fort ne pouvait préparer aucune potion",
    [8283] = "ai traqué [[name:Deathclasp]], terreur des sables, pour ouvrir par les montagnes du sud un chemin contournant les ruches silithides",
    [8284] = "ai fouillé les ruines d'un camp du Marteau du crépuscule à la recherche de morceaux d'une tablette d'argile, pour comprendre ce que le culte faisait [[at:Silithus]]",
    [8285] = "ai cherché l'ermite Ortell, un déserteur du Marteau du crépuscule caché dans les montagnes, pour obtenir son aide avec la tablette",
    [8286] = "me suis $grendu:rendue; à [[Caverns of Time]] pour un Guetteur du Bronze, afin de savoir si [[name:Anachronos]] s'était relevé",
    [8287] = "ai remis la tablette déchiffrée au commandant Mar'alith, jetant un peu de lumière sur ce que le Marteau du crépuscule faisait [[at:Silithus]]",
    [8288] = "ai tué [[name:Broodlord Lashlayer]], qui garde le chemin du sanctuaire de Nefarian, et rapporté sa tête à Baristolth",
    [8290] = "ai repoussé la Horde loin du Fort d'Aile-argent dans [[Warsong Gulch]], pour épargner les arbres de la forêt sacrée",
    [8291] = "ai combattu la Horde dans [[Warsong Gulch]] pour les Sentinelles d'Aile-argent, dont la forêt sacrée tombait pour des machines de guerre",
    [8294] = "ai abattu les Sentinelles d'Aile-argent dans [[Warsong Gulch]], qui voulaient empêcher la Horde d'exploiter les bois de [[Ashenvale]]",
    [8295] = "ai combattu l'Alliance dans [[Warsong Gulch]] pour les Voltigeurs Warsong, pour que la Horde continue d'abattre les arbres de [[Ashenvale]]",
    [8301] = "ai prouvé à la Progéniture de Nozdormu que j'avais l'étoffe d'un héros, avec [[des:Silithid Carapace Fragment]] arrachés aux silithides des trois ruches",
    [8302] = "ai arraché deux cents [[pl:Silithid Carapace Fragment]] de plus aux ruches, chaque chargement me valant de Baristolth le droit de nommer un autre adjoint",
    [8304] = "ai interrogé les nains de [[Bronzebeard Encampment]] pour le commandant Mar'alith, dont la bien-aimée Natalia avait disparu",
    [8305] = "ai contemplé la Larme cristalline près de la barrière sacrée, souvenir de tout ce qui avait été perdu pendant la guerre des Sables changeants",
    [8306] = "me suis $gaventuré:aventurée; dans [[Hive'Regal]] à la recherche de Natalia, la bien-aimée du commandant Mar'alith, et y ai trouvé le monstre que C'Thun avait fait d'elle",
    [8307] = "ai fouillé le camp du Marteau du crépuscule à l'ouest de [[Cenarion Hold]] pour savoir comment ils rendaient mangeable l'amère viande de ver des sables",
    [8308] = "ai porté la lettre perdue de Brann Bronzebeard à son ancien camp, avec la nouvelle d'un tunnel vers Ahn'Qiraj et une prière pour son singe",
    [8309] = "ai relevé des empreintes des cristaux à glyphes des trois ruches, dans l'espoir qu'ils expliquent pourquoi les ruches vomissaient des insectes",
    [8310] = "ai rassemblé un cerveau de chaque sorte de silithide des ruches pour l'élixir de [[name:Frankal Stonebridge]], censé aider à lire les glyphes",
    [8311] = "suis $gallé:allée; quémander des bonbons dans les auberges des capitales pour Jesper, un enfant de l'orphelinat de [[Stormwind City]] trop malade pour y aller",
    [8312] = "ai quémandé des bonbons pour Spoops, un enfant malade de l'orphelinat de [[Orgrimmar]], et fait tous les tours que les aubergistes me demandaient",
    [8313] = "ai apporté la page de recette déchirée à Calandrath, qui saurait comprendre les noms que le Marteau du crépuscule donnait aux herbes du désert",
    [8314] = "ai porté le prisme de cristal orné de glyphes à la géologue Larksbane, dans l'espoir qu'elle saurait percer les messages qu'il cachait",
    [8315] = "ai tracé les glyphes d'appel à [[Bones of Grakkarond]] et tué l'émissaire qiraji qui est venu, pour la clé des cristaux",
    [8317] = "ai cuisiné des boulettes du désert fumées pour Calandrath d'après la recette du Marteau du crépuscule, qui se sont révélées étonnamment bonnes",
    [8318] = "ai pris des textes cryptés aux fidèles du Marteau du crépuscule pour [[name:Bor Wildmane]], afin que leurs ordres secrets circulent moins",
    [8320] = "ai frappé les têtes du serpent, [[les:Twilight Geolord]] qui menaient les rituels du culte dans les camps de [[Silithus]]",
    [8321] = "ai tué [[name:Vyral the Vile]], chef du Marteau du crépuscule dans la grotte de [[Twilight's Run]], sa chevalière pour preuve",
    [8322] = "me suis $gbattu:battue; jusqu'à l'auberge de [[Southshore]] pour jeter des œufs pourris dans sa grande cuve, gâchant pour des semaines la précieuse bière des humains",
    [8323] = "ai rassemblé les bulletins codés du culte pour l'ermite Ortell, qui voulait savoir si son ancien ordre le traquait encore",
    [8332] = "ai gagné des blasons sur des templiers abyssaux pour qu'Aurel Goldleaf forge un médaillon du culte capable de tromper le Conseil abyssal",
    [8341] = "ai trouvé des éclats et des chevalières pour l'anneau de seigneur d'Aurel Goldleaf, un déguisement pour attirer un seigneur abyssal dans une embuscade",
    [8348] = "ai invoqué l'un des ducs abyssaux et l'ai détruit, sa chevalière portée à [[name:Bor Wildmane]] pour ébranler les sous-fifres du culte",
    [8352] = "ai abattu un seigneur du Conseil abyssal avec une troupe prête au combat, son sceptre rapporté à [[name:Bor Wildmane]] pour preuve",
    [8353] = "ai caqueté comme une poule devant Firebrew l'aubergiste pour un bonbon à la menthe de [[Ironforge]], une douceur pour la Sanssaint d'un enfant malade",
    [8354] = "ai caqueté comme une poule pour Norman l'aubergiste, le prix d'un bonbon à la menthe de [[Undercity]] pour un enfant malade",
    [8355] = "ai imité le bruit d'un train devant Talvash del Kissel pour une boule de gomme de [[Gnomeregan]] destinée à un enfant malade",
    [8356] = "ai montré mes muscles à l'aubergiste Allison pour gagner du nougat de [[Stormwind City]] pour la Sanssaint d'un enfant malade",
    [8357] = "ai dansé pour Saelienne l'aubergiste en échange de massepain de [[Darnassus]] pour un enfant malade",
    [8358] = "ai fait le train pour Kali Remik à [[Sen'jin Village]] pour gagner une boule de gomme darkspear pour un enfant malade",
    [8359] = "ai montré mes muscles à Gryshka l'aubergiste, qui voulait une démonstration de force avant de donner du nougat de [[Orgrimmar]] pour un enfant malade",
    [8360] = "ai dansé pour Pala l'aubergiste à [[Thunder Bluff]], le prix du massepain de [[Thunder Bluff]] pour un enfant malade",
    [8361] = "ai vaincu un templier abyssal, l'un des élémentaires qui donnaient leurs ordres au culte, pour semer le désordre dans sa chaîne de commandement",
    [8365] = "ai pris leurs chapeaux aux pirates des Mers du sud de [[Lost Rigger Cove]] pour la modiste hautaine, qui habillait rois et chefs de guerre",
    [8366] = "ai donné une leçon aux pirates des Mers du sud de [[Lost Rigger Cove]] pour Bilgewhizzle, puisqu'ils avaient cessé de payer la protection du Cartel",
    [8373] = "ai nettoyé [[Southshore]] des boules puantes réprouvées avec un détergent au pin pour le sergent Hartman, pendant la Sanssaint",
    [8414] = "ai rassemblé des pierres du Fléau sur les serviteurs du Fléau pour le grand prêtre Thel'danis à [[Uther's Tomb]], afin que leur mal soit dissipé",
    [8416] = "ai porté une pierre du Fléau purifiée au commandant Ashlam Valorfist, qui comptait baigner le Fléau d'un feu vertueux",
    [8418] = "ai pris des plumes vaudou aux prêtres trolls de [[Sunken Temple]], une magie pour forger une pierre de pouvoir sacrée contre les morts-vivants",
    [8423] = "ai tué des sangliers infernaux dans [[Blasted Lands]], l'épreuve de force que le Héros déchu de la Horde fixait avant de me confier une tâche honorable",
    [8424] = "ai massacré les Ombre-juré, dont les sombres rituels tourmentaient l'esprit du Héros déchu de la Horde",
    [8425] = "ai détruit les gardiens trolls de [[Sunken Temple]] pour des plumes vaudou qui prêteraient un instant un corps au Héros déchu de la Horde",
    [8446] = "ai cherché un druide pour déchiffrer un objet noyé dans les cauchemars, dont la corruption semblait liée aux dragons sortis du Rêve",
    [8447] = "ai attendu que le gardien Remulos purifie l'objet noyé dans les cauchemars dans [[Lake Elune'ara]], révélant un anneau de Malfurion",
    [8492] = "ai fondu des barres de cuivre pour le sergent Stonebrow à [[Ironforge]], du métal pour le matériel de guerre de l'Alliance contre [[Ahn'Qiraj]]",
    [8494] = "ai apporté des barres de fer à un caporal Carnes peu aimable, tandis que l'Alliance s'équipait pour la guerre de [[Ahn'Qiraj]]",
    [8496] = "ai fourni des bandages épais à [[Cenarion Hold]], dont les réserves de campagne étaient dangereusement basses après les dernières pertes",
    [8497] = "ai assemblé des trousses de survie d'eau, d'anti-venin et de boulettes, pour garder en vie dans le désert les nouvelles recrues du fort",
    [8498] = "ai intercepté les ordres de bataille portés par des prophètes du crépuscule bien gardés, pour que le commandant Mar'alith puisse anticiper les attaques du culte",
    [8499] = "ai fourni des barres de thorium à dame Twinbraid pour le bataillon de chars à vapeur que l'Alliance comptait transporter par les airs [[at:Silithus]]",
    [8501] = "ai abattu en plein vol [[des:Hive'Ashi Stinger]] lors de l'assaut de [[Cenarion Hold]] sur [[Hive'Ashi]]",
    [8502] = "ai tué [[des:Hive'Ashi Worker]] pour que les silithides peinent à réparer leur ruche une fois l'assaut passé",
    [8503] = "ai arraché de l'étouffante pour le soldat Draxlegauge, à qui il en fallait énormément pour l'effort de guerre de [[Ahn'Qiraj]]",
    [8505] = "ai cueilli du lotus pourpre pour maître Nightsong, des herbes pour la résistance de l'Alliance face à l'avancée impitoyable des silithides",
    [8507] = "ai servi sur le terrain avec la brigade de [[Ironforge]] du capitaine Blackanvil devant [[Hive'Zora]], avant de plus grandes tâches à [[Cenarion Hold]]",
    [8509] = "ai ramassé des larmes d'Arthas pour le sergent-major Germaine, sur des ordres pour l'effort de guerre de [[Ahn'Qiraj]] que personne n'expliquait",
    [8511] = "ai dépecé du cuir léger pour Bonnie Stoneflayer, dont la famille de dépeceurs le tannait pour le matériel de guerre de l'Alliance",
    [8513] = "ai apporté du cuir moyen au soldat Porter, qui notait chaque pièce rassemblée pour la guerre de [[Ahn'Qiraj]]",
    [8515] = "ai apporté du cuir épais à une Marta Finespindle tout excitée, à qui il en fallait des tonnes pour l'effort de guerre de [[Ahn'Qiraj]]",
    [8517] = "ai fait des bandages en lin pour la sentinelle Silversky, pour une guerre à [[Ahn'Qiraj]] qu'on annonçait longue et sanglante",
    [8519] = "ai assisté dans le cristal à un souvenir oublié de la guerre des Sables changeants, jusqu'à la trahison de Staghelm",
    [8520] = "ai roulé des bandages en soie pour l'infirmière Stonefield, pour que les soldats en route pour [[Ahn'Qiraj]] ne manquent de rien",
    [8522] = "ai donné des bandages en étoffe runique à la gardienne Moonshade, pour offrir à ceux qu'on envoyait à [[Ahn'Qiraj]] toutes les chances de survivre",
    [8524] = "ai pêché et cuisiné du thon arc-en-ciel pour Slicky Gastronome, de quoi nourrir les soldats de la guerre de [[Ahn'Qiraj]]",
    [8526] = "ai rôti du raptor pour Sarah Sadwhistle, une volontaire malgré elle qui stockait des vivres pour les soldats en route pour [[Ahn'Qiraj]]",
    [8528] = "ai pêché et cuisiné du jaune-queue tacheté pour les réserves de la chasseresse Swiftriver, des vivres qui tiendraient jusqu'au début de la guerre",
    [8532] = "ai fondu du minerai de cuivre en barres pour le mineur Cromwell à [[Orgrimmar]], du métal brut pour le matériel de guerre de la Horde",
    [8534] = "ai rejoint l'éclaireuse cénarienne Azenel au fond de [[Hive'Zora]] pour son rapport écrit sur les mouvements des silithides",
    [8535] = "ai invoqué et détruit [[un:Hoary Templar]], l'un des nobles élémentaires que vénère le Marteau du crépuscule",
    [8536] = "ai fait venir [[un:Earthen Templar]] et l'ai abattu, pour que le culte devant Ahn'Qiraj ne prenne pas le fort au dépourvu",
    [8537] = "ai trouvé le moyen d'invoquer [[un:Crimson Templar]] et l'ai tué, les nobles élémentaires du culte étant une menace trop grande pour être ignorée",
    [8538] = "ai attiré dans ce monde les ducs des Cendres, des Profondeurs, des Zéphyrs et des Éclats et les ai détruits, les principaux organisateurs du culte",
    [8539] = "ai abattu [[des:Hive'Zora Hive Sister]] avec les renforts appelés à l'assaut de [[Hive'Zora]]",
    [8540] = "ai procuré des bottes ornées en mithril à la division montée de la garde de [[Cenarion Hold]], qui en manquait",
    [8541] = "ai approvisionné la garde de [[Cenarion Hold]] en silex à aiguiser, denses, solides et lourds, qui lui faisaient défaut",
    [8542] = "ai fait des barres d'étain pour le grunt Maug, qui aurait préféré aiguiser des armes pour la guerre contre les insectes de [[Ahn'Qiraj]]",
    [8544] = "ai remis les manchettes de commandement qiraji à Andorgos, pour en faire des épaulières plus terribles que les ailes de Nefarian",
    [8545] = "ai extrait et fondu du mithril pour le sergent-chef T'kelah, des barres pour bâtir ce dont la Horde aurait besoin dans la guerre à venir",
    [8549] = "ai cueilli de la pacifique pour l'herboriste Proudfeather, à transformer en potions pour l'épreuve que la Horde allait affronter à [[Ahn'Qiraj]]",
    [8551] = "ai repris le coffre du capitaine Smotts à Gorlash, l'un des géants des mers qui avaient fait sombrer son navire et tué son équipage",
    [8552] = "ai rendu au capitaine Smotts une écharpe brodée HS, la preuve que Mok'rash, l'un des géants qui avaient coulé ses navires, était mort",
    [8554] = "ai appâté le géant Negolash avec des ailes de busard et du vin, puis l'ai tué pour récupérer le coutelas du capitaine Smotts",
    [8559] = "ai donné à Kandrostrasz les manchettes de commandement qiraji, une magie à faire hésiter un dragon, pour en faire des bottes",
    [8560] = "ai offert à Kandrostrasz la peau intacte d'Ouro, presque impénétrable et pourtant souple, pour en faire des jambières",
    [8561] = "ai présenté le diadème de Vek'nilash à Andorgos, usé par les murmures des empereurs jumeaux, pour en faire une couronne",
    [8562] = "ai déposé la carapace du Dieu très ancien devant Vethsera, la preuve que C'Thun était mort, pour une armure digne de qui a tué un dieu",
    [8575] = "ai porté le registre magique d'Azuregos, écrit dans une langue que personne ne savait lire, à Narain Soothfancy [[at:Tanaris]]",
    [8577] = "ai retrouvé Stewvul pour reprendre les lunettes de divination qu'il avait volées à son ex-meilleur ami, Narain Soothfancy",
    [8578] = "ai fouillé [[Molten Core]] à la recherche des lunettes de divination de Narain Soothfancy, perdues là un mois plus tôt par un curieux",
    [8580] = "ai ramassé de la fleur de feu pour le chevaucheur de chauve-souris Pele'keiki, qui devinait que la Horde la voulait pour des choses qui font boum",
    [8582] = "ai cueilli du lotus pourpre pour l'apothicaire Jezel, un composant des nombreuses potions dont la Horde aurait besoin à [[Ahn'Qiraj]]",
    [8585] = "ai tué le seigneur Lakmaeran sur [[Isle of Dread]] pour Dirge Quikcleave, qui comptait faire passer la bête pour un poulet de 500 livres",
    [8586] = "ai fourni à Dirge Quikcleave du carburant de fusée et du sel de Fonderoc pour ce qui est devenu ses côtelettes de chimaerok qui déménagent",
    [8587] = "ai rapporté le poulet de 500 livres de Dirge à Narain Soothfancy, qui s'est jeté dessus à pleines mains",
    [8588] = "ai dépecé du cuir lourd pour le dépeceur Jamani, pour les armures, les renforts et les simples bâches du matériel de guerre de la Horde",
    [8590] = "ai apporté du cuir épais au sergent Umala pour le matériel de guerre de la Horde, avec la gratitude de la Horde promise en retour",
    [8592] = "ai fait taire les murmures des empereurs jumeaux pour Andorgos, et lui ai apporté le diadème de Vek'nilash pour qu'il le change en couronne",
    [8593] = "ai apporté la peau intacte d'Ouro à Kandrostrasz pour me montrer digne des dragons, pour des jambières taillées dans la peau contre nature du ver",
    [8594] = "ai porté les manchettes des plus hauts chefs qiraji à Andorgos, qui en a fait des épaulières avec des écailles de Qiraji tombés",
    [8596] = "ai porté les manchettes de commandement qiraji à Kandrostrasz en échange de bottes pour aider à écraser les infâmes qiraji",
    [8597] = "ai nagé jusqu'à une île des mers du Sud pour le livre enterré de Narain Soothfancy, pour n'y trouver qu'une note à sa place",
    [8598] = "ai apporté à Narain Soothfancy la demande de rançon laissée par celui qui avait volé son livre",
    [8599] = "ai livré une lettre d'amour de Meridith, qui avait tiré Narain Soothfancy de son gyrocoptère écrasé, au gnome stupéfait",
    [8600] = "ai taillé du cuir robuste pour le docteur Serratus, juge sévère du couteau d'un dépeceur, pour l'effort de guerre de [[Ahn'Qiraj]]",
    [8602] = "ai échangé les manchettes de domination qiraji au dragon Andorgos contre des épaulières faites pour semer la peur chez les Qiraji",
    [8603] = "ai porté la carcasse du Dieu très ancien, un morceau de C'Thun abattu, à Vethsera, qui ne s'attendait à voir revenir personne",
    [8604] = "ai amassé des bandages en laine pour les trousses de secours du guérisseur Longrunner, puisque les soldats sur le terrain ne pouvaient compter sur un guérisseur",
    [8606] = "ai livré la rançon dans [[Winterspring]], $gdéguisé:déguisée;, un sac de cailloux contre de l'or, pour démasquer les voleurs du livre de Narain",
    [8607] = "ai fait des bandages en tisse-mage pour l'effort de guerre, pour dame Callow",
    [8609] = "ai donné des bandages en étoffe runique au garde-pierre Clayhoof pour les soldats qui affrontaient les silithides et la force qui les dirigeait",
    [8611] = "ai chassé des loups et cuisiné des steaks de loup pour le garde sanglant Rawtar, mis au sel pour nourrir les soldats de la Horde",
    [8613] = "ai pêché du jaune-queue tacheté pour le pêcheur Lin'do, chargé d'en rassembler une tonne pour la guerre de la Horde",
    [8615] = "ai fait cuire du saumon pour le chef Sharpclaw, un plat choisi pour sa bonne conservation et pour donner aux soldats la force de lever une hache",
    [8620] = "ai reconstitué les huit chapitres épars du Draconique pour les nuls après que le docteur Weavil avait déchiré le seul exemplaire de Narain",
    [8621] = "ai livré les manchettes des plus puissants qiraji à Kandrostrasz, qui a changé leur antique puissance en bottes",
    [8622] = "ai apporté la carapace du Dieu très ancien à Vethsera après que la mort de C'Thun avait sauvé Azeroth, pour une armure qui en porte la gloire et le fardeau",
    [8623] = "ai cédé le diadème de Vek'lor à Andorgos, que les empereurs jumeaux avaient pris à son frère Arygos, pour en faire une couronne",
    [8624] = "ai traîné la peau du Grand ver des sables jusqu'à Kandrostrasz pour des jambières contre les horreurs qui attendaient plus loin dans le temple",
